@Override
    public void renderEffect(long appliedAtWorldTime, int amplifier, LivingEntity livingEntity, float delta, MatrixStack matrixStack, VertexConsumerProvider vertexConsumers, int light) {
        if (livingEntity.getHealth() <= 0 || !livingEntity.isAlive()) { return; }
        var itemRenderer = MinecraftClient.getInstance().getItemRenderer();
        var camera =  MinecraftClient.getInstance().gameRenderer.getCamera();
        var direction = camera.getPos().subtract(livingEntity.getPos()).normalize().multiply(livingEntity.getWidth() * 0.5F);

        matrixStack.push();
        var verticalOffset = (livingEntity.getHeight() / livingEntity.getScale()) * 0.75F;
        matrixStack.translate(direction.x, verticalOffset, direction.z);

        matrixStack.multiply(RotationAxis.POSITIVE_Y.rotationDegrees(180F + (float)Math.toDegrees(Math.atan2(direction.x, direction.z)) ));
        matrixStack.multiply(RotationAxis.POSITIVE_X.rotationDegrees(camera.getPitch()));

        CustomModels.render(GLOWING_RENDER_LAYER, itemRenderer, modelId,
                matrixStack, vertexConsumers, light, livingEntity.getId());

        matrixStack.pop();
    }

public void render(PoseStack pMatrixStack, MultiBufferSource pBuffer, int pPackedLight, Player pLivingEntity, float pLimbSwing, float pLimbSwingAmount, float pPartialTicks, float pAgeInTicks, float pNetHeadYaw, float pHeadPitch) {
            float percent = getRenderPercent(pLivingEntity);
            if (percent > 0) {
                float f = (float) pLivingEntity.tickCount + pPartialTicks;
                float offset = Mth.sin(f * 2) * 0.75f * percent;
                pMatrixStack.translate(offset, 0, 0);
                pMatrixStack.scale(1.01f, 1.01f, 1.01f);
                int color = RenderHelper.colorf(.988f * percent, .313f * percent, .968f * percent, percent);
                this.getParentModel().renderToBuffer(pMatrixStack, pBuffer.getBuffer(RenderHelper.CustomerRenderType.magic(this.getTextureLocation(pLivingEntity))), LightTexture.FULL_BRIGHT, OverlayTexture.NO_OVERLAY, color);
            }
        }

@Override
        public void render(PoseStack poseStack, AbstractSpellCastingMob animatable, BakedGeoModel bakedModel, RenderType renderType2, MultiBufferSource bufferSource, VertexConsumer buffer, float partialTick, int packedLight, int packedOverlay) {
            if (EnergySwirlLayer.shouldRender(animatable, shouldRenderFlag)) {
                float f = (float) animatable.tickCount + partialTick;
                var renderType = EnergySwirlLayer.getRenderType(TEXTURE, f);
                VertexConsumer vertexconsumer = bufferSource.getBuffer(renderType);
                poseStack.pushPose();
                bakedModel.getBone("body").ifPresent((rootBone) -> {
                    rootBone.getChildBones().forEach(bone -> {
                        bone.updateScale(1.1f, 1.1f, 1.1f);
                    });
                });
                this.getRenderer().actuallyRender(poseStack, animatable, bakedModel, renderType, bufferSource, vertexconsumer, true, partialTick,
                        packedLight, OverlayTexture.NO_OVERLAY, COLOR);

                bakedModel.getBone("body").ifPresent((rootBone) -> {
                    rootBone.getChildBones().forEach(bone -> {
                        bone.updateScale(1f, 1f, 1f);
                    });
                });
                poseStack.popPose();
            }
        }

@Override
    public void render(PoseStack poseStack, AbstractSpellCastingMob animatable, BakedGeoModel bakedModel, RenderType renderType, MultiBufferSource bufferSource, VertexConsumer buffer, float partialTick, int packedLight, int packedOverlay) {
        if (animatable.isAutoSpinAttack()) {
            poseStack.pushPose();
            for (int i = 0; i < 3; ++i) {
                poseStack.pushPose();
                float f = (animatable.tickCount + partialTick) + (float) (-(45 + i * 5));
                poseStack.mulPose(Axis.YP.rotationDegrees(f));
                float f1 = 0.75F * (float) i;
                poseStack.scale(f1, f1, f1);
                poseStack.translate(0, -1 + (double) (-0.2F + 0.6F * (float) i), 0);
                var rendertype = RenderType.entityCutoutNoCull(modelProvider.getTextureResource(animatable));
                getRenderer().actuallyRender(poseStack, animatable, modelProvider.getBakedModel(modelProvider.getModelResource(animatable)), rendertype, bufferSource, bufferSource.getBuffer(rendertype), true, partialTick, LightTexture.FULL_BRIGHT, packedOverlay, -1);
                poseStack.popPose();
            }
            poseStack.popPose();
        }
    }

@Override
    public void render(VertexConsumer buffer, Camera camera, float partialTick) {
        boolean mirrored = !this.mirror; // based on animation, we actually want the default to be mirrored
        Vec3 vec3 = camera.getPosition();
        float f = (float) (Mth.lerp(partialTick, this.xo, this.x) - vec3.x());
        float f1 = (float) (Mth.lerp(partialTick, this.yo, this.y) - vec3.y());
        float f2 = (float) (Mth.lerp(partialTick, this.zo, this.z) - vec3.z());
        Vector3f[] vertices = new Vector3f[4];
        for (int i = 0; i < 4; i++) {
            var localVertex = localVertices[i];
            vertices[i] = new Vector3f(localVertex.x, localVertex.y, localVertex.z);
            vertices[i].mul(this.getQuadSize(partialTick));
            vertices[i].add(f, f1, f2);
        }
        int j = this.getLightColor(partialTick);
        this.makeCornerVertex(buffer, vertices[0], this.getU1(), mirrored ? this.getV0() : this.getV1(), j);
        this.makeCornerVertex(buffer, vertices[1], this.getU1(), mirrored ? this.getV1() : this.getV0(), j);
        this.makeCornerVertex(buffer, vertices[2], this.getU0(), mirrored ? this.getV1() : this.getV0(), j);
        this.makeCornerVertex(buffer, vertices[3], this.getU0(), mirrored ? this.getV0() : this.getV1(), j);
        //backface
        this.makeCornerVertex(buffer, vertices[3], this.getU0(), mirrored ? this.getV0() : this.getV1(), j);
        this.makeCornerVertex(buffer, vertices[2], this.getU0(), mirrored ? this.getV1() : this.getV0(), j);
        this.makeCornerVertex(buffer, vertices[1], this.getU1(), mirrored ? this.getV1() : this.getV0(), j);
        this.makeCornerVertex(buffer, vertices[0], this.getU1(), mirrored ? this.getV0() : this.getV1(), j);

    }

@Override
    public void render(VertexConsumer consumer, Camera camera, float partialTick) {
        Vec3 vec3 = camera.getPosition();
        float f = (float) (Mth.lerp((double) partialTick, this.xo, this.x) - vec3.x());
        float f1 = (float) (Mth.lerp((double) partialTick, this.yo, this.y) - vec3.y());
        float f2 = (float) (Mth.lerp((double) partialTick, this.zo, this.z) - vec3.z());
        PoseStack poseStack = new PoseStack();
        poseStack.translate(f, f1, f2);
        Vec3 rayVector = destination.subtract(this.getPos());
        float baseWidth = 1f;
        float hullLength = 3 * baseWidth;
        double distance = rayVector.length();
        int hulls = (int) (distance / hullLength);
        double zmargin = distance / (hulls * hullLength); // make up marginal differences caused by truncation of hull unit length
        rayVector = rayVector.normalize();
        Vec2 rotation = Utils.rotationFromDirection(rayVector);
        poseStack.mulPose(Axis.YP.rotation(rotation.y));
        poseStack.mulPose(Axis.XP.rotation(-rotation.x));
        poseStack.mulPose(Axis.ZP.rotationDegrees((age + partialTick) * 360 / lifetime));
        poseStack.scale(1, 1, (float) zmargin);
        float t = Math.clamp((age + partialTick) / (float) lifetime, 0, 1);
        float width = Mth.lerp(t, 0.1f, baseWidth);
        this.alpha = Mth.lerp(t, 1, 0);

        for (int i = 0; i < hulls; i++) {
            drawHull(Vec3.ZERO, new Vec3(0, 0, hullLength), width, width, poseStack, consumer);
            drawHull(Vec3.ZERO, new Vec3(0, 0, hullLength), width * .5f, width * .5f, poseStack, consumer);
            poseStack.translate(0, 0, hullLength);
        }
    }

public static void renderRayOfSiphoning(LivingEntity entity, PoseStack poseStack, MultiBufferSource bufferSource, float partialTicks) {

        poseStack.pushPose();
        poseStack.translate(0, entity.getEyeHeight() * .8f, 0);

        var pose = poseStack.last();
        Vec3 end;
        Vec3 rayEndPos;
        if (entity instanceof Mob mob && MagicData.getPlayerMagicData(mob).getAdditionalCastData() instanceof CastingMobAimingData aimingData) {
            rayEndPos = RaycastBuilder.begin(entity.level, entity)
                    .start(entity.getEyePosition())
                    .end(entity.getEyePosition().add(aimingData.getAimPosition(partialTicks).subtract(entity.getEyePosition(partialTicks)).normalize().scale(RayOfSiphoningSpell.getRange(0))))
                    .checkForBlocks(true)
                    .build()
                    .getLocation();
        } else {
            rayEndPos = RaycastBuilder.begin(entity.level(), entity)
                    .range(RayOfSiphoningSpell.getRange(0))
                    .checkForBlocks(true)
                    .build()
                    .getLocation();
        }
        float distance = (float) entity.getEyePosition().distanceTo(rayEndPos);
        float radius = .12f;
        int r = (int) (255 * .7f);
        int g = (int) (255 * 0f);
        int b = (int) (255 * 0f);
        int a = (int) (255 * 1f);

        float deltaTicks = entity.tickCount + partialTicks;
        float deltaUV = -deltaTicks % 10;
        float max = Mth.frac(deltaUV * 0.2F - (float) Mth.floor(deltaUV * 0.1F));
        float min = -1.0F + max;

        var dir = rayEndPos.subtract(entity.getEyePosition(partialTicks)).normalize();

        //y rotation is a triangle of x and z axis
        float dx = (float) dir.x;
        float dz = (float) dir.z;
        //angle = atan o/a
        float yRot = (float) Mth.atan2(dz, dx) - 1.5707f; // for some reason, we are rotated 90 degrees the wrong way. subtracting 2 pi here.
        //IronsSpellbooks.LOGGER.debug("yRot: {}", yRot);
        //x rotation is a triangle of xz and y axis
        float dxz = Mth.sqrt(dx * dx + dz * dz);
        float dy = (float) dir.y;
        //angle = atan o/a
        float xRot = (float) Mth.atan2(dy, dxz);
        //IronsSpellbooks.LOGGER.debug("xRot: {}", xRot);
        poseStack.mulPose(Axis.YP.rotation(-yRot));
        poseStack.mulPose(Axis.XP.rotation(-xRot));
        Vec3 start = Vec3.ZERO;
        for (float j = 1; j <= distance; j += .5f) {
            Vec3 wiggle = new Vec3(
                    Mth.sin(deltaTicks * .8f) * .02f,
                    Mth.sin(deltaTicks * .8f + 100) * .02f,
                    Mth.cos(deltaTicks * .8f) * .02f
            );
            //end = dir.scale(Math.min(j, distance)).add(wiggle);
            end = new Vec3(0, 0, Math.min(j, distance)).add(wiggle);
            VertexConsumer inner = bufferSource.getBuffer(RenderType.entityTranslucent(BEACON, true));
            drawHull(start, end, radius, radius, pose, inner, r, g, b, a, min, max);
            //drawHull(start, end, .25f, .25f, pose, outer, r / 2, g / 2, b / 2, a / 2);
            VertexConsumer outer = bufferSource.getBuffer(RenderType.entityTranslucent(TWISTING_GLOW));
            drawQuad(start, end, radius * 4f, 0, pose, outer, r, g, b, a, min, max);
            drawQuad(start, end, 0, radius * 4f, pose, outer, r, g, b, a, min, max);
            start = end;

        }
        poseStack.popPose();
    }

@Override
    public void render(VertexConsumer buffer, Camera renderInfo, float partialTicks) {
        float var = (age + partialTicks)/lifetime;
        if (behavior == 0) {
            quadSize = size * var;
        }
        else if (behavior == 1) {
            quadSize = size * (1 - var);
        }
        else if (behavior == 2) {
            quadSize = (float) (size * (1 - var - Math.pow(2000, -var)));
        }
        else {
            quadSize = size;
        }
        alpha = opacity * 0.95f * (1 - (age + partialTicks)/lifetime) + 0.05f;
        rCol = r;
        gCol = g;
        bCol = b;

        Vec3 Vector3d = renderInfo.getPosition();
        float f = (float)(Mth.lerp(partialTicks, this.xo, this.x) - Vector3d.x());
        float f1 = (float)(Mth.lerp(partialTicks, this.yo, this.y) - Vector3d.y());
        float f2 = (float)(Mth.lerp(partialTicks, this.zo, this.z) - Vector3d.z());
        Quaternionf quaternionf = new Quaternionf(0.0F, 0.0F, 0.0F, 1.0F);
        if (facesCamera) {
            if (this.roll == 0.0F) {
                quaternionf = renderInfo.rotation();
            } else {
                quaternionf = new Quaternionf(renderInfo.rotation());
                float f3 = Mth.lerp(partialTicks, this.oRoll, this.roll);
                quaternionf.mul(Axis.ZP.rotation(f3));
            }
        }
        else {
            Quaternionf quatX = CMMathUtil.quatFromRotationXYZ(pitch, 0, 0, false);
            Quaternionf quatY = CMMathUtil.quatFromRotationXYZ(0, yaw, 0, false);
            quaternionf.mul(quatY);
            quaternionf.mul(quatX);
        }

        Vector3f vector3f1 = new Vector3f(-1.0F, -1.0F, 0.0F);
        quaternionf.transform(vector3f1);
        Vector3f[] avector3f = new Vector3f[]{new Vector3f(-1.0F, -1.0F, 0.0F), new Vector3f(-1.0F, 1.0F, 0.0F), new Vector3f(1.0F, 1.0F, 0.0F), new Vector3f(1.0F, -1.0F, 0.0F)};
        float f4 = this.getQuadSize(partialTicks);

        for(int i = 0; i < 4; ++i) {
            Vector3f vector3f = avector3f[i];
            quaternionf.transform(vector3f);
            vector3f.mul(f4);
            vector3f.add(f, f1, f2);
        }

        float f7 = this.getU0();
        float f8 = this.getU1();
        float f5 = this.getV0();
        float f6 = this.getV1();
        int j = this.getLightColor(partialTicks);
        buffer.vertex(avector3f[0].x(), avector3f[0].y(), avector3f[0].z()).uv(f8, f6).color(this.rCol/255F, this.gCol/255F, this.bCol/255F, this.alpha).uv2(j).endVertex();
        buffer.vertex(avector3f[1].x(), avector3f[1].y(), avector3f[1].z()).uv(f8, f5).color(this.rCol/255F, this.gCol/255F, this.bCol/255F, this.alpha).uv2(j).endVertex();
        buffer.vertex(avector3f[2].x(), avector3f[2].y(), avector3f[2].z()).uv(f7, f5).color(this.rCol/255F, this.gCol/255F, this.bCol/255F, this.alpha).uv2(j).endVertex();
        buffer.vertex(avector3f[3].x(), avector3f[3].y(), avector3f[3].z()).uv(f7, f6).color(this.rCol/255F, this.gCol/255F, this.bCol/255F, this.alpha).uv2(j).endVertex();

        buffer.vertex(avector3f[3].x(), avector3f[3].y(), avector3f[3].z()).uv(f7, f6).color(this.rCol/255F, this.gCol/255F, this.bCol/255F, this.alpha).uv2(j).endVertex();
        buffer.vertex(avector3f[2].x(), avector3f[2].y(), avector3f[2].z()).uv(f7, f5).color(this.rCol/255F, this.gCol/255F, this.bCol/255F, this.alpha).uv2(j).endVertex();
        buffer.vertex(avector3f[1].x(), avector3f[1].y(), avector3f[1].z()).uv(f8, f5).color(this.rCol/255F, this.gCol/255F, this.bCol/255F, this.alpha).uv2(j).endVertex();
        buffer.vertex(avector3f[0].x(), avector3f[0].y(), avector3f[0].z()).uv(f8, f6).color(this.rCol/255F, this.gCol/255F, this.bCol/255F, this.alpha).uv2(j).endVertex();


    }

@SubscribeEvent
	public static void onRenderWorldLastEvent(RenderWorldLastEvent event){
		// Only render in first person
		if(Minecraft.getMinecraft().gameSettings.thirdPersonView == 0){

			EntityPlayer player = Minecraft.getMinecraft().player;

			if(EntityUtils.isCasting(player, Spells.shadow_ward)){

				GlStateManager.pushMatrix();

				GlStateManager.enableBlend();
				GlStateManager.blendFunc(GL11.GL_SRC_ALPHA, GL11.GL_ONE_MINUS_SRC_ALPHA);
				//GlStateManager.shadeModel(GL11.GL_SMOOTH);
				GlStateManager.disableLighting();
				//GlStateManager.disableAlpha();
				OpenGlHelper.setLightmapTextureCoords(OpenGlHelper.lightmapTexUnit, 240f, 240f);

				GlStateManager.translate(0, 1.2, 0);
				GlStateManager.rotate(-player.rotationYaw, 0, 1, 0);
				GlStateManager.rotate(player.rotationPitch, 1, 0, 0);

				Minecraft.getMinecraft().renderEngine.bindTexture(TEXTURE);

				GlStateManager.pushMatrix();

				GlStateManager.translate(0, 0, 1.2);
				GlStateManager.rotate(player.ticksExisted * -2, 0, 0, 1);
				GlStateManager.scale(1.1, 1.1, 1.1);

				Tessellator tessellator = Tessellator.getInstance();
				BufferBuilder buffer = tessellator.getBuffer();

				buffer.begin(GL11.GL_QUADS, DefaultVertexFormats.POSITION_TEX);

				buffer.pos(-0.5, 0.5, -0.5).tex(0, 0).endVertex();
				buffer.pos(0.5, 0.5, -0.5).tex(1, 0).endVertex();
				buffer.pos(0.5, -0.5, -0.5).tex(1, 1).endVertex();
				buffer.pos(-0.5, -0.5, -0.5).tex(0, 1).endVertex();

				tessellator.draw();

				buffer.begin(GL11.GL_QUADS, DefaultVertexFormats.POSITION_TEX);

				buffer.pos(-0.5, 0.5, -0.5).tex(0, 0).endVertex();
				buffer.pos(-0.5, -0.5, -0.5).tex(0, 1).endVertex();
				buffer.pos(0.5, -0.5, -0.5).tex(1, 1).endVertex();
				buffer.pos(0.5, 0.5, -0.5).tex(1, 0).endVertex();

				tessellator.draw();

				GlStateManager.popMatrix();

				//GlStateManager.shadeModel(GL11.GL_FLAT);
				GlStateManager.enableLighting();
				GlStateManager.disableBlend();

				GlStateManager.popMatrix();

			}
		}
	}

private void renderEntityModel(T entity, float limbSwing, float limbSwingAmount, float partialTicks,
			float ageInTicks, float netHeadYaw, float headPitch, float scale){

		GlStateManager.pushMatrix();
		// Enables texture tiling (Also used for guardian beam, beacon beam and ender crystal beam, amongst others)
		GlStateManager.glTexParameteri(GL11.GL_TEXTURE_2D, GL11.GL_TEXTURE_WRAP_S, GL11.GL_REPEAT);
		GlStateManager.glTexParameteri(GL11.GL_TEXTURE_2D, GL11.GL_TEXTURE_WRAP_T, GL11.GL_REPEAT);

		GlStateManager.depthMask(true); // Some entities set depth mask to false (i.e. no sorting of faces by depth)
		// In particular, LayerSpiderEyes sets it to false when the spider is invisible, for some reason.

		// Changes the scale at which the texture is applied to the model. See LayerCreeper for a similar example,
		// but with translation instead of scaling.
		// You can do all sorts of fun stuff with this, just by applying transformations in the 2D texture space.
		GlStateManager.matrixMode(GL11.GL_TEXTURE); // Switch to the 2D texture space
		GlStateManager.loadIdentity();

		ModelBase model = getModel(entity, partialTicks);

		// Calculate the scaling required in each direction
		double scaleX = 1, scaleY = 1;
		// It's more logical to use the model's texture size, but some classes don't bother setting it properly
		// (e.g. ModelVillager), so to get the correct dimensions I'm getting them from the first box instead.
		if(model.boxList != null && model.boxList.size() >= 1 && model.boxList.get(0) != null){
			scaleX = (double)model.boxList.get(0).textureWidth / textureWidth;
			scaleY = (double)model.boxList.get(0).textureHeight / textureHeight;
		}else{ // Fallback to model fields; should never be needed
			scaleX = (double)model.textureWidth / textureWidth;
			scaleY = (double)model.textureHeight / textureHeight;
		}

		GlStateManager.scale(scaleX, scaleY, 1);

		applyTextureSpaceTransformations(entity, partialTicks);

		GlStateManager.matrixMode(GL11.GL_MODELVIEW); // Switch back to the 3D model space

		boolean headWearHidden = false;
		boolean bodyWearHidden = false;
		boolean leftArmWearHidden = false;
		boolean rightArmWearHidden = false;
		boolean leftLegWearHidden = false;
		boolean rightLegWearHidden = false;

		if(!renderSecondLayer(entity, partialTicks)){
			// Hide the hat layer for bipeds, and all the other body part overlays for players
			if(model instanceof ModelBiped){
				headWearHidden = ((ModelBiped)model).bipedHeadwear.isHidden;
				((ModelBiped)model).bipedHeadwear.isHidden = true;
			}

			if(model instanceof ModelPlayer){
				bodyWearHidden = ((ModelPlayer)model).bipedBodyWear.isHidden;
				leftArmWearHidden = ((ModelPlayer)model).bipedLeftArmwear.isHidden;
				rightArmWearHidden = ((ModelPlayer)model).bipedRightArmwear.isHidden;
				leftLegWearHidden = ((ModelPlayer)model).bipedLeftLegwear.isHidden;
				rightLegWearHidden = ((ModelPlayer)model).bipedRightLegwear.isHidden;
				((ModelPlayer)model).bipedBodyWear.isHidden = true;
				((ModelPlayer)model).bipedLeftArmwear.isHidden = true;
				((ModelPlayer)model).bipedRightArmwear.isHidden = true;
				((ModelPlayer)model).bipedLeftLegwear.isHidden = true;
				((ModelPlayer)model).bipedRightLegwear.isHidden = true;
			}
		}

		// Actually render the model
		model.setLivingAnimations(entity, limbSwing, limbSwingAmount, partialTicks);
		model.render(entity, limbSwing, limbSwingAmount, ageInTicks, netHeadYaw, headPitch, scale);

		if(!renderSecondLayer(entity, partialTicks)){
			// Reset the hidden status of everything to how it was before
			if(model instanceof ModelBiped){
				((ModelBiped)model).bipedHeadwear.isHidden = headWearHidden;
			}

			if(model instanceof ModelPlayer){
				((ModelPlayer)model).bipedBodyWear.isHidden = bodyWearHidden;
				((ModelPlayer)model).bipedLeftArmwear.isHidden = leftArmWearHidden;
				((ModelPlayer)model).bipedRightArmwear.isHidden = rightArmWearHidden;
				((ModelPlayer)model).bipedLeftLegwear.isHidden = leftLegWearHidden;
				((ModelPlayer)model).bipedRightLegwear.isHidden = rightLegWearHidden;
			}
		}

		// Undo the texture scaling
		GlStateManager.matrixMode(GL11.GL_TEXTURE);
		GlStateManager.loadIdentity();
		GlStateManager.matrixMode(GL11.GL_MODELVIEW);

		GlStateManager.popMatrix();
	}

@Override
	public void render(@NotNull BabylonWeaponEntity weapon, float yaw, float partialTicks, PoseStack ms, MultiBufferSource buffers, int light) {
		ms.pushPose();
		ms.mulPose(VecHelper.rotateY(weapon.getRotation()));

		int live = weapon.getLiveTicks();
		int delay = weapon.getDelay();
		float charge = Math.min(10F, Math.max(live, weapon.getChargeTicks()) + partialTicks);
		float chargeMul = charge / 10F;

		ms.pushPose();
		ms.translate(-0.75, 0, 1); // X shifts the weapon hilt to the center of the circle, Z makes it intersect it.
		float s = 1.5F;
		ms.scale(s, s, s);
		ms.mulPose(VecHelper.rotateY(90F)); // Rotate to make it match facing, instead of perpendicular to the circle
		ms.mulPose(VecHelper.rotateZ(-45F)); // Perpendicular to the ground, instead of the rising 45 deg of the sprite

		BakedModel model = MiscellaneousModels.INSTANCE.kingKeyWeaponModels[weapon.getVariety()];
		Minecraft.getInstance().getBlockRenderer().getModelRenderer().renderModel(ms.last(), buffers.getBuffer(Sheets.translucentItemSheet()), null, model, 1, 1, 1, 0xF000F0, OverlayTexture.NO_OVERLAY);
		ms.popPose();

		Random rand = new Random(weapon.getUUID().getMostSignificantBits());
		ms.mulPose(VecHelper.rotateX(-90F)); // Lay the circle horizontally
		ms.translate(0F, -0.3F + rand.nextFloat() * 0.1F, 0F); // Randomly offset how deep the item is in the circle

		s = chargeMul;
		if (live > delay) {
			s -= Math.min(1F, (live - delay + partialTicks) * 0.2F);
		}
		s *= 2F;
		ms.scale(s, s, s);

		ms.mulPose(VecHelper.rotateY(charge * 9F + (weapon.tickCount + partialTicks) * 0.5F + rand.nextFloat() * 360F));

		VertexConsumer buffer = buffers.getBuffer(RenderHelper.BABYLON_ICON);
		Matrix4f mat = ms.last().pose();
		buffer.vertex(mat, -1, 0, -1).color(1, 1, 1, chargeMul).uv(0, 0).endVertex();
		buffer.vertex(mat, -1, 0, 1).color(1, 1, 1, chargeMul).uv(0, 1).endVertex();
		buffer.vertex(mat, 1, 0, 1).color(1, 1, 1, chargeMul).uv(1, 1).endVertex();
		buffer.vertex(mat, 1, 0, -1).color(1, 1, 1, chargeMul).uv(1, 0).endVertex();

		ms.popPose();
	}

private static RenderPhase.Texturing itemGlowTexturing(Color color) {
        return new RenderPhase.Texturing("spell_engine_item_glow_texturing",
                () -> {
                    // `getShaderColor` hands out the live array, not a copy of it
                    System.arraycopy(RenderSystem.getShaderColor(), 0, shaderColorToRestore, 0, 4);
                    glintAlphaToRestore = RenderSystem.getShaderGlintAlpha();

                    RenderSystem.setTextureMatrix(itemGlowTextureMatrix());

                    // Opacity is folded into the color instead of the alpha, because the additive blend
                    // scales by color, and the glint shader discards fragments below `alpha < 0.1`,
                    // which would cut faint glows off entirely instead of fading them out.
                    var intensity = color.alpha() * itemGlowGain;
                    RenderSystem.setShaderColor(
                            color.red() * intensity,
                            color.green() * intensity,
                            color.blue() * intensity,
                            1F);

                    // The glint shader fades by this, and it follows the `Glint Strength` video setting.
                    // This glow carries gameplay meaning, so it must not be dimmed away by a cosmetic option.
                    RenderSystem.setShaderGlintAlpha(1F);
                },
                () -> {
                    RenderSystem.resetTextureMatrix();
                    RenderSystem.setShaderColor(
                            shaderColorToRestore[0], shaderColorToRestore[1],
                            shaderColorToRestore[2], shaderColorToRestore[3]);
                    RenderSystem.setShaderGlintAlpha(glintAlphaToRestore);
                });
    }

@Override
    public void renderEffect(long appliedAtWorldTime, int amplifier, LivingEntity livingEntity, float delta, MatrixStack matrixStack,
                 VertexConsumerProvider vertexConsumers, int light) {
        var itemRenderer = MinecraftClient.getInstance().getItemRenderer();
        // World time, not Entity.age: the server stamps `appliedAtWorldTime` in its clock, and the
        // client's World.getTime() tracks it (shared origin, re-synced each second). Entity.age counts
        // from whenever each side first saw the entity, so `age - appliedAtAge` could start deeply
        // negative and skip the whole animation for seconds. See Synchronized.Effect.
        float rawTime = (livingEntity.getWorld().getTime() - appliedAtWorldTime) + delta;

        if (followYaw) {
            float yaw = livingEntity.getYaw(delta);
            matrixStack.multiply(RotationAxis.NEGATIVE_Y.rotationDegrees(yaw));
        }

        if (entityScaling != null) {
            float s = entityScaling.scaleFor(livingEntity);
            matrixStack.scale(s, s, s);
        }

        for (var effect : effects) {
            if (effect.model_id == null || effect.model_id.isEmpty()) continue;

            float age;
            if (playback == Playback.LOOP && effect.duration > 0) {
                age = rawTime % effect.duration;
            } else {
                age = rawTime;
            }

            ModelEffectOperations.renderEffect(effect, age, matrixStack, itemRenderer, vertexConsumers, light, livingEntity.getId());
        }
    }

public static boolean renderComposite(float scale, EntityRenderDispatcher dispatcher, ItemRenderer itemRenderer,
                                          Spell.ProjectileModelComposite composite, @Nullable String heldItemModelId,
                                          @Nullable Vec3d previousVelocity, Entity entity, float tickDelta, boolean allowSpin,
                                          MatrixStack matrices, VertexConsumerProvider vertexConsumers, int light) {
        // Skip while very fresh and very close to the camera, so a just-spawned projectile doesn't
        // fill the caster's view.
        if (entity.age < 2 && dispatcher.camera.getFocusedEntity().squaredDistanceTo(entity) < 12.25) {
            return false;
        }

        float age = entity.age + tickDelta;
        for (var model : composite.models) {
            var fx = model.fx;
            matrices.push();

            // Placement within the entity bounding box (entity space, before the entity scale).
            if (fx.positioning != null && fx.positioning.vertical != 0) {
                matrices.translate(0, fx.positioning.vertical * entity.getHeight(), 0);
            }
            // Overall projectile scale.
            matrices.scale(scale, scale, scale);
            // Facing relative to travel.
            applyCompositeOrientation(model.orientation, dispatcher, entity, previousVelocity, tickDelta, matrices);
            // Continuous spin (disabled e.g. while an arrow is stuck in the ground).
            if (allowSpin && (model.rotate_degrees_per_tick != 0 || model.rotate_degrees_offset != 0)) {
                matrices.multiply(RotationAxis.POSITIVE_Z.rotationDegrees(
                        model.rotate_degrees_offset + age * model.rotate_degrees_per_tick));
            }
            // modelFX animation (initial + animated transforms + fx.scale).
            ModelEffectOperations.applyTransforms(matrices, fx, age);

            var layer = SpellModelHelper.LAYERS.get(fx.light_emission);
            if (model.use_held_item) {
                // Held items MUST resolve through the item model path (itemRenderer.getModel(stack, ...)).
                // Resolving them as a raw model Identifier via CustomModels.render breaks on NeoForge: getModel returns the missing-model placeholder
                // (never null) for a bare item id — an item's model isn't registered under the `#standalone`
                // variant the NeoForge branch looks up — so the item-stack fallback never fires and an
                // empty/placeholder model is drawn. heldItemModelId is null for non-held projectiles (e.g.
                // arrows via ProjectileEntityRendererMixin), which then correctly skip these models.
                if (heldItemModelId != null && !heldItemModelId.isEmpty()) {
                    var stack = Registries.ITEM.get(Identifier.of(heldItemModelId)).getDefaultStack();
                    if (!stack.isEmpty()) {
                        var itemModel = itemRenderer.getModel(stack, entity.getWorld(), null, entity.getId());
                        // Item models are authored in item-display space; FIXED (item-frame) gives them the
                        // base orientation the projectile orientation math (e.g. ALONG_MOTION) expects.
                        itemModel.getTransformation().getTransformation(ModelTransformationMode.FIXED).apply(false, matrices);
                        CustomModels.renderModel(layer, (ItemRendererAccessor) itemRenderer, matrices, vertexConsumers, light, itemModel);
                    }
                }
            } else if (fx.model_id != null && !fx.model_id.isEmpty()) {
                // Custom (non-item) fx models render raw, with no display transform.
                CustomModels.render(layer, itemRenderer, Identifier.of(fx.model_id), null, matrices, vertexConsumers, light, entity.getId());
            }

            matrices.pop();
        }
        return true;
    }

private static void applyCompositeOrientation(Spell.ProjectileModelComposite.Orientation orientation, EntityRenderDispatcher dispatcher,
                                                  Entity entity, @Nullable Vec3d previousVelocity, float tickDelta, MatrixStack matrices) {
        switch (orientation) {
            case TOWARDS_CAMERA -> {
                matrices.multiply(dispatcher.getRotation());
                matrices.multiply(RotationAxis.POSITIVE_Y.rotationDegrees(180.0F));
            }
            case TOWARDS_MOTION, ALONG_MOTION -> {
                var velocity = entity.getVelocity();
                if (previousVelocity != null) {
                    velocity = previousVelocity.lerp(velocity, tickDelta);
                }
                velocity = velocity.normalize();
                var directionBasedYaw = Math.toDegrees(Math.atan2(velocity.x, velocity.z)) + 180F;
                var directionBasedPitch = Math.toDegrees(Math.asin(velocity.y));
                matrices.multiply(RotationAxis.POSITIVE_Y.rotationDegrees((float) directionBasedYaw));
                matrices.multiply(RotationAxis.POSITIVE_X.rotationDegrees((float) directionBasedPitch));
                if (orientation == Spell.ProjectileModelComposite.Orientation.ALONG_MOTION) {
                    // ALONG_MOTION models lie along their local X axis, so folding the +90 into the
                    // yaw would leave the pitch (applied around X) rotating the model about its own
                    // length — no elevation, model stuck facing the horizon. Instead convert the X
                    // length into the +Z "forward" that the yaw/pitch above already orient, applied
                    // innermost (last) so it doesn't cancel the vertical component of the motion.
                    matrices.multiply(RotationAxis.POSITIVE_Y.rotationDegrees(90F));
                }
            }
        }
    }

@Override
	public void renderParticle(BufferBuilder buffer, Entity viewer, float partialTicks, float rotationX, float rotationZ,
			float rotationYZ, float rotationXY, float rotationXZ){

		// Copied from ParticleWizardry, needs to be here since we're not calling super
		updateEntityLinking(viewer, partialTicks);

		GlStateManager.pushMatrix();
		GlStateManager.pushAttrib();

		GlStateManager.enableBlend();
		GlStateManager.disableAlpha();
		GlStateManager.disableCull();
		GlStateManager.disableLighting();
		GlStateManager.blendFunc(SourceFactor.SRC_ALPHA, DestFactor.ONE);
		// Makes the particle colour add to the colour of the texture pixels, rather than the default multiplying
		GlStateManager.glTexEnvi(GL11.GL_TEXTURE_ENV, GL11.GL_TEXTURE_ENV_MODE, GL11.GL_ADD);

		OpenGlHelper.setLightmapTextureCoords(OpenGlHelper.lightmapTexUnit, 240f, 240f);

		GlStateManager.glTexParameteri(GL11.GL_TEXTURE_2D, GL11.GL_TEXTURE_WRAP_S, GL11.GL_REPEAT);
		GlStateManager.glTexParameteri(GL11.GL_TEXTURE_2D, GL11.GL_TEXTURE_WRAP_T, GL11.GL_REPEAT);

		// Does the texture translation wrapping thing (the cool stuff)
		GlStateManager.matrixMode(GL11.GL_TEXTURE);
		GlStateManager.loadIdentity();

		GlStateManager.translate((this.particleAge + partialTicks)/(float)this.particleMaxAge * -2, 0, 0);

		GlStateManager.matrixMode(GL11.GL_MODELVIEW);

		RenderHelper.disableStandardItemLighting();

		Minecraft.getMinecraft().getTextureManager().bindTexture(TEXTURE);

		buffer.begin(GL11.GL_TRIANGLE_STRIP, DefaultVertexFormats.POSITION_TEX_COLOR);

		float x = (float)(this.prevPosX + (this.posX - this.prevPosX) * (double)partialTicks - interpPosX);
		float y = (float)(this.prevPosY + (this.posY - this.prevPosY) * (double)partialTicks - interpPosY);
		float z = (float)(this.prevPosZ + (this.posZ - this.prevPosZ) * (double)partialTicks - interpPosZ);

		// Increases from 0 to 1 in steps of 0.125 evenly throughout the particle's lifetime
		float f = 0.875f - 0.125f * MathHelper.floor((float)this.particleAge/(float)this.particleMaxAge * 8 - 0.000001f);
		float g = f + 0.125f;
		float hrepeat = 1;
		float scale = 0.6f;
		float yScale = 0.7f * scale;
		float dx = mirror ? -scale : scale;
		float dz = scale;

		buffer.pos(x-dx, y-yScale, z-dz).tex(0, g).color(particleRed, particleGreen, particleBlue, particleAlpha).endVertex();
		buffer.pos(x-dx, y+yScale, z-dz).tex(0, f).color(particleRed, particleGreen, particleBlue, particleAlpha).endVertex();
		buffer.pos(x+dx, y-yScale, z-dz).tex(0.25*hrepeat, g).color(particleRed, particleGreen, particleBlue, particleAlpha).endVertex();
		buffer.pos(x+dx, y+yScale, z-dz).tex(0.25*hrepeat, f).color(particleRed, particleGreen, particleBlue, particleAlpha).endVertex();
		buffer.pos(x+dx, y-yScale, z+dz).tex(0.5*hrepeat, g).color(particleRed, particleGreen, particleBlue, particleAlpha).endVertex();
		buffer.pos(x+dx, y+yScale, z+dz).tex(0.5*hrepeat, f).color(particleRed, particleGreen, particleBlue, particleAlpha).endVertex();
		buffer.pos(x-dx, y-yScale, z+dz).tex(0.75*hrepeat, g).color(particleRed, particleGreen, particleBlue, particleAlpha).endVertex();
		buffer.pos(x-dx, y+yScale, z+dz).tex(0.75*hrepeat, f).color(particleRed, particleGreen, particleBlue, particleAlpha).endVertex();
		buffer.pos(x-dx, y-yScale, z-dz).tex(hrepeat, g).color(particleRed, particleGreen, particleBlue, particleAlpha).endVertex();
		buffer.pos(x-dx, y+yScale, z-dz).tex(hrepeat, f).color(particleRed, particleGreen, particleBlue, particleAlpha).endVertex();

		Tessellator.getInstance().draw();

		// Undoes the texture transformations
		GlStateManager.matrixMode(GL11.GL_TEXTURE);
		GlStateManager.loadIdentity();
		GlStateManager.matrixMode(GL11.GL_MODELVIEW);

		GlStateManager.disableBlend();
		GlStateManager.enableAlpha();
		GlStateManager.enableCull();
		GlStateManager.enableLighting();
		// Reverses the colour addition change from before
		GlStateManager.glTexEnvi(GL11.GL_TEXTURE_ENV, GL11.GL_TEXTURE_ENV_MODE, GL11.GL_MODULATE);

		GlStateManager.popAttrib();
		GlStateManager.popMatrix();

	}

@Override
	public void renderParticle(BufferBuilder buffer, Entity viewer, float partialTicks, float rotationX, float rotationZ, float rotationYZ,
			float rotationXY, float rotationXZ){

		// Copied from ParticleWizardry, needs to be here since we're not calling super
		updateEntityLinking(viewer, partialTicks);

		float x = (float)(this.prevPosX + (this.posX - this.prevPosX) * (double)partialTicks);
		float y = (float)(this.prevPosY + (this.posY - this.prevPosY) * (double)partialTicks);
		float z = (float)(this.prevPosZ + (this.posZ - this.prevPosZ) * (double)partialTicks);

		// Translates the particle a short distance in front of the entity
		if(this.entity != null && this.shouldApplyOriginOffset()){
			if(this.entity != viewer || Minecraft.getMinecraft().gameSettings.thirdPersonView != 0){
				Vec3d look = entity.getLook(partialTicks).scale(THIRD_PERSON_AXIAL_OFFSET);
				x += look.x;
				y += look.y;
				z += look.z;
			}
		}

		if(this.target != null){

			this.targetX = this.target.prevPosX + (this.target.posX - this.target.prevPosX) * partialTicks;
			double correction = this.target.posY - this.target.posY;
			this.targetY = this.target.prevPosY + (this.target.posY - this.target.prevPosY) * partialTicks
					+ target.height/2 + correction;
			this.targetZ = this.target.prevPosZ + (this.target.posZ - this.target.prevPosZ) * partialTicks;

		}else if(this.entity != null && this.length > 0){

			Vec3d look = entity.getLook(partialTicks).scale(length);
			this.targetX = x + look.x;
			this.targetY = y + look.y;
			this.targetZ = z + look.z;
		}

		if(Double.isNaN(targetX) || Double.isNaN(targetY) || Double.isNaN(targetZ)){
			Wizardry.logger.warn("Attempted to render a targeted particle, but neither its target entity nor target"
					+ "position was set, and it either had no length assigned or was not linked to an entity!");
			return;
		}

		GlStateManager.pushMatrix();
		GlStateManager.translate(x - interpPosX, y - interpPosY, z - interpPosZ);

		double dx = this.targetX - x;
		double dy = this.targetY - y;
		double dz = this.targetZ - z;

		// No need for previous tick target positions and all that stuff since this is the only place they're used
		// and interpolating like this works just as well
		if(!Double.isNaN(targetVelX) && !Double.isNaN(targetVelY) && !Double.isNaN(targetVelZ)){
			dx += partialTicks * this.targetVelX;
			dy += partialTicks * this.targetVelY;
			dz += partialTicks * this.targetVelZ;
		}

		// The distance from origin to endpoint
		double length = Math.sqrt(dx*dx+dy*dy+dz*dz);

		// Math.atan2 computes within -180 to +180, rather than -90 to +90.
		float yaw = (float)(180d/Math.PI * Math.atan2(dx, dz));
		float pitch = (float)(180f/(float)Math.PI * Math.atan(-dy/Math.sqrt(dz*dz+dx*dx)));

		GL11.glRotatef(yaw, 0, 1, 0);
		GL11.glRotatef(pitch, 1, 0, 0);

		Tessellator tessellator = Tessellator.getInstance();

		this.draw(tessellator, length, partialTicks);

		GlStateManager.popMatrix();
	}

@Override
	protected void draw(Tessellator tessellator, double length, float partialTicks){

		random.setSeed(seed); // Reset the random so we get the same sequence of numbers each frame

		float scale = this.particleScale;

		BufferBuilder buffer = tessellator.getBuffer();

		GlStateManager.disableLighting();
		OpenGlHelper.setLightmapTextureCoords(OpenGlHelper.lightmapTexUnit, 240f, 240f);

		// Hmmmm we can't get the texture to tile using OpenGL texture space because it's on a sprite sheet...
		// Solution: Draw loads of boxes. Simple!
		// (Since there aren't going to be that many of these particles around we could have not used sprite sheets
		// and done the OpenGL texture space thing, but this is kinda easier)
		// Everything is drawn back-to-front so it looks like the vine is growing from the origin, not the endpoint
		int i = 0;
		while(i + SEGMENT_LENGTH < length){
			drawShearedBox(tessellator, 0, 0, length-i, 0, 0, length-i-SEGMENT_LENGTH, THICKNESS * scale,
					particleRed, particleGreen, particleBlue, particleAlpha);
			i += SEGMENT_LENGTH;
		}

		drawShearedBox(tessellator, 0, 0, length-i, 0, 0, 0, THICKNESS * scale,
				particleRed, particleGreen, particleBlue, particleAlpha);

		for(double l=length; l>0; l-=LEAF_SPACING){

			GlStateManager.pushMatrix();

			GlStateManager.rotate(random.nextInt(4) * 90, 0, 0, 1);

			buffer.begin(GL11.GL_QUADS, DefaultVertexFormats.POSITION_TEX_COLOR);

			TextureAtlasSprite leaf = Minecraft.getMinecraft().getTextureMapBlocks().getAtlasSprite(
					LEAF_TEXTURES[random.nextInt(LEAF_TEXTURES.length)].toString());

			float w = 16 * THICKNESS * scale;
			float u1 = leaf.getMinU();
			float u2 = leaf.getMaxU();
			float v1 = leaf.getMinV();
			float v2 = leaf.getMaxV();

			float colourVariation = 0.3f;

			float r = MathHelper.clamp(particleRed + (random.nextFloat() - 0.5f) * colourVariation, 0, 1);
			float g = MathHelper.clamp(particleGreen + (random.nextFloat() - 0.5f) * colourVariation, 0, 1);
			float b = MathHelper.clamp(particleBlue + (random.nextFloat() - 0.5f) * colourVariation, 0, 1);

			buffer.pos(0, 0, l).tex(u1, v1).color(r, g, b, particleAlpha).endVertex();
			buffer.pos(w, 0, l).tex(u2, v1).color(r, g, b, particleAlpha).endVertex();
			buffer.pos(w, w, l).tex(u2, v2).color(r, g, b, particleAlpha).endVertex();
			buffer.pos(0, w, l).tex(u1, v2).color(r, g, b, particleAlpha).endVertex();

			tessellator.draw();

			GlStateManager.popMatrix();
		}

		// Makes the rain go weird
		//GlStateManager.enableLighting();
	}

@Override
	public void doRender(EntityForceArrow arrow, double par2, double par4, double par6, float par8, float par9){

		this.bindEntityTexture(arrow);
		GlStateManager.pushMatrix();
		GlStateManager.disableLighting();
		OpenGlHelper.setLightmapTextureCoords(OpenGlHelper.lightmapTexUnit, 240f, 240f);

		GlStateManager.enableBlend();
		GlStateManager.blendFunc(GL11.GL_SRC_ALPHA, GL11.GL_ONE_MINUS_SRC_ALPHA);

		GlStateManager.translate((float)par2, (float)par4, (float)par6);
		GlStateManager.rotate(arrow.prevRotationYaw + (arrow.rotationYaw - arrow.prevRotationYaw) * par9 - 90.0F, 0.0F,
				1.0F, 0.0F);
		GlStateManager.rotate(arrow.prevRotationPitch + (arrow.rotationPitch - arrow.prevRotationPitch) * par9, 0.0F,
				0.0F, 1.0F);
		GlStateManager.rotate(180, 0, 1, 0);
		Tessellator tessellator = Tessellator.getInstance();
		BufferBuilder buffer = tessellator.getBuffer();
		float pixel = 1.0f / 32.0f;
		float u1 = 0.0f;
		float u2 = pixel * 14;
		float v1 = 0.0f;
		float v2 = pixel * 7;
		float u3 = pixel * 16;
		float u4 = 1.0f;
		float v3 = 0.0f;
		float v4 = pixel * 16;
		float u5 = 0.0f;
		float u6 = pixel * 7;
		float v5 = pixel * 25;
		float v6 = 1.0f;
		float scale = 0.05625F;
		float f11 = 0.0f;
		GlStateManager.enableRescaleNormal();
		// f11 = (float)par1EntityArrow.arrowShake - par9;
		if(f11 > 0.0F){
			float f12 = -MathHelper.sin(f11 * 3.0F) * f11;
			GlStateManager.rotate(f12, 0.0F, 0.0F, 1.0F);
		}

		scale *= 0.8f;

		GlStateManager.rotate(45.0F, 1.0F, 0.0F, 0.0F);
		GlStateManager.scale(scale, scale, scale);
		GlStateManager.translate(-4.0F, 0.0F, 0.0F);

		// Front
		buffer.begin(GL11.GL_QUADS, DefaultVertexFormats.POSITION_TEX);
		buffer.pos(-5, 3.5, -3.5).tex((double)u5, (double)v5).endVertex();
		buffer.pos(-5, 3.5, 3.5).tex((double)u6, (double)v5).endVertex();
		buffer.pos(-5, -3.5, 3.5).tex((double)u6, (double)v6).endVertex();
		buffer.pos(-5, -3.5, -3.5).tex((double)u5, (double)v6).endVertex();
		tessellator.draw();

		// Back
		buffer.begin(GL11.GL_QUADS, DefaultVertexFormats.POSITION_TEX);
		buffer.pos(-5, -3.5, -3.5).tex((double)u5, (double)v6).endVertex();
		buffer.pos(-5, -3.5, 3.5).tex((double)u6, (double)v6).endVertex();
		buffer.pos(-5, 3.5, 3.5).tex((double)u6, (double)v5).endVertex();
		buffer.pos(-5, 3.5, -3.5).tex((double)u5, (double)v5).endVertex();
		tessellator.draw();

		// Rings
		for(int i = 0; i < 5; i++){
			GlStateManager.color(1, 1, 1, 1 - i * 0.2f);
			double j = i + ((double)arrow.ticksExisted % 3) / 3;
			double width = 2.0d + (Math.sqrt(j * 2) - 0.6) * 2;
			GL11.glNormal3f(scale, 0.0F, 0.0F);
			buffer.begin(GL11.GL_QUADS, DefaultVertexFormats.POSITION_TEX);
			buffer.pos(-10 + j * 4, -width, -width).tex((double)u3, (double)v3).endVertex();
			buffer.pos(-10 + j * 4, -width, width).tex((double)u4, (double)v3).endVertex();
			buffer.pos(-10 + j * 4, width, width).tex((double)u4, (double)v4).endVertex();
			buffer.pos(-10 + j * 4, width, -width).tex((double)u3, (double)v4).endVertex();
			tessellator.draw();
			GL11.glNormal3f(-scale, 0.0F, 0.0F);
			buffer.begin(GL11.GL_QUADS, DefaultVertexFormats.POSITION_TEX);
			buffer.pos(-10 + j * 4, width, -width).tex((double)u3, (double)v3).endVertex();
			buffer.pos(-10 + j * 4, width, width).tex((double)u4, (double)v3).endVertex();
			buffer.pos(-10 + j * 4, -width, width).tex((double)u4, (double)v4).endVertex();
			buffer.pos(-10 + j * 4, -width, -width).tex((double)u3, (double)v4).endVertex();
			tessellator.draw();
		}

		GlStateManager.color(1, 1, 1, 1);

		// Sides
		for(int i = 0; i < 4; ++i){
			GlStateManager.rotate(90.0F, 1.0F, 0.0F, 0.0F);
			GL11.glNormal3f(0.0F, 0.0F, scale);
			buffer.begin(GL11.GL_QUADS, DefaultVertexFormats.POSITION_TEX);
			buffer.pos(-10.0D, -4.0D, 0.0D).tex((double)u1, (double)v1).endVertex();
			buffer.pos(10.0D, -4.0D, 0.0D).tex((double)u2, (double)v1).endVertex();
			buffer.pos(10.0D, 4.0D, 0.0D).tex((double)u2, (double)v2).endVertex();
			buffer.pos(-10.0D, 4.0D, 0.0D).tex((double)u1, (double)v2).endVertex();
			tessellator.draw();
		}

		GlStateManager.disableBlend();

		GlStateManager.disableRescaleNormal();
		GlStateManager.enableLighting();
		GlStateManager.popMatrix();
	}

public static void SHAPE_BEAM(World world, Vec3d target, Vec3d origin, Color color) {
		ParticleBuilder beam = new ParticleBuilder(10);
		beam.setRender(new ResourceLocation(Wizardry.MODID, MISC.SPARKLE_BLURRED));
		beam.setAlphaFunction(new InterpFloatInOut(0.3f, 1f));
		//beam.disableRandom();

		beam.setColor(ColorUtils.shiftColorHueRandomly(color, 10));
		beam.setCollision(true);

		Vec3d look = target.subtract(origin).normalize();
		double dist = target.distanceTo(origin);

		ParticleSpawner.spawn(beam, world, new StaticInterp<>(origin), 1, 0, (aFloat1, particleBuilder1) -> {
			particleBuilder1.setPositionOffset(look.scale(RandUtil.nextDouble(0, dist)));
			particleBuilder1.setScale(RandUtil.nextFloat(0.1f, 0.5f));
			final int life = RandUtil.nextInt(50, 60);
			particleBuilder1.setLifetime(life);
			particleBuilder1.enableMotionCalculation();
			particleBuilder1.setCollision(true);
			particleBuilder1.setCanBounce(true);
			particleBuilder1.setAcceleration(new Vec3d(0, -0.03, 0));

			double radius = 2;
			double theta = 2.0f * (float) Math.PI * RandUtil.nextFloat();
			double r = radius * RandUtil.nextFloat();
			double x = r * MathHelper.cos((float) theta);
			double z = r * MathHelper.sin((float) theta);
			Vec3d dest = new Vec3d(x, RandUtil.nextDouble(-1, 2), z);
			particleBuilder1.setPositionFunction(new InterpBezier3D(Vec3d.ZERO, dest, dest.scale(2), new Vec3d(dest.x, RandUtil.nextDouble(-2, 2), dest.z)));

			particleBuilder1.setTick(particle -> {
				if (particle.getAge() >= particle.getLifetime() / RandUtil.nextDouble(2, 5)) {
					if (particle.getAcceleration().y == 0)
						particle.setAcceleration(new Vec3d(0, RandUtil.nextDouble(-0.05, -0.01), 0));
				} else if (particle.getAcceleration().x != 0 || particle.getAcceleration().y != 0 || particle.getAcceleration().z != 0) {
					particle.setAcceleration(Vec3d.ZERO);
				}
			});
		});

		ParticleSpawner.spawn(beam, world, new StaticInterp<>(origin), 10, 0, (aFloat, particleBuilder) -> {
			particleBuilder.setTick(particle -> particle.setAcceleration(Vec3d.ZERO));

			particleBuilder.setScaleFunction(new InterpFloatInOut(0, 1f));
			particleBuilder.setAlphaFunction(new InterpFloatInOut(0.3f, 0.2f));
			particleBuilder.setScale(RandUtil.nextFloat(0.5f, 1.5f));
			particleBuilder.setLifetime(RandUtil.nextInt(10, 20));
			particleBuilder.disableMotionCalculation();
			particleBuilder.setMotion(Vec3d.ZERO);
			particleBuilder.setCanBounce(false);
			particleBuilder.setPositionOffset(Vec3d.ZERO);
			particleBuilder.setPositionFunction(new InterpLine(Vec3d.ZERO, target.subtract(origin)));
		});
	}

@Override
	public void doRenderLayer(@Nonnull EntityLivingBase entitylivingbaseIn, float limbSwing, float limbSwingAmount, float partialTicks, float ageInTicks, float netHeadYaw, float headPitch, float scale) {
		if (BaublesSupport.getItem(entitylivingbaseIn, ModItems.FAKE_HALO, ModItems.CREATIVE_HALO, ModItems.REAL_HALO).isEmpty())
			return;
		ItemStack halo = BaublesSupport.getItem(entitylivingbaseIn, ModItems.FAKE_HALO, ModItems.CREATIVE_HALO, ModItems.REAL_HALO);

		// TODO: Remove these once we have a cosmetics system
		if (halo.getItem() == ModItems.FAKE_HALO && !ClientConfigValues.renderCrudeHalo) return;
		if (halo.getItem() == ModItems.REAL_HALO && !ClientConfigValues.renderRealHalo) return;
		if (halo.getItem() == ModItems.CREATIVE_HALO && !ClientConfigValues.renderCreativeHalo) return;

		if (halo.getItem() == ModItems.FAKE_HALO) {
			GlStateManager.pushMatrix();

			if (entitylivingbaseIn.isSneaking()) GlStateManager.translate(0.0f, 0.2f, 0.0f);

			boolean flag = entitylivingbaseIn instanceof EntityVillager || entitylivingbaseIn instanceof EntityZombieVillager;

			if (entitylivingbaseIn.isChild() && !(entitylivingbaseIn instanceof EntityVillager)) {
				GlStateManager.translate(0.0f, 0.5f * scale, 0.0f);
				GlStateManager.scale(0.7f, 0.7f, 0.7f);
				GlStateManager.translate(0.0f, 16.0f * scale, 0.0f);
			}

			if (flag) GlStateManager.translate(0.0f, 0.1875f, 0.0f);

			this.modelRenderer.postRender(0.0625f);
			GlStateManager.color(1.0f, 1.0f, 1.0f, 1.0f);

			GlStateManager.translate(0.0f, -0.25f, 0.0f);
			GlStateManager.rotate(180.0f, 0.0f, 1.0f, 0.0f);
			GlStateManager.scale(0.625f, -0.625f, -0.625f);

			Minecraft.getMinecraft().getItemRenderer().renderItem(entitylivingbaseIn, halo, ItemCameraTransforms.TransformType.HEAD);

			GlStateManager.popMatrix();
		} else {
		    Entity entity = entitylivingbaseIn;

			Vec3d entityOrigin = entity.getPositionVector().add(0, entity.height + (entity.isSneaking() ? 0.2 : 0.4), 0);
			InterpCircle circle = new InterpCircle(Vec3d.ZERO, new Vec3d(0, 1, 0), 0.3f, RandUtil.nextFloat(), RandUtil.nextFloat());

			for (Vec3d origin : circle.list(5)) {
				RenderFunction baseRenderFunction = new RenderFunctionBasic(new ResourceLocation(Wizardry.MODID, NBTConstants.MISC.SPARKLE_BLURRED), false);
				ParticleBuilder glitter = new ParticleBuilder(3);
				glitter.setAlphaFunction(new InterpFloatInOut(1f, 1f));
				glitter.disableMotionCalculation();
				glitter.disableRandom();

				ParticleSpawner.spawn(glitter, entity.world, new StaticInterp<>(entityOrigin.add(origin)), 1, 0, (aFloat, particleBuilder) -> {
					if (RandUtil.nextInt(10) != 0)
						if (halo.getItem() == ModItems.CREATIVE_HALO)
							glitter.setColor(ColorUtils.changeColorAlpha(new Color(0xd600d2), RandUtil.nextInt(60, 100)));
						else glitter.setColor(ColorUtils.changeColorAlpha(Color.YELLOW, RandUtil.nextInt(60, 100)));
					else glitter.setColor(ColorUtils.changeColorAlpha(Color.WHITE, RandUtil.nextInt(60, 100)));
					glitter.setAlphaFunction(new InterpFloatInOut(0.5f, 0.5f));
					glitter.setLifetime(10);
					glitter.setScaleFunction(new InterpFloatInOut(0.5f, 0.5f));

					glitter.setRenderFunction(
							new RenderFunction(ParticleRenderManager.getLAYER_BLOCK_MAP_ADDITIVE()) {
								@Override
								public void render(float i,
												   @NotNull ParticleBase particle, @NotNull Color color, float alpha,
												   @NotNull BufferBuilder worldRendererIn, @Nullable Entity entityIn,
												   float partialTicks, float rotationX, float rotationZ,
												   float rotationYZ, float rotationXY, float rotationXZ,
												   float scale, float rotation, @NotNull Vec3d pos,
												   int skyLight, int blockLight) {

									Vec3d interpPos =
											new Vec3d(
//													ClientTickHandler.interpPartialTicks(entity.prevPosX, entity.posX) - Particle.interpPosX,
//													ClientTickHandler.interpPartialTicks(entity.prevPosY, entity.posY) - Particle.interpPosY,
//													ClientTickHandler.interpPartialTicks(entity.prevPosZ, entity.posZ) - Particle.interpPosZ
													entity.prevPosX + (entity.posX - entity.prevPosX) * ClientTickHandler.getPartialTicks() - Particle.interpPosX,
													entity.prevPosY + (entity.posY - entity.prevPosY) * ClientTickHandler.getPartialTicks() - Particle.interpPosY,
													entity.prevPosZ + (entity.posZ - entity.prevPosZ) * ClientTickHandler.getPartialTicks() - Particle.interpPosZ
											);
									Vec3d newPos = interpPos
											.add(0, entity.height + (entity.isSneaking() ? 0.2 : 0.4), 0)
											.add(origin);

									baseRenderFunction.render(i,
											particle, color, alpha,
											worldRendererIn, entityIn,
											partialTicks, rotationX, rotationZ,
											rotationYZ, rotationXY, rotationXZ,
											scale, rotation, newPos,
											skyLight, blockLight);
								}
							}
					);
				});
			}
		}
	}

private void renderSpinningCubes(PoseStack ms, MultiBufferSource buffers, int overlay, int cubes, int iters) {
		for (int curIter = iters; curIter > 0; curIter--) {
			final float modifier = 6F;
			final float rotationModifier = 0.2F;
			final float radiusBase = 0.35F;
			final float radiusMod = 0.05F;

			double ticks = ClientTickHandler.ticksInGame + ClientTickHandler.partialTicks - 1.3 * (iters - curIter);
			float offsetPerCube = 360 / cubes;

			ms.pushPose();
			ms.translate(-0.025F, 0.85F, -0.025F);
			for (int i = 0; i < cubes; i++) {
				float offset = offsetPerCube * i;
				float deg = (int) (ticks / rotationModifier % 360F + offset);
				float rad = VecHelper.toRadians(deg);
				float radiusX = (float) (radiusBase + radiusMod * Math.sin(ticks / modifier));
				float radiusZ = (float) (radiusBase + radiusMod * Math.cos(ticks / modifier));
				float x = (float) (radiusX * Math.cos(rad));
				float z = (float) (radiusZ * Math.sin(rad));
				float y = (float) Math.cos((ticks + 50 * i) / 5F) / 10F;

				ms.pushPose();
				ms.translate(x, y, z);
				float xRotate = (float) Math.sin(ticks * rotationModifier) / 2F;
				float yRotate = (float) Math.max(0.6F, Math.sin(ticks * 0.1F) / 2F + 0.5F);
				float zRotate = (float) Math.cos(ticks * rotationModifier) / 2F;

				ms.mulPose(new Quaternionf().rotateAxis(rad, xRotate, yRotate, zRotate));
				float alpha = 1;
				if (curIter < iters) {
					alpha = (float) curIter / (float) iters * 0.4F;
				}

				VertexConsumer buffer = buffers.getBuffer(curIter < iters ? RenderType.entityTranslucentCull(cubeTex) : RenderType.entitySolid(cubeTex));
				spinningCube.render(ms, buffer, 0xF000F0, overlay, 1, 1, 1, alpha);

				ms.popPose();
			}
			ms.popPose();
		}
	}

@Override
	public void doRender(EntityFireRing entity, double x, double y, double z, float entityYaw, float partialTicks){

		GlStateManager.pushMatrix();
		GlStateManager.enableBlend();
		GlStateManager.disableLighting();
		OpenGlHelper.setLightmapTextureCoords(OpenGlHelper.lightmapTexUnit, 240, 240);
		GlStateManager.blendFunc(GL11.GL_SRC_ALPHA, GL11.GL_ONE_MINUS_SRC_ALPHA);

		float yOffset = 0;

		GlStateManager.translate(x, y + yOffset, z);

		this.bindTexture(texture);
		float f6 = 1.0F;
		float f7 = 0.5F;
		float f8 = 0.5F;

		GlStateManager.rotate(-90, 1, 0, 0);

		float s = DrawingUtils.smoothScaleFactor(entity.lifetime, entity.ticksExisted, partialTicks, 10, 10);
		GlStateManager.scale(entity.width * s, entity.width * s, entity.width * s);

		Tessellator tessellator = Tessellator.getInstance();
