				GlStateManager.translate(0, 0, 2.3f * s1);

				buffer.begin(GL11.GL_QUADS, DefaultVertexFormats.POSITION_TEX);

				while(f4 > 0.0F){

					this.bindTexture(TextureMap.LOCATION_BLOCKS_TEXTURE);
					float f71 = icon.getMinU();
					float f81 = icon.getMinV();
					float f9 = icon.getMaxU();
					float f10 = icon.getMaxV();

					if(i / 2 % 2 == 0){
						float f11 = f9;
						f9 = f71;
						f71 = f11;
					}

					buffer.pos((f2 - f3), (0.0F - f5), f61).tex(f9, f10).endVertex();
					buffer.pos((-f2 - f3), (0.0F - f5), f61).tex(f71, f10).endVertex();
					buffer.pos((-f2 - f3), (height - f5), f61).tex(f71, f81).endVertex();
					buffer.pos((f2 - f3), (height - f5), f61).tex(f9, f81).endVertex();
					f4 -= 0.45F;
					f5 -= 0.45F;
					f2 *= 0.9F;
					f61 += 0.03F;
					++i;
				}

				tessellator.draw();
				GlStateManager.popMatrix();
			}
		}

		GlStateManager.enableLighting();
	}

public Vector4f getUVs(IParticle particle, float partialTicks) {
        var t = particle.getT(partialTicks);
        var cellU = 1f / tiles.x();
        var cellV = 1f / tiles.y();
        var currentFrame = this.startFrame.get(t, () -> particle.getMemRandom("startFrame")).floatValue();
        currentFrame += cycle * frameOverTime.get(t, () -> particle.getMemRandom("frameOverTime")).floatValue();
        float u0, v0, u1, v1;
        var cellSize = tiles.x();
        if (animation == Animation.WholeSheet) {
            // wrap into the sheet so frames past tiles.x*tiles.y don't sample outside the texture
            int frame = Math.floorMod((int) currentFrame, tiles.x() * tiles.y());
            int X = frame % cellSize;
            int Y = frame / cellSize;
            u0 = X * cellU;
            v0 = Y * cellV;
        } else {
            int X = (int) (currentFrame % cellSize);
            int Y = (int) (particle.getMemRandom("randomRow") * tiles.y());
            u0 = X * cellU;
            v0 = Y * cellV;
        }
        u1 = u0 + cellU;
        v1 = v0 + cellV;
        return new Vector4f(u0, v0, u1, v1);
    }

public FXRuntime(FXData fxData) {
        this.fxData = fxData;
        // created before any object is added, so addSceneObjectInternal is the ONE place that wires
        // per-object keep-alive — for construction and editor additions alike
        this.timelinePlayer = new TimelinePlayer(this, fxData.timeline());
        this.root = new EmptyFXObject();
        this.root.transform()._setInternalID(ROOT_UUID);
        addSceneObject(root);
        root.setName("root");
        initRuntime();
        // the always-on root drives the timeline once per tick (editor + in-world)
        if (root instanceof FXObject fxRoot) {
            fxRoot.setOnUpdateTick(() -> {
                // ⚠️ Re-applied every tick, not only in setRate: FXObject.reset() puts selfTimeScale
                // back to 1, and a control clip restarting a subtree resets the root with it. Runs
                // before the timeline's own speed tracks (evaluate -> applySpeed), so a track that
                // targets the root deliberately wins for that tick — see setRate.
                root.setSelfTimeScale(rate);
                if (!timelinePlayer.isEmpty()) {
                    timelinePlayer.tick(rate);
                }
            });
            // and the per-frame animation pass for smooth (interpolated) transform animation
            fxRoot.setOnUpdateFrame(partialTicks -> {
                if (!timelinePlayer.isEmpty()) {
                    timelinePlayer.frame(partialTicks);
                }
            });
        }
    }

public void emit(IEffectExecutor effect, int delay) {
        emitted = true;
        destroyed = false;
        // track the owning engine for isValid(): same resolution as IFXObject.emit's engine pick
        this.host = effect.getLevel() instanceof DummyWorld dummyWorld
                && dummyWorld.getParticleManager() instanceof ParticleTickHost tickHost
                ? tickHost : VanillaParticleHost.INSTANCE;
        this.generationAtEmit = host.generation();
        if (root instanceof FXObject fxRoot) {
            fxRoot.setTickHost(host);
            fxRoot.setLastHostTick(host.tickCount());
        }
        for (var fxObject : objects.values()) {
            fxObject.emit(effect);
            // set after emit: emit() resets the object, which zeroes its delay
            fxObject.setDelay(delay);
        }
        timelinePlayer.begin(effect);
    }

public boolean isValid() {
        if (!emitted || destroyed) {
            return false;
        }
        if (host == null || !(root instanceof FXObject fxRoot)) {
            return true; // untrackable host: degrade to the state flags above
        }
        if (generationAtEmit != host.generation()) {
            return false;
        }
        // <=1: isValid may be queried mid-engine-tick, before the root has ticked this round
        return host.tickCount() - fxRoot.getLastHostTick() <= 1;
    }

public void destroy(boolean force) {
        destroyed = true;
        timelinePlayer.stop();
        for (var fxObject : objects.values()) {
            fxObject.remove(force);
        }
    }

public TailArray generateSmoothPath(TailArray vertices, TailArray lastSmooth, float distance) {
    if (vertices.size() <= 2) {
        return vertices;
    }

    TailArray smoothPath = new TailArray();
    float minDistanceSq = Math.max(distance, 0.05f) * Math.max(distance, 0.05f);
    Vector3f prevDir = null;

    for (int i = 0; i < vertices.size() - 1; i++) {
        var curr = vertices.getPosition(i);
        var next = vertices.getPosition(i + 1);
        var dir = new Vector3f(next).sub(curr).normalize();
        smoothPath.add(vertices.copyAsTail(i));

        if (prevDir != null && dir.dot(prevDir) > 0.99f) {
            // skip interpolation if angle is small
            prevDir = dir;
            continue;
        }

        float distSq = curr.distanceSquared(next);
        if (distSq > minDistanceSq) {
            int steps = (int) (distSq / minDistanceSq);
            for (int j = 1; j < steps; j++) {
                float t = j / (float) steps;
                Vector3f interpPos = catmullRomInterpolate(
                        vertices.getPosition(Math.max(i - 1, 0)),
                        curr, next,
                        vertices.getPosition(Math.min(i + 2, vertices.size() - 1)), t);
                // build interpolated tail
                smoothPath.add(new Tail(
                        interpPos,
                        Mth.lerp(t, vertices.lifeTime[i], vertices.lifeTime[i + 1]),
                        new Vector4f(vertices.getColor(i)).lerp(vertices.getColor(i + 1), t),
                        Mth.lerp(t, vertices.width[i], vertices.width[i + 1])
                ));
            }
        }
        prevDir = dir;
    }
    smoothPath.add(vertices.copyAsTail(vertices.size() - 1));
    return smoothPath;
}

private StretchedFrame computeStretchedFrame(TileParticle particle, Vector3f worldPos,
                                             double camX, double camY, double camZ,
                                             Vector3f size, Vector3f spaceScale) {
    Vector3f vel = particle.getRealVelocity();
    float speed = vel.length();

    Vector3f right = new Vector3f();
    if (speed > 1e-5f) {
        right.set(vel).div(speed);
    } else {
        right.set(1, 0, 0);
    }

    Vector3f dirToCam = new Vector3f((float) (camX - worldPos.x), (float) (camY - worldPos.y), (float) (camZ - worldPos.z));
    if (dirToCam.lengthSquared() > 1e-5f) {
        dirToCam.normalize();
    } else {
        dirToCam.set(0, 0, 1);
    }

    Vector3f up = new Vector3f();
    dirToCam.cross(right, up);

    if (up.lengthSquared() < 1e-5f) {
        if (Math.abs(right.y) > 0.99f) {
            up.set(0, 0, 1).cross(right).normalize();
        } else {
            up.set(0, 1, 0).cross(right).normalize();
        }
    } else {
        up.normalize();
    }

    Vector3f forward = new Vector3f();
    right.cross(up, forward).normalize();

    Matrix3f mat = new Matrix3f(
            right.x,   right.y,   right.z,
            up.x,      up.y,      up.z,
            forward.x, forward.y, forward.z
    );
    var quaternion = new Quaternionf().setFromNormalized(mat);

    float stretch = renderer.getLengthScale() + speed * renderer.getVelocityScale();
    float stretchedSizeX = size.x * stretch;

    float offsetAmount = (stretchedSizeX - size.x) * spaceScale.x;
    return new StretchedFrame(quaternion, stretchedSizeX,
            right.x * offsetAmount, right.y * offsetAmount, right.z * offsetAmount);
}

@Override
public void updateFXObjectFrame(IFXObject fxObject, float partialTicks) {
    if (runtime != null && fxObject == runtime.root) {
        if (!entity.isAlive()) return;
        var position = entity.getEyePosition(partialTicks);
        runtime.root.updatePos(new Vector3f((float) (position.x + offset.x), (float) (position.y + offset.y), (float) (position.z + offset.z)));
        if (autoRotate != AutoRotate.NONE) {
            switch (autoRotate) {
                case FORWARD -> {
                    var forward = entity.getForward();
                    var newRotation = new Quaternionf(rotation).rotateXYZ(
                            0,
                            (float) Math.atan2(-forward.z, forward.x),
                            (float) forward.y
                    );
                    runtime.root.updateRotation(newRotation);
                }
                case LOOK -> {
                    var lookAngles = entity.getLookAngle();
                    var newRotation = new Quaternionf(rotation).rotateXYZ(
                            0,
                            (float) Math.atan2(-lookAngles.z, lookAngles.x),
                            (float) lookAngles.y
                    );
                    runtime.root.updateRotation(newRotation);
                }
                case XROT -> {
                    var newRotation = new Quaternionf(rotation).rotateXYZ(
                            0,
                            Math.toRadians(-90 - entity.getVisualRotationYInDegrees()),
                            0
                    );
                    runtime.root.updateRotation(newRotation);
                }
            }
        }
    }
}

public void emitParticle(float dt) {
    updateLightRegistration();
    // calculate distance (scaled by this step's dt)
    accumulatedDistance += getVelocity().length() * dt;
    // emit new particle (maxParticles may be timeline-overridden; authored value is the fallback)
    var maxParticles = runtime().maxParticles.get();
    var particleAmount = getParticleAmount(); // streams all queues — compute once per call
    if (!removed && particleAmount < maxParticles) {
        var emissionCount = runtime().emission.getEmissionCount(this, getRandomSource(), dt);
        var available = Math.min(emissionCount, maxParticles - particleAmount);
        particleBatchCount = Math.max(1, available);
        particleBatchCursor = 0;
        for (int i = 0; i < available; i++) {
            emitParticle(createNewParticle());
        }
    }

    // particles life cycle
    if (!waitToAdded.isEmpty()) {
        for (var p : waitToAdded) {
            // modest initial capacity: maxParticles is timeline-drivable and may be huge
            particles.computeIfAbsent(p.getRenderType(), type -> new ArrayDeque<>(Math.min(maxParticles, 256))).add(p);
        }
        waitToAdded.clear();
    }

    var parallelAllowed = useParallelUpdate();
    for (var queue : particles.values()) {
        if (parallelAllowed && queue.size() >= PARALLEL_UPDATE_MIN_PARTICLES) { // parallel stream for particles tick.
            queue.removeIf(p -> !p.isAlive());
            setParallelLightPhase(true);
            try {
                queue.parallelStream().forEach(p -> p.updateTick(dt));
            } finally {
                setParallelLightPhase(false);
            }
        } else {
            var iter = queue.iterator();
            while (iter.hasNext()) {
                var particle = iter.next();
                if (!particle.isAlive()) {
                    iter.remove();
                } else {
                    particle.updateTick(dt);
                }
            }
        }
    }
    if (parallelAllowed) {
        // refresh every light position requested this tick on the game thread
        // (parallel reads only consult the cache; misses used the last value)
        rebuildLightCache();
    }

    // drain sub-emitter spawns collected during (possibly parallel) particle updates
    for (Runnable spawn; (spawn = pendingSubEmitterSpawns.poll()) != null; ) {
        spawn.run();
    }
}

private void walkSpan(AraTrailParticle particle, int start, int end, Vector3f localCamPosition, PointSink sink) {
    var config = particle.config;
    var runtime = particle.runtime;

    // Get a list of the actual points to render: either the original, unsmoothed points or the smoothed curve.
    ElasticArray<Point> trail = getRenderablePoints(particle, start, end);

    if (config.sorting == AraTrailConfig.TrailSorting.NewerOnTop)
        trail.reverse();

    var data = trail.getData();

    if (trail.size() > 1) {
        float totalLength = 0;
        for (int i = 0; i < trail.size() - 1; ++i)
            totalLength += data[i].position.distance(data[i + 1].position); // read-only, no copy needed

        totalLength = Math.max(totalLength, EPSILON);
        float partialLength = 0;
        // U runs along the trail length. Anchor U at the head (newest point) and decrease toward the
        // tail so the direction matches TrailParticle: head -> U=1, tail -> U=0 (WorldTile derives U
        // from texcoord below and is unaffected).
        float vCoord = config.textureMode == AraTrailConfig.TextureMode.Stretch ?
                config.uvFactor :
                config.uvFactor * totalLength * (1 - config.tileAnchor);

        if (config.sorting == AraTrailConfig.TrailSorting.NewerOnTop)
            vCoord = 1 - vCoord;

        // Initialize curve frame using the first two points to calculate the first tangent vector:
        CurveFrame frame = initializeCurveFrame(particle, data[trail.size() - 1].position,
                data[trail.size() - 2].position);

        flatVa = 1;
        flatVb = 0;

        // ---- hoisted loop invariants (bit-identical: these were recomputed per point) ----
        float normalizedLife = Math.clamp(particle.emitter.getT(), 0, 1);
        float lifeTime = particle.getLifeTime();
        var colorMultiplier = particle.getColorMultiplier();
        float thicknessMultiplier = particle.getThicknessMultiplier();
        float baseThickness = runtime.thickness.get();
        var colorOverLength = runtime.colorOverLength.get();
        var colorOverSegmentTime = runtime.colorOverSegmentTime.get();
        var thicknessOverSegmentTime = runtime.thicknessOverSegmentTime.get();
        var thicknessOverLength = runtime.thicknessOverLength.get();
        java.util.function.Supplier<Float> lengthColorRandom = () -> particle.getMemRandom("trails-colorOverLength");
        java.util.function.Supplier<Float> segmentColorRandom = () -> particle.getMemRandom("trails-colorOverSegmentTime");
        java.util.function.Supplier<Float> segmentThicknessRandom = () -> particle.getMemRandom("trails-thicknessOverSegmentTime");
        java.util.function.Supplier<Float> lengthThicknessRandom = () -> particle.getMemRandom("trails-thicknessOverLength");
        // colorOverTime / thicknessOverTime sample the (per-trail constant) emitter T
        var timeColor = runtime.colorOverTime.get().get(normalizedLife, () -> particle.getMemRandom("trails-colorOverTime")).intValue();
        float timeColorR = ColorUtils.red(timeColor);
        float timeColorG = ColorUtils.green(timeColor);
        float timeColorB = ColorUtils.blue(timeColor);
        float timeColorA = ColorUtils.alpha(timeColor);
        float timeThickness = runtime.thicknessOverTime.get().get(normalizedLife, () -> particle.getMemRandom("trails-thicknessOverTime")).floatValue();

        for (int i = trail.size() - 1; i >= 0; --i)
        {

            // Calculate next and previous point indices:
            int nextIndex = Math.max(i - 1, 0);
            int prevIndex = Math.min(i + 1, trail.size() - 1);

            // Calculate next and previous trail vectors:
            nextV.x = data[nextIndex].position.x - data[i].position.x;
            nextV.y = data[nextIndex].position.y - data[i].position.y;
            nextV.z = data[nextIndex].position.z - data[i].position.z;

            prevV.x = data[i].position.x - data[prevIndex].position.x;
            prevV.y = data[i].position.y - data[prevIndex].position.y;
            prevV.z = data[i].position.z - data[prevIndex].position.z;

            float sectionLength = nextIndex == i ? prevV.length() : nextV.length();

            // Guard the trail ends: nextIndex/prevIndex clamp to i there, so one neighbour vector is
            // (0,0,0), and normalize((0,0,0)) yields NaN which poisons the tangent/bitangent -> NaN
            // end-cap vertices. Fall back to the available direction so the end cap keeps a valid frame.
            boolean nextZero = nextV.lengthSquared() < EPSILON;
            boolean prevZero = prevV.lengthSquared() < EPSILON;
            if (!nextZero) nextV.normalize();
            if (!prevZero) prevV.normalize();
            if (nextZero) nextV.set(prevV);   // tail end: reuse the (normalized) prev direction
            if (prevZero) prevV.set(nextV);   // head end: reuse the (normalized) next direction

            // Calculate tangent vector:
            if (config.alignment == AraTrailConfig.TrailAlignment.Local)
                tangent = new Vector4f(data[i].tangent.normalize(new Vector3f()), 0);
            else
            {
                tangent.x = (nextV.x + prevV.x) * 0.5f;
                tangent.y = (nextV.y + prevV.y) * 0.5f;
                tangent.z = (nextV.z + prevV.z) * 0.5f;
            }

            // Calculate normal vector:
            normal = new Vector3f(data[i].normal);
            if (config.alignment != AraTrailConfig.TrailAlignment.Local)
                normal = config.alignment == AraTrailConfig.TrailAlignment.View ?
                        new Vector3f(localCamPosition).sub(data[i].position) :
                        frame.transport(new Vector3f(tangent.x, tangent.y, tangent.z), data[i].position);
            normal.normalize();

            // Calculate bitangent vector:
            if (config.alignment == AraTrailConfig.TrailAlignment.Velocity)
                bitangent = frame.bitangent;
            else
            {
                // cross(tangent, normal):
                bitangent.x = tangent.y * normal.z - tangent.z * normal.y;
                bitangent.y = tangent.z * normal.x - tangent.x * normal.z;
                bitangent.z = tangent.x * normal.y - tangent.y * normal.x;
            }
            bitangent.normalize();

            // Calculate this point's normalized (0,1) lenght and life.
            walkNormalizedLength = config.sorting == AraTrailConfig.TrailSorting.OlderOnTop ?
                    partialLength / totalLength :
                    (totalLength - partialLength) / totalLength;
            partialLength += sectionLength;
            walkNormalizedSegmentLife = Float.isInfinite(lifeTime) ? 1 : Mth.clamp(1 - data[i].life / lifeTime, 0, 1);

            // Calculate vertex color:
            var lengthColor = colorOverLength.get(walkNormalizedLength, lengthColorRandom).intValue();
            var segmentColor = colorOverSegmentTime.get(walkNormalizedSegmentLife, segmentColorRandom).intValue();
            color = new Vector4f(data[i].color).mul(colorMultiplier).mul(
                    timeColorR * ColorUtils.red(lengthColor) * ColorUtils.red(segmentColor),
                    timeColorG * ColorUtils.green(lengthColor) * ColorUtils.green(segmentColor),
                    timeColorB * ColorUtils.blue(lengthColor) * ColorUtils.blue(segmentColor),
                    timeColorA * ColorUtils.alpha(lengthColor) * ColorUtils.alpha(segmentColor)
            );

            // Calculate final thickness:
            walkSectionThickness = baseThickness * thicknessMultiplier * data[i].thickness *
                    timeThickness *
                    thicknessOverSegmentTime.get(walkNormalizedSegmentLife, segmentThicknessRandom).floatValue() *
                    thicknessOverLength.get(walkNormalizedLength, lengthThicknessRandom).floatValue();

            // In world tile mode, override texture coordinate with the point's one:
            if (config.textureMode == AraTrailConfig.TextureMode.WorldTile)
                vCoord = config.tileAnchor + data[i].texcoord * config.uvFactor;

            sink.point(particle, data, i, trail.size(), frame, vCoord);

            // Update vcoord:
            float uvDelta = (config.textureMode == AraTrailConfig.TextureMode.Stretch ? sectionLength / totalLength : sectionLength);
            vCoord += config.uvFactor * (config.sorting == AraTrailConfig.TrailSorting.NewerOnTop ? uvDelta : -uvDelta);
        }
    }
}

private int[] appendFlatTrail(AraTrailConfig config, Point[] data, int i, int count, float sectionThickness, float vCoord, int va, int vb) {
    boolean hqCorners = config.highQualityCorners && config.alignment != AraTrailConfig.TrailAlignment.Local;

    Quaternionf q = new Quaternionf();
    Vector3f corner = new Vector3f();
    float curvatureSign = 0;
    float correctedThickness = sectionThickness;
    Vector3f prevSectionBitangent = bitangent;

    // High-quality corners:
    if (hqCorners) {

        Vector3f nextSectionBitangent = i == 0 ? bitangent :
                nextV.cross(bitangent.cross(new Vector3f(tangent.x, tangent.y, tangent.z), new Vector3f()), new Vector3f()).normalize();

        // If round corners are enabled:
        if (config.cornerRoundness > 0) {

            prevSectionBitangent = i == count - 1 ? bitangent.negate(new Vector3f()) :
                    prevV.cross(bitangent.cross(new Vector3f(tangent.x, tangent.y, tangent.z), new Vector3f()), new Vector3f()).normalize();

            // Calculate "elbow" angle:
            curvatureSign = (i == 0 || i == count - 1) ? 1 : Math.signum(nextV.dot(prevSectionBitangent.negate(new Vector3f())));
            float angle = (i == 0 || i == count - 1) ? (float) Math.PI :
                    (float) Math.acos(Math.max(-1, Math.min(1, nextSectionBitangent.dot(prevSectionBitangent))));

            // Prepare a quaternion for incremental rotation of the corner vector:
            q.fromAxisAngleRad(normal.mul(curvatureSign, new Vector3f()), angle / config.cornerRoundness);
            corner = prevSectionBitangent.mul(sectionThickness * curvatureSign, new Vector3f());
        }

        // Calculate correct thickness by projecting corner bitangent onto the next section bitangent. This prevents "squeezing"
        if (nextSectionBitangent.lengthSquared() > 0.1f)
            correctedThickness = sectionThickness / Math.max(bitangent.dot(nextSectionBitangent), 0.15f);

    }

    // Append straight section mesh data:
    if (hqCorners && config.cornerRoundness > 0) {
        // bitangents are slightly asymmetrical in case of high-quality round or sharp corners:
        if (curvatureSign > 0) {
            vertices.add(data[i].position.add(prevSectionBitangent.mul(sectionThickness, new Vector3f()), new Vector3f()));
            vertices.add(data[i].position.sub(bitangent.mul(correctedThickness, new Vector3f()), new Vector3f()));
        } else {
            vertices.add(data[i].position.add(bitangent.mul(correctedThickness, new Vector3f()), new Vector3f()));
            vertices.add(data[i].position.sub(prevSectionBitangent.mul(sectionThickness, new Vector3f()), new Vector3f()));
        }
    } else {
        vertices.add(data[i].position.add(bitangent.mul(correctedThickness, new Vector3f()), new Vector3f()));
        vertices.add(data[i].position.sub(bitangent.mul(correctedThickness, new Vector3f()), new Vector3f()));
    }

    var normal = new Vector3f(this.normal);
    normals.add(normal);
    normals.add(normal);

    var tangent = new Vector4f(this.tangent);
    tangents.add(tangent);
    tangents.add(tangent);

    var color = new Vector4f(this.color);
    vertColors.add(color);
    vertColors.add(color);

    uv.set(vCoord, config.sorting == AraTrailConfig.TrailSorting.NewerOnTop ? config.uvWidthFactor : 0);
    uvs.add(new Vector2f(uv));
    uv.set(vCoord, config.sorting == AraTrailConfig.TrailSorting.NewerOnTop ? 0 : config.uvWidthFactor);
    uvs.add(new Vector2f(uv));

    if (i < count - 1) {
        int vc = vertices.size() - 1;
        tris.add(vc);
        tris.add(va);
        tris.add(vb);

        tris.add(vb);
        tris.add(vc - 1);
        tris.add(vc);
    }

    va = vertices.size() - 1;
    vb = vertices.size() - 2;

    // Append smooth corner mesh data:
    if (hqCorners && config.cornerRoundness > 0) {
        for (int p = 0; p <= config.cornerRoundness; ++p) {
            vertices.add(data[i].position.add(corner, new Vector3f()));
            normals.add(normal);
            tangents.add(tangent);
            vertColors.add(color);
            uv.set(vCoord, curvatureSign > 0 ? 0 : 1);
            uvs.add(new Vector2f(uv));

            int vc = vertices.size() - 1;

            tris.add(vc);
            tris.add(va);
            tris.add(vb);

            if (curvatureSign > 0)
                vb = vc;
            else va = vc;

            // rotate corner point:
            corner = q.transform(corner);
        }
    }
    return new int[]{va, vb};
}

static Quaternionf computeLookAtDirection(Vector3f direction, Vector3f particlePos, Vector3f cameraPos) {
    Vector3f dir = normalizeDirection(direction, false);
    if (dir.lengthSquared() < MIN_THRESHOLD) {
        return computeLookAtXYZ(particlePos, cameraPos);
    }

    Quaternionf axisRotation = new Quaternionf().rotationTo(LOCAL_X, dir);
    Vector3f cameraInAxisSpace = new Vector3f(cameraPos).sub(particlePos);
    if (cameraInAxisSpace.lengthSquared() < MIN_THRESHOLD) {
        return axisRotation;
    }
    new Quaternionf(axisRotation).conjugate().transform(cameraInAxisSpace);

    float xRotation = (float) Math.atan2(-cameraInAxisSpace.y, cameraInAxisSpace.z);
    return new Quaternionf(axisRotation).mul(new Quaternionf().rotationX(xRotation));
}

public void setup() {
    if (emitter instanceof ParticleEmitter particleEmitter) {
        particleBatchIndex = particleEmitter.nextParticleBatchIndex();
        particleBatchCount = particleEmitter.getParticleBatchCount();
    } else {
        particleBatchIndex = 0;
        particleBatchCount = 1;
    }
    var emitterT = emitter.getT();
    // start values come from the runtime layer (timeline override if set, else authored config)
    setDelay(runtime.startDelay.get().get(randomSource, emitterT).intValue());
    if (runtime.lifetimeByEmitterSpeed.isEnable()) {
        setLifetime(runtime.lifetimeByEmitterSpeed.getLifetime(this, emitter,
                runtime.startLifetime.get().get(randomSource, emitterT).intValue()));
    } else {
        setLifetime(runtime.startLifetime.get().get(randomSource, emitterT).intValue());
    }

    runtime.shape.setupParticle(this, emitter);
    // the shape wrote emitter-local position/velocity; for non-Local simulation spaces,
    // re-express them in simulation space using the emitter's spawn-time pose
    if (config.getSimulationSpace() != ParticleConfig.Space.Local) {
        var emitterToWorld = emitter.transform().localToWorldMatrix();
        var worldToSim = emitter.getWorldToSim();
        var pos = new Vector3f(localX, localY, localZ).mulPosition(emitterToWorld).mulPosition(worldToSim);
        setSimPos(pos, true);
        var vel = worldToSim.transformDirection(emitterToWorld.transformDirection(new Vector3f(velocityX, velocityY, velocityZ)));
        setInternalVelocity(vel);
        // the frame we are born into, shared with every particle emitted at this emitter pose
        this.spawnFrame = emitter instanceof ParticleEmitter particleEmitter
                ? particleEmitter.currentSpawnFrame()
                : new SpawnFrame(emitterToWorld, emitter.transform().worldToLocalMatrix(),
                        worldToSim, emitter.getSimToWorld());
    }
    if (runtime.inheritVelocity.isEnable() && runtime.inheritVelocity.getMode() == InheritVelocitySetting.Mode.INITIAL) {
        addInternalVelocity(getSpaceTransformInverse().transformDirection(runtime.inheritVelocity.getVelocity(emitter)));
    }
    mulInternalVelocity(runtime.startSpeed.get().get(randomSource, emitterT).floatValue());
    this.initialSize = runtime.startSize.get().get(randomSource, emitterT);
    // non-Local particles are not rendered through the emitter matrix, so bake the emitter's
    // spawn-time scale (relative to the simulation space) into the size instead
    if (config.getSimulationSpace() != ParticleConfig.Space.Local) {
        this.initialSize.mul(emitter.transform().scale().div(emitter.getSimSpaceScale()));
    }
    this.initialRotation = runtime.startRotation.get().get(randomSource, emitterT).mul(Mth.TWO_PI / 360);
    var color = runtime.startColor.get().get(randomSource, emitterT).intValue();
    this.initialColor = new Vector4f(ColorUtils.red(color), ColorUtils.green(color), ColorUtils.blue(color), ColorUtils.alpha(color));
    setSize(initialSize);
    setRotation(initialRotation);
    setColor(initialColor);
    update(1f);
    // update() skips the pure visual recomputes during a timeline seek, on the promise that the
    // seek's last two full ticks redo them. A particle with a START DELAY never reaches them:
    // updateTick returns early for the whole delay, so the frame it first becomes visible on --
    // the one right after the delay hits 0 -- still carries the raw birth values, with every
    // over-lifetime curve unapplied. Redo them here, where it is correct for every path.
    if (PhotonParticleManager.isFastSimulation()) {
        updateColor();
        updateSize();
        updateRotation();
        updateLight();
    }
    updateOrigin();

    if (runtime.trails.isEnable() && emitter instanceof ParticleEmitter particleEmitter) {
        runtime.trails.setup(particleEmitter, this);
    }
}

public void updateTick(float dt) {
    if (delay > 0) {
        delay -= dt;
        return;
    }

    if (this.age == 0 && runtime.subEmitters.isEnable()) {
        runtime.subEmitters.triggerEvent(this, SubEmittersSetting.Event.Birth);
    }

    // death: snap t to 1 and apply the final visual state (no motion) so over-lifetime curves
    // reach their endpoints on the frames the dead particle still renders before removal.
    // lifetime <= 0 intentionally never age-dies (infinite particles; they die via collision
    // or emitter removal).
    if (this.age >= this.lifetime && lifetime > 0) {
        this.age += dt;
        this.t = 1;
        this.updateColor();
        this.updateSize();
        this.updateRotation();
        this.updateLight();
        setRemoved(true);
        if (runtime.subEmitters.isEnable()) {
            runtime.subEmitters.triggerEvent(this, SubEmittersSetting.Event.Death);
        }
        return;
    }
    this.age += dt;
    if (lifetime > 0) {
        // recompute BEFORE update so curves sample this step's t (was one tick late), and clamp:
        // fractional dt can push age past lifetime here, which previously produced t > 1
        t = Math.min(age / lifetime, 1f);
    }

    // update data
    update(dt);

    if (runtime.subEmitters.isEnable()) {
        runtime.subEmitters.triggerTickEvent(this, dt);
    }
}

