public static void renderSpellCircle(float alive, float scale, float horizontalScale, float xDir, float yDir, float zDir, int color, PoseStack ms, MultiBufferSource buffers) {
	ms.pushPose();
	double ratio = 0.0625 * horizontalScale;

	Vec3 direction = new Vec3(xDir, yDir, zDir);
	Vec3 normal = new Vec3(0f, 0f, 1f);
	Vec3 axis = normal.cross(direction);
	double dot = normal.dot(direction);

	// Very small threshold to see if it's parallel or not.
	if(axis.length() < 1e-6) {
		// If it's parallel but the dot product is negative we flip it.
		if(dot < 0) {
			ms.mulPose(Axis.XP.rotationDegrees(180f));
		}
	} else {
		float angle = (float) Math.acos(dot);
		ms.mulPose(new Quaternionf().fromAxisAngleRad((float) axis.x, (float) axis.y, (float) axis.z, angle));
	}

	ms.translate(0, 0, 0.1);
	ms.scale((float) ratio * scale, (float) ratio * scale, (float) ratio);

	int r = PsiRenderHelper.r(color);
	int g = PsiRenderHelper.g(color);
	int b = PsiRenderHelper.b(color);

	for(int i = 0; i < LAYERS.length; i++) {
		int rValue = r;
		int gValue = g;
		int bValue = b;

		if(i == 1) {
			rValue = gValue = bValue = 0xFF;
		} else if(i == 2) {
			int minBrightness = (int) (1 / (1 - BRIGHTNESS_FACTOR));
			if(rValue == 0 && gValue == 0 && bValue == 0) {
				rValue = gValue = bValue = minBrightness;
			}
			if(rValue > 0 && rValue < minBrightness) {
				rValue = minBrightness;
			}
			if(gValue > 0 && gValue < minBrightness) {
				gValue = minBrightness;
			}
			if(bValue > 0 && bValue < minBrightness) {
				bValue = minBrightness;
			}

			rValue = (int) Math.min(rValue / BRIGHTNESS_FACTOR, 0xFF);
			gValue = (int) Math.min(gValue / BRIGHTNESS_FACTOR, 0xFF);
			bValue = (int) Math.min(bValue / BRIGHTNESS_FACTOR, 0xFF);
		}

		ms.pushPose();
		ms.mulPose(Axis.ZP.rotationDegrees(i == 0 ? -alive : alive));

		VertexConsumer buffer = buffers.getBuffer(LAYERS[i]);
		Matrix4f mat = ms.last().pose();
		int fullbright = 0xF000F0;
		addVertex(buffer, mat, -32, 32, rValue, gValue, bValue, 0, 1, fullbright);
		addVertex(buffer, mat, 32, 32, rValue, gValue, bValue, 1, 1, fullbright);
		addVertex(buffer, mat, 32, -32, rValue, gValue, bValue, 1, 0, fullbright);
		addVertex(buffer, mat, -32, -32, rValue, gValue, bValue, 0, 0, fullbright);
		ms.popPose();

		ms.translate(0, 0, -0.5);
	}

	ms.popPose();
}

protected SpellParticle(ClientWorld world, double x, double y, double z,
                        double velocityX, double velocityY, double velocityZ,
                        SpriteProvider spriteProvider,
                        SpellEngineParticles.Entry entry,
                        ParticleGroup.Appearance config,
                        @Nullable Entity sourceEntity) {
    super(world, x, y, z);
    this.spriteProvider = spriteProvider;
    this.frameCount = entry.texture().frames();
    this.pivot = entry.pivot();

    this.facing = config.facing != null ? config.facing : ParticleGroup.Facing.CAMERA;
    this.render = config.render != null ? config.render : ParticleGroup.Render.TRANSLUCENT;
    this.glow = config.glow != null ? config.glow : true;
    var motion = config.motion != null ? config.motion : ParticleGroup.Motion.STATIC;
    this.motion = motion;

    // MARK: Motion preset (constants ported from V1 SpellUniversalParticle)

    this.collidesWithWorld = config.collides;
    switch (motion) {
        case STATIC -> {
            this.velocityX = velocityX;
            this.velocityY = velocityY;
            this.velocityZ = velocityZ;
            this.velocityMultiplier = 1F;
            this.gravityStrength = 0F;
        }
        case FLOAT, DECELERATE -> {
            this.velocityMultiplier = motion == ParticleGroup.Motion.DECELERATE ? 0.768F : 0.96F;
            this.gravityStrength = 0F;
            this.velocityX = velocityX + (this.random.nextFloat() - this.random.nextFloat()) * 0.005F;
            this.velocityY = velocityY + (this.random.nextFloat() - this.random.nextFloat()) * 0.005F;
            this.velocityZ = velocityZ + (this.random.nextFloat() - this.random.nextFloat()) * 0.005F;
            this.x += (this.random.nextFloat() - this.random.nextFloat()) * 0.05F;
            this.y += (this.random.nextFloat() - this.random.nextFloat()) * 0.05F;
            this.z += (this.random.nextFloat() - this.random.nextFloat()) * 0.05F;
            this.setPos(this.x, this.y, this.z);
        }
        case ASCEND -> {
            this.velocityMultiplier = 0.96F;
            this.gravityStrength = -0.1F;
            this.ascending = true;
            this.velocityX = velocityX * (velocityX == 0 && velocityZ == 0 ? 0.1F : 1F)
                    + (this.random.nextFloat() - this.random.nextFloat()) * 0.005F;
            this.velocityY = velocityY * 0.2F + 0.02F;
            this.velocityZ = velocityZ * (velocityX == 0 && velocityZ == 0 ? 0.1F : 1F)
                    + (this.random.nextFloat() - this.random.nextFloat()) * 0.005F;
        }
        case BURST -> {
            this.velocityMultiplier = 0.7F;
            this.gravityStrength = 0.5F;
            this.velocityX = velocityX * 0.4F + (this.random.nextFloat() - this.random.nextFloat()) * 0.02F;
            this.velocityY = velocityY * 0.4F + (this.random.nextFloat() - this.random.nextFloat()) * 0.02F;
            this.velocityZ = velocityZ * 0.4F + (this.random.nextFloat() - this.random.nextFloat()) * 0.02F;
        }
        case DRIFT -> {
            // Vanilla SnowflakeParticle's motion: a wide random scatter, gravity,
            // and per-axis damping that bleeds vertical speed faster than lateral,
            // so particles fan out as they settle rather than dropping in a line.
            this.velocityMultiplier = 1F;
            this.gravityStrength = 0.225F;
            this.velocityX = velocityX + (Math.random() * 2.0 - 1.0) * 0.05F;
            this.velocityY = velocityY + (Math.random() * 2.0 - 1.0) * 0.05F;
            this.velocityZ = velocityZ + (Math.random() * 2.0 - 1.0) * 0.05F;
        }
    }
    if (config.gravity != null) {
        this.gravityStrength = config.gravity;
    }
    if (config.drag != null) {
        this.velocityMultiplier = config.drag;
    }

    // MARK: Lifetime & playback

    float playbackSpeed = config.playback_speed == 0F ? 1F : config.playback_speed;
    this.reversedPlayback = playbackSpeed < 0F;
    float lifetimeRoll = 1F + (this.random.nextFloat() * 2F - 1F) * MathHelper.clamp(config.lifetime_variance, 0F, 1F);
    this.maxAge = Math.max(1, Math.round(
            entry.lifetime() * motion.lifetime_factor * lifetimeRoll / Math.abs(playbackSpeed)));

    // MARK: Appearance

    float darken = 1F - this.random.nextFloat() * MathHelper.clamp(config.color_variance, 0F, 1F);
    float colorAlpha = 1F;
    if (config.color >= 0) {
        var color = Color.fromRGBA(config.color);
        this.setColor(color.red() * darken, color.green() * darken, color.blue() * darken);
        colorAlpha = color.alpha();
    } else {
        this.setColor(darken, darken, darken);
    }
    this.baseOpacity = config.opacity * colorAlpha;
    this.opacityCurve = config.opacity_curve;
    this.alpha = baseOpacity * (opacityCurve != null ? opacityCurve.sample(0F) : 1F);

    float scaleVariance = MathHelper.clamp(config.scale_variance, 0F, 1F);
    this.spawnScale = config.scale * (1F + (this.random.nextFloat() * 2F - 1F) * scaleVariance);
    this.scale = spawnScale;
    this.scaleEasing = config.scale_easing;
    this.scaleMultiplier = config.scale_multiplier;

    // MARK: Attachment

    this.attachment = config.attachment;
    this.followEntity = attachment != ParticleGroup.Attachment.NONE ? sourceEntity : null;
    if (followEntity != null) {
        this.followDiff = new Vec3d(this.x - followEntity.getX(), this.y - followEntity.getY(), this.z - followEntity.getZ());
    }
    // Seed the ground cache with the spawn height (a GROUND-anchored batch already
    // resolves to the floor), so the first frame is correct before any re-probe.
    this.groundY = this.y;

    updateSprite();
    updateSkipRender();
}

public static void renderChain(Vec3 to, PoseStack poseStack, VertexConsumer buffer, int packedLightIn, int overlayCoords) {
        double d = to.horizontalDistance();
        float rotY = (float) (Mth.atan2(to.x, to.z) * (double) (180F / (float) Math.PI));
        float rotX = (float) (-(Mth.atan2(to.y, d) * (double) (180F / (float) Math.PI))) - 90.0F;
        float chainWidth = 3F / 16F;
        float chainOffset = chainWidth * -0.5F;
        float chainLength = (float) to.length();
        poseStack.pushPose();
        poseStack.mulPose(Axis.YP.rotationDegrees(rotY));
        poseStack.mulPose(Axis.XP.rotationDegrees(rotX));
        poseStack.translate(0, -chainLength, 0);
        PoseStack.Pose posestack$pose = poseStack.last();
        Matrix4f matrix4f = posestack$pose.pose();
        Matrix3f matrix3f = posestack$pose.normal();
        //x links
        buffer.vertex(matrix4f, chainOffset, 0, 0).color(255, 255, 255, 255).uv((float) 0, (float) chainLength).overlayCoords(overlayCoords).uv2(packedLightIn).normal(matrix3f, 0.0F, -1.0F, 0.0F).endVertex();
        buffer.vertex(matrix4f, chainWidth + chainOffset, 0, 0).color(255, 255, 255, 255).uv((float) chainWidth, (float) chainLength).overlayCoords(overlayCoords).uv2(packedLightIn).normal(matrix3f, 0.0F, -1.0F, 0.0F).endVertex();
        buffer.vertex(matrix4f, chainWidth + chainOffset, chainLength, 0).color(255, 255, 255, 255).uv((float) chainWidth, (float) 0).overlayCoords(overlayCoords).uv2(packedLightIn).normal(matrix3f, 0.0F, -1.0F, 0.0F).endVertex();
        buffer.vertex(matrix4f, chainOffset, chainLength, 0).color(255, 255, 255, 255).uv((float) 0, (float) 0).overlayCoords(overlayCoords).uv2(packedLightIn).normal(matrix3f, 0.0F, -1.0F, 0.0F).endVertex();
        float pixelSkip = 2.5F / 16F;
        //z links
        buffer.vertex(matrix4f, 0, pixelSkip, chainOffset).color(255, 255, 255, 255).uv((float) chainWidth, (float) chainLength + pixelSkip).overlayCoords(overlayCoords).uv2(packedLightIn).normal(matrix3f, 0.0F, -1.0F, 0.0F).endVertex();
        buffer.vertex(matrix4f, 0, pixelSkip, chainWidth + chainOffset).color(255, 255, 255, 255).uv((float) chainWidth * 2, (float) chainLength + pixelSkip).overlayCoords(overlayCoords).uv2(packedLightIn).normal(matrix3f, 0.0F, -1.0F, 0.0F).endVertex();
        buffer.vertex(matrix4f, 0, chainLength + pixelSkip, chainWidth + chainOffset).color(255, 255, 255, 255).uv((float) chainWidth * 2, (float) pixelSkip).overlayCoords(overlayCoords).uv2(packedLightIn).normal(matrix3f, 0.0F, -1.0F, 0.0F).endVertex();
        buffer.vertex(matrix4f, 0, chainLength + pixelSkip, chainOffset).color(255, 255, 255, 255).uv((float) chainWidth, (float) pixelSkip).overlayCoords(overlayCoords).uv2(packedLightIn).normal(matrix3f, 0.0F, -1.0F, 0.0F).endVertex();
        poseStack.popPose();
    }

private static void addLicoriceStringVertexPair(VertexConsumer vertexConsumer, Matrix4f matrix4f, float x, float y, float z, int blockLightFrom, int blockLightTo, int skyLightFrom, int skyLightTo, float height, float yWidth, float xWidth, float zWidth, int vertIndex) {
        float f = (float) vertIndex / 32.0F;
        int i = (int) Mth.lerp(f, (float) blockLightFrom, (float) blockLightTo);
        int j = (int) Mth.lerp(f, (float) skyLightFrom, (float) skyLightTo);
        int k = LightTexture.pack(i, j);
        boolean colorScheme = vertIndex % 2 == 0;
        float f2 = colorScheme ? LICORICE_COLOR_1_R : LICORICE_COLOR_2_R;
        float f3 = colorScheme ? LICORICE_COLOR_1_G : LICORICE_COLOR_2_G;
        float f4 = colorScheme ? LICORICE_COLOR_1_B : LICORICE_COLOR_2_B;
        float f5 = x * f;
        float f6 = y < 0.0F ? y * f * f : y - y * (1.0F - f) * (1.0F - f);
        float f7 = z * f;
        vertexConsumer.vertex(matrix4f, f5 - xWidth, f6 + yWidth, f7 + zWidth).color(f2, f3, f4, 1.0F).uv2(k).endVertex();
        vertexConsumer.vertex(matrix4f, f5 + xWidth, f6 + height - yWidth, f7 - zWidth).color(f2, f3, f4, 1.0F).uv2(k).endVertex();
    }

public static void renderEntireBatch(LevelRenderer levelRenderer, PoseStack poseStack, int renderTick, Camera camera, float partialTick) {
        if (!allDugBlocksOnScreen.isEmpty()) {
            poseStack.pushPose();
            Vec3 cameraPos = camera.getPosition();
            poseStack.translate(-cameraPos.x, -cameraPos.y, -cameraPos.z);
            MultiBufferSource.BufferSource multibuffersource$buffersource = Minecraft.getInstance().renderBuffers().crumblingBufferSource();
            for (Map.Entry<BlockPos, Integer> posAndInt : allDugBlocksOnScreen.entrySet()) {
                int progress = posAndInt.getValue() - 1;
                if (progress >= 0 && progress < 10) {
                    poseStack.pushPose();
                    BlockPos pos = posAndInt.getKey();
                    poseStack.translate((double) pos.getX(), (double) pos.getY(), (double) pos.getZ());
                    PoseStack.Pose posestack$pose1 = poseStack.last();
                    VertexConsumer vertexconsumer1 = new SheetedDecalTextureGenerator(multibuffersource$buffersource.getBuffer(ModelBakery.DESTROY_TYPES.get(progress)), posestack$pose1.pose(), posestack$pose1.normal(), 1.0F);
                    net.minecraftforge.client.model.data.ModelData modelData = Minecraft.getInstance().level.getModelDataManager().getAt(pos);
                    Minecraft.getInstance().getBlockRenderer().renderBreakingTexture(Minecraft.getInstance().level.getBlockState(pos), pos, Minecraft.getInstance().level, poseStack, vertexconsumer1, modelData == null ? net.minecraftforge.client.model.data.ModelData.EMPTY : modelData);
                    poseStack.popPose();
                }
            }
            poseStack.popPose();
        }
        allDugBlocksOnScreen.clear();

    }

public void render(DarkArrowEntity entity, float entityYaw, float partialTicks, PoseStack poseStack, MultiBufferSource bufferSource, int lighting) {
        poseStack.pushPose();
        poseStack.mulPose(Axis.YP.rotationDegrees(Mth.lerp(partialTicks, entity.yRotO, entity.getYRot())));
        poseStack.mulPose(Axis.XN.rotationDegrees(Mth.lerp(partialTicks, entity.xRotO, entity.getXRot())));
        poseStack.translate(0.0D, (double) 1.5F, -0.15D);
        poseStack.mulPose(Axis.XP.rotationDegrees(180));
        float f9 = (float) entity.shakeTime - partialTicks;
        if (f9 > 0.0F) {
            float f10 = -Mth.sin(f9 * 3.0F) * f9;
            poseStack.mulPose(Axis.ZP.rotationDegrees(f10));
        }
        float ageInTicks = entity.tickCount + partialTicks;
        float invFade = 1.0F - entity.getFadeOut(ageInTicks - entity.tickCount);
        float alpha = Math.min(ageInTicks / 4F, 1F) * invFade;
        RenderType renderType = ForgeRenderTypes.getUnlitTranslucent(this.getTextureLocation(entity));
        VertexConsumer vertexconsumer = bufferSource.getBuffer(renderType);
        MODEL.setupAnim(entity, 0.0F, 0.0F, ageInTicks, 0.0F, 0.0F);
        MODEL.renderToBuffer(poseStack, vertexconsumer, 240, OverlayTexture.NO_OVERLAY, entity.getArrowRed(partialTicks), 0.0F, 0.0F, alpha);
        poseStack.popPose();
        super.render(entity, entityYaw, partialTicks, poseStack, bufferSource, lighting);
    }

public void render(DesolateDaggerEntity entity, float entityYaw, float partialTicks, PoseStack poseStack, MultiBufferSource source, int lightIn) {
        super.render(entity, entityYaw, partialTicks, poseStack, source, lightIn);
        float ageInTicks = partialTicks + entity.tickCount;
        double stab = Math.max(entity.getStab(partialTicks), Math.sin(ageInTicks * 0.1F) * 0.2F);
        poseStack.pushPose();
        poseStack.translate(0.0D, 0.5D, 0.0D);
        poseStack.mulPose(Axis.YN.rotationDegrees(Mth.lerp(partialTicks, entity.yRotO, entity.getYRot()) + 90.0F));
        poseStack.mulPose(Axis.ZN.rotationDegrees((float) (Mth.lerp(partialTicks, entity.xRotO, entity.getXRot()) + 5F * Math.sin(ageInTicks * 0.2F))));
        poseStack.mulPose(Axis.ZN.rotationDegrees(45));
        poseStack.translate(-0.5D, -0.5D, -0.5D);
        float f = 1.0F;
        float f1 = 0;
        float f2 = 0;
        float startAlpha = ageInTicks < 3 ? 0 : (ageInTicks - 3) / 6F;
        float alpha = (float) Math.min(0.6F + stab, Math.min(1F, startAlpha));
        int redOverlay = OverlayTexture.pack(OverlayTexture.u(0), OverlayTexture.v(true));
        poseStack.translate(stab, stab + Math.cos(ageInTicks * 0.1F) * 0.2F, 0);
        BakedModel bakedmodel = Minecraft.getInstance().getItemRenderer().getModel(entity.daggerRenderStack, entity.level(), null, 0);
        for (net.minecraft.client.renderer.RenderType rt : bakedmodel.getRenderTypes(entity.daggerRenderStack, false)) {
            renderModel(poseStack.last(), source.getBuffer(Sheets.translucentItemSheet()), alpha, null, bakedmodel, f, f1, f2, 240, redOverlay, ModelData.EMPTY, rt);
        }
        poseStack.popPose();
    }

public void render(DinosaurSpiritEntity entityIn, float entityYaw, float partialTicks, PoseStack poseStack, MultiBufferSource bufferIn, int packedLightIn) {
        poseStack.pushPose();
        poseStack.translate(0.0D, 1.5D, 0.0D);
        if(entityIn.getDinosaurType() == DinosaurSpiritEntity.DinosaurType.GROTTOCERATOPS){
            Player player = entityIn.getUsingPlayer();
            if(player != null){
                Vec3 playerPos = player.getPosition(partialTicks);
                Vec3 dinoPos = entityIn.getPosition(partialTicks);
                double d1 = playerPos.z - dinoPos.z;
                double d2 = playerPos.x - dinoPos.x;
                float f = (-((float) Mth.atan2(d2, d1)) * (180F / (float) Math.PI));
                poseStack.mulPose(Axis.YP.rotationDegrees(-f));
            }
        }else{
            poseStack.mulPose(Axis.YP.rotationDegrees(180 - entityIn.getViewYRot(partialTicks)));
        }
        poseStack.scale(-1.0F, -1.0F, 1.0F);
        poseStack.mulPose(Axis.XN.rotationDegrees(entityIn.getViewXRot(partialTicks)));
        VertexConsumer ivertexbuilder;
        float ghostAlpha = entityIn.getFadeIn(partialTicks);
        boolean prevBaby;
        switch (entityIn.getDinosaurType()){
            case SUBTERRANODON:
                prevBaby = SUBTERRANODON_MODEL.young;
                SUBTERRANODON_MODEL.young = false;
                ivertexbuilder = bufferIn.getBuffer(ACRenderTypes.getRedGhost(SUBTERRANODON_TEXTURE));
                SUBTERRANODON_MODEL.animateSpirit(entityIn, partialTicks);
                SUBTERRANODON_MODEL.renderToBuffer(poseStack, ivertexbuilder, 240, OverlayTexture.NO_OVERLAY, 1.0F, 1.0F, 1.0F, ghostAlpha);
                SUBTERRANODON_MODEL.young = prevBaby;
                break;
            case GROTTOCERATOPS:
                prevBaby = GROTTOCERATOPS_MODEL.young;
                GROTTOCERATOPS_MODEL.young = false;
                ivertexbuilder = bufferIn.getBuffer(ACRenderTypes.getRedGhost(GROTTOCERATOPS_TEXTURE));
                GROTTOCERATOPS_MODEL.animateSpirit(entityIn, partialTicks);
                GROTTOCERATOPS_MODEL.renderSpiritToBuffer(poseStack, ivertexbuilder, 240, OverlayTexture.NO_OVERLAY, 1.0F, 1.0F, 1.0F, ghostAlpha);
                GROTTOCERATOPS_MODEL.young = prevBaby;
                break;
            case TREMORSAURUS:
                prevBaby = TREMORSAURUS_MODEL.young;
                TREMORSAURUS_MODEL.young = false;
                ivertexbuilder = bufferIn.getBuffer(ACRenderTypes.getRedGhost(TREMORSAURUS_TEXTURE));
                TREMORSAURUS_MODEL.animateSpirit(entityIn, partialTicks);
                TREMORSAURUS_MODEL.renderSpiritToBuffer(poseStack, ivertexbuilder, 240, OverlayTexture.NO_OVERLAY, 1.0F, 1.0F, 1.0F, ghostAlpha);
                TREMORSAURUS_MODEL.young = prevBaby;
                break;
        }
        poseStack.popPose();
        super.render(entityIn, entityYaw, partialTicks, poseStack, bufferIn, packedLightIn);
    }

public void render(MagneticWeaponEntity entity, float entityYaw, float partialTicks, PoseStack poseStack, MultiBufferSource source, int i) {
        ItemStack itemStack = entity.getItemStack();
        ItemRenderer renderer = Minecraft.getInstance().getItemRenderer();
        BakedModel bakedModel = renderer.getModel(itemStack, entity.level(), null, 0);
        float ageInTicks = entity.tickCount + partialTicks;
        float strikeProgress = entity.getStrikeProgress(partialTicks);
        poseStack.pushPose();
        poseStack.translate(0, 0.1F + Math.sin(ageInTicks * 0.1F) * 0.1F, 0);
        Entity controller = entity.getController();
        if (controller instanceof Player player) {
            double x = Mth.lerp(partialTicks, entity.xOld, entity.getX());
            double y = Mth.lerp(partialTicks, entity.yOld, entity.getY());
            double z = Mth.lerp(partialTicks, entity.zOld, entity.getZ());
            Vec3 fromVec;
            if (controller == Minecraft.getInstance().player && Minecraft.getInstance().options.getCameraType().isFirstPerson()) {
                int leftAmount = 1;
                ItemStack itemstack = player.getMainHandItem();
                if (!itemstack.is(ACItemRegistry.GALENA_GAUNTLET.get())) {
                    leftAmount = -leftAmount;
                }
                double d7 = 1000.0D / (double) this.entityRenderDispatcher.options.fov().get().intValue();
                float f = player.getAttackAnim(partialTicks);
                float f1 = Mth.sin(Mth.sqrt(f) * (float) Math.PI);
                Vec3 vec3 = this.entityRenderDispatcher.camera.getNearPlane().getPointOnPlane((float) leftAmount * 0.525F, -0.7F);
                vec3 = vec3.scale(d7);
                vec3 = vec3.yRot(f1 * 0.5F);
                vec3 = vec3.xRot(-f1 * 0.7F);
                float d4 = (float) (Mth.lerp((double) partialTicks, player.xo, player.getX()) + vec3.x);
                float d5 = (float) (Mth.lerp((double) partialTicks, player.yo, player.getY()) + vec3.y);
                float d6 = (float) (Mth.lerp((double) partialTicks, player.zo, player.getZ()) + vec3.z);
                float f3 = player.getEyeHeight();
                Vec3 behind = controller.getViewVector(partialTicks).normalize().scale(-0.2F);
                fromVec = new Vec3(d4, d5 + f3, d6).add(behind);
            } else {
                fromVec = entity.getControllerHandPos(player, partialTicks);
            }
            Vec3 toVec = entity.position().add(0, 0.24F, 0);
            poseStack.pushPose();
            poseStack.translate(-x, -y, -z);
            int segCount = Mth.clamp((int) entity.distanceTo(player) + 2, 3, 30);
            float spreadFactor = Mth.clamp((10 - entity.distanceTo(player)) / 10F * 0.2F, 0.01F, 0.2F);
            float returnProgress = entity.getReturnProgress(partialTicks);
            LightningBoltData.BoltRenderInfo boltData = new LightningBoltData.BoltRenderInfo(0.0F, spreadFactor, 0.0F, 0.0F, new Vector4f(0.1F + returnProgress * 0.9F, 0.1F, 0.9F - returnProgress * 0.8F, 0.8F), 0.1F);
            LightningBoltData bolt1 = new LightningBoltData(boltData, fromVec, toVec, segCount)
                    .size(0.1F)
                    .lifespan(1)
                    .spawn(LightningBoltData.SpawnFunction.CONSECUTIVE)
                    .fade(LightningBoltData.FadeFunction.NONE);
            LightningRender lightningRender = getLightingRender(entity.getUUID());
            lightningRender.update(entity, bolt1, partialTicks);

            lightningRender.render(partialTicks, poseStack, source);

            poseStack.popPose();
        }
        poseStack.mulPose(Axis.YN.rotationDegrees(Mth.lerp(partialTicks, entity.yRotO, entity.getYRot()) - 180.0F));
        poseStack.mulPose(Axis.XN.rotationDegrees(Mth.lerp(partialTicks, entity.xRotO, entity.getXRot())));
        poseStack.translate(0, strikeProgress * 0.1F, strikeProgress * 0.2F);
        poseStack.mulPose(Axis.XN.rotationDegrees(strikeProgress * 90F));
        Minecraft.getInstance().getItemRenderer().render(itemStack, ItemDisplayContext.THIRD_PERSON_RIGHT_HAND, false, poseStack, source, i, OverlayTexture.NO_OVERLAY, bakedModel);
        poseStack.popPose();

        super.render(entity, entityYaw, partialTicks, poseStack, source, i);
        if (entity.isRemoved() && lightningRenderMap.containsKey(entity.getUUID())) {
            lightningRenderMap.remove(entity.getUUID());
        }
    }

public static <E extends Entity> void renderEntityInHologram(E entityIn, double x, double y, double z, float yaw, float partialTicks, PoseStack matrixStack, MultiBufferSource bufferIn, int packedLight) {
        PostEffectRegistry.renderEffectForNextTick(ClientProxy.HOLOGRAM_SHADER);

        EntityRenderer<? super E> render = null;
        EntityRenderDispatcher manager = Minecraft.getInstance().getEntityRenderDispatcher();
        try {
            render = manager.getRenderer(entityIn);
            float animSpeed = 0;
            float animSpeedOld = 0;
            float animPos = 0;
            float xRot = entityIn.getXRot();
            float xRotOld = entityIn.xRotO;
            float yRot = entityIn.getYRot();
            float yRotOld = entityIn.yRotO;
            float yBodyRot = 0;
            float yBodyRotOld = 0;
            float headRot = 0;
            float headRotOld = 0;
            if (entityIn instanceof LivingEntity living) {
                headRot = living.yHeadRot;
                headRotOld = living.yHeadRotO;
                yBodyRot = living.yBodyRot;
                yBodyRotOld = living.yBodyRotO;
                living.yHeadRot = 0;
                living.yHeadRotO = 0;
                living.yBodyRot = 0;
                living.yBodyRotO = 0;
                entityIn.setXRot(0);
                entityIn.xRotO = 0;
                entityIn.setYRot(0);
                entityIn.yRotO = 0;
                if (render instanceof LivingEntityRenderer renderer && renderer.getModel() != null) {
                    EntityModel model = renderer.getModel();
                    ResourceLocation texture = render.getTextureLocation(entityIn);
                    if(entityIn instanceof DeepOneMageEntity){
                        texture = DeepOneMageRenderer.TEXTURE;
                    }else if(entityIn instanceof GummyBearEntity gummyBearEntity && renderer instanceof GummyBearRenderer gummyBearRenderer){
                        texture = gummyBearRenderer.getOutsideTextureLocation(gummyBearEntity);
                        model = GummyBearRenderer.OUTSIDE_MODEL;
                    }
                    VertexConsumer ivertexbuilder = bufferIn.getBuffer(ACRenderTypes.getHologram(texture));
                    matrixStack.pushPose();
                    boolean shouldSit = entityIn.isPassenger() && (entityIn.getVehicle() != null && entityIn.getVehicle().shouldRiderSit());
                    model.young = living.isBaby();
                    model.riding = shouldSit;
                    model.attackTime = living.getAttackAnim(partialTicks);
                    boolean prevCrouching = false;
                    if (model instanceof HumanoidModel<?> humanoidModel) {
                        prevCrouching = humanoidModel.crouching;
                        humanoidModel.crouching = false;
                    }
                    if(model instanceof UnderzealotModel underzealotModel){
                        underzealotModel.noBurrowing = true;
                    }
                    if(model instanceof HullbreakerModel hullbreakerModel){
                        hullbreakerModel.straighten = true;
                    }
                    if(model instanceof SauropodBaseModel sauropodBaseModel){
                        sauropodBaseModel.straighten = true;
                    }
                    if(model instanceof TremorzillaModel tremorzillaModel){
                        tremorzillaModel.straighten = true;
                    }
                    model.setupAnim(living, 0.0F, 0.0F, -0.1F, 0.0F, 0.0F);

                    if(model instanceof UnderzealotModel underzealotModel){
                        underzealotModel.noBurrowing = false;
                    }
                    if(model instanceof HullbreakerModel hullbreakerModel){
                        hullbreakerModel.straighten = false;
                    }
                    if(model instanceof SauropodBaseModel sauropodBaseModel){
                        sauropodBaseModel.straighten = false;
                    }
                    if(model instanceof TremorzillaModel tremorzillaModel){
                        tremorzillaModel.straighten = false;
                    }
                    if(model instanceof GummyBearModel gummyBearModel){
                        gummyBearModel.ignoreColor = true;
                    }
                    matrixStack.scale(-living.getScale(), -living.getScale(), living.getScale());
                    ((LivingEntityRendererAccessor)renderer).scaleForHologram(living, matrixStack, partialTicks);
                    if(entityIn instanceof CaramelCubeEntity caramelCubeEntity){
                        float scaleBy = caramelCubeEntity.getSlimeSize() == 2 ? 4 : caramelCubeEntity.getSlimeSize() == 1 ? 2 : 1;
                        matrixStack.translate(0, -scaleBy * 0.25F, 0);
                    }
                    model.renderToBuffer(matrixStack, ivertexbuilder, 240, OverlayTexture.NO_OVERLAY, 1.0F, 1.0F, 1.0F, 1.0F);
                    matrixStack.popPose();
                    if (model instanceof HumanoidModel<?> humanoidModel) {
                        humanoidModel.crouching = prevCrouching;
                    }
                    if(model instanceof GummyBearModel gummyBearModel){
                        gummyBearModel.ignoreColor = false;
                    }
                }else if(render instanceof FerrouslimeRenderer && living instanceof FerrouslimeEntity ferrouslime){
                    matrixStack.pushPose();
                    matrixStack.translate(0, -1, 0);
                    matrixStack.scale(-living.getScale(), -living.getScale(), living.getScale());
                    VertexConsumer ivertexbuilder = bufferIn.getBuffer(ACRenderTypes.getHologram(render.getTextureLocation(entityIn)));
                    FerrouslimeRenderer.FERROUSLIME_MODEL.setupAnim(ferrouslime, 0.0F, 0.0F, -0.1F, 0.0F, 0.0F);
                    FerrouslimeRenderer.FERROUSLIME_MODEL.renderToBuffer(matrixStack, ivertexbuilder, 240, OverlayTexture.NO_OVERLAY, 1.0F, 1.0F, 1.0F, 1.0F);
                    matrixStack.popPose();
                }
                entityIn.setXRot(xRot);
                entityIn.xRotO = xRotOld;
                entityIn.setYRot(yRot);
                entityIn.yRotO = yRotOld;
                living.yHeadRot = headRot;
                living.yHeadRotO = headRotOld;
                living.yBodyRot = yBodyRot;
                living.yBodyRotO = yBodyRotOld;
            }
            Minecraft.getInstance().getMainRenderTarget().bindWrite(false);
        } catch (Throwable throwable3) {
            CrashReport crashreport = CrashReport.forThrowable(throwable3, "Rendering entity in world");
            CrashReportCategory crashreportcategory = crashreport.addCategory("Entity being rendered");
            entityIn.fillCrashReportCategory(crashreportcategory);
            CrashReportCategory crashreportcategory1 = crashreport.addCategory("Renderer details");
            crashreportcategory1.setDetail("Assigned renderer", render);
            crashreportcategory1.setDetail("Rotation", Float.valueOf(yaw));
            crashreportcategory1.setDetail("Delta", Float.valueOf(partialTicks));
            throw new ReportedException(crashreport);
        }
    }

public void render(SugarStaffHexEntity entity, float entityYaw, float partialTicks, PoseStack poseStack, MultiBufferSource multiBufferSource, int packedLight) {
        PostEffectRegistry.renderEffectForNextTick(ClientProxy.PURPLE_WITCH_SHADER);
        poseStack.pushPose();
        float despawnsIn = entity.getDespawnTime(partialTicks);
        float randomRotation = entity.getId() % 4 * 90;
        float randomYOffset = entity.getYRenderOffset();
        float tickCount = entity.tickCount + partialTicks;
        float minAge = Math.min(1F, Math.min(tickCount, despawnsIn) / 10F);
        float alpha = minAge;
        float alpha2 = alpha * alpha;
        float scale = 4.0F * entity.getHexScale();
        poseStack.translate(0, randomYOffset, 0);
        poseStack.mulPose(Axis.YP.rotationDegrees(randomRotation + 3.0F * tickCount));
        poseStack.scale(scale, scale, scale);
        renderHex(poseStack, multiBufferSource, ACRenderTypes.getPurpleWitch(TEXTURE), 1F, 1F, 1F - alpha2, 1F);
        for(int i = 0; i < 5; i++){
            float f = (1F - i / 5F) * 0.5F;
            float bob = (float) (Math.sin(tickCount * 0.2F + i) * 0.005F);
            renderHex(poseStack, multiBufferSource, ACRenderTypes.getVoidBeingCloud(TEXTURE), 1 * f, 1F, 1F - alpha2 * f, 1F);
            poseStack.translate(0, 0.01F + bob + (1F - alpha2) * 0.03F, 0);
        }
        poseStack.popPose();
        super.render(entity, entityYaw, partialTicks, poseStack, multiBufferSource, packedLight);
    }

private void renderTrail(TeletorEntity entityIn, int side, float partialTicks, PoseStack poseStack, MultiBufferSource bufferIn, float trailR, float trailG, float trailB, float trailA, int packedLightIn) {
        int samples = 0;
        int sampleSize = 10;
        float trailHeight = 0.2F;
        float trailZRot = 0;
        Vec3 topAngleVec = new Vec3(0, trailHeight, 0).zRot(trailZRot);
        Vec3 bottomAngleVec = new Vec3(0, -trailHeight, 0).zRot(trailZRot);
        Vec3 drawFrom = entityIn.getTrailPosition(0, side, partialTicks);
        VertexConsumer vertexconsumer = bufferIn.getBuffer(RenderType.entityTranslucent(TRAIL_TEXTURE));
        while (samples < sampleSize) {
            Vec3 sample = entityIn.getTrailPosition(samples + 2, side, partialTicks);
            float u1 = samples / (float) sampleSize;
            float u2 = u1 + 1 / (float) sampleSize;

            Vec3 draw1 = drawFrom;
            Vec3 draw2 = sample;

            PoseStack.Pose posestack$pose = poseStack.last();
            Matrix4f matrix4f = posestack$pose.pose();
            Matrix3f matrix3f = posestack$pose.normal();
            vertexconsumer.vertex(matrix4f, (float) draw1.x + (float) bottomAngleVec.x, (float) draw1.y + (float) bottomAngleVec.y, (float) draw1.z + (float) bottomAngleVec.z).color(trailR, trailG, trailB, trailA).uv(u1, 1F).overlayCoords(NO_OVERLAY).uv2(packedLightIn).normal(matrix3f, 0.0F, 1.0F, 0.0F).endVertex();
            vertexconsumer.vertex(matrix4f, (float) draw2.x + (float) bottomAngleVec.x, (float) draw2.y + (float) bottomAngleVec.y, (float) draw2.z + (float) bottomAngleVec.z).color(trailR, trailG, trailB, trailA).uv(u2, 1F).overlayCoords(NO_OVERLAY).uv2(packedLightIn).normal(matrix3f, 0.0F, 1.0F, 0.0F).endVertex();
            vertexconsumer.vertex(matrix4f, (float) draw2.x + (float) topAngleVec.x, (float) draw2.y + (float) topAngleVec.y, (float) draw2.z + (float) topAngleVec.z).color(trailR, trailG, trailB, trailA).uv(u2, 0).overlayCoords(NO_OVERLAY).uv2(packedLightIn).normal(matrix3f, 0.0F, 1.0F, 0.0F).endVertex();
            vertexconsumer.vertex(matrix4f, (float) draw1.x + (float) topAngleVec.x, (float) draw1.y + (float) topAngleVec.y, (float) draw1.z + (float) topAngleVec.z).color(trailR, trailG, trailB, trailA).uv(u1, 0).overlayCoords(NO_OVERLAY).uv2(packedLightIn).normal(matrix3f, 0.0F, 1.0F, 0.0F).endVertex();
            samples++;
            drawFrom = sample;
        }
    }

private void renderBeam(TremorzillaEntity entity, PoseStack poseStack, MultiBufferSource source, float partialTicks, float width, float length, boolean inner, boolean glowSecondPass) {
        poseStack.pushPose();
        int vertices;
        VertexConsumer vertexconsumer;
        float speed;
        float startAlpha = 1.0F;
        float endAlpha = 1.0F;
        if (inner) {
            vertices = 4;
            ResourceLocation resourceLocation = entity.getAltSkin() == 2 ? TEXTURE_TECTONIC_BEAM_INNER : entity.getAltSkin() == 1 ? TEXTURE_RETRO_BEAM_INNER : TEXTURE_BEAM_INNER;
            if (AlexsCaves.CLIENT_CONFIG.radiationGlowEffect.get() && glowSecondPass) {
                PostEffectRegistry.renderEffectForNextTick(ClientProxy.IRRADIATED_SHADER);
                vertexconsumer = source.getBuffer(ACRenderTypes.getTremorzillaBeam(resourceLocation, true));
                endAlpha = 0.5F;
            } else {
                vertexconsumer = source.getBuffer(ACRenderTypes.getTremorzillaBeam(resourceLocation, false));
            }
            speed = 0.5F;
        } else {
            vertices = 8;
            ResourceLocation resourceLocation = entity.getAltSkin() == 2 ? TEXTURE_TECTONIC_BEAM_OUTER : entity.getAltSkin() == 1 ? TEXTURE_RETRO_BEAM_OUTER : TEXTURE_BEAM_OUTER;
            if (AlexsCaves.CLIENT_CONFIG.radiationGlowEffect.get()) {
                PostEffectRegistry.renderEffectForNextTick(ClientProxy.IRRADIATED_SHADER);
                vertexconsumer = source.getBuffer(ACRenderTypes.getTremorzillaBeam(resourceLocation, true));
            } else {
                vertexconsumer = source.getBuffer(ACRenderTypes.getTremorzillaBeam(resourceLocation, false));
            }
            width += 0.25F;
            speed = 1F;
            endAlpha = 0.0F;
        }

        float v = ((float) entity.tickCount + partialTicks) * -0.25F * speed;
        float v1 = v + length * (inner ? 0.5F : 0.15F);
        float f4 = -width;
        float f5 = 0;
        float f6 = 0.0F;
        PoseStack.Pose posestack$pose = poseStack.last();
        Matrix4f matrix4f = posestack$pose.pose();
        for (int j = 0; j <= vertices; ++j) {
            Matrix3f matrix3f = posestack$pose.normal();
            float f7 = Mth.cos((float) Math.PI + (float) j * ((float) Math.PI * 2F) / (float) vertices) * width;
            float f8 = Mth.sin((float) Math.PI + (float) j * ((float) Math.PI * 2F) / (float) vertices) * width;
            float f9 = (float) j + 1;
            vertexconsumer.vertex(matrix4f, f4 * 0.55F, f5 * 0.55F, 0.0F).color(1.0F, 1.0F, 1.0F, startAlpha).uv(f6, v).overlayCoords(OverlayTexture.NO_OVERLAY).uv2(240).normal(matrix3f, 0.0F, -1.0F, 0.0F).endVertex();
            vertexconsumer.vertex(matrix4f, f4, f5, length).color(1.0F, 1.0F, 1.0F, endAlpha).uv(f6, v1).overlayCoords(OverlayTexture.NO_OVERLAY).uv2(240).normal(matrix3f, 0.0F, -1F, 0.0F).endVertex();
            vertexconsumer.vertex(matrix4f, f7, f8, length).color(1.0F, 1.0F, 1.0F, endAlpha).uv(f9, v1).overlayCoords(OverlayTexture.NO_OVERLAY).uv2(240).normal(matrix3f, 0.0F, -1F, 0.0F).endVertex();
            vertexconsumer.vertex(matrix4f, f7 * 0.55F, f8 * 0.55F, 0.0F).color(1.0F, 1.0F, 1.0F, startAlpha).uv(f9, v).overlayCoords(OverlayTexture.NO_OVERLAY).uv2(240).normal(matrix3f, 0.0F, -1.0F, 0.0F).endVertex();
            f4 = f7;
            f5 = f8;
            f6 = f9;
        }
        if(inner){
            VertexConsumer endVertexConsumer;
            if (AlexsCaves.CLIENT_CONFIG.radiationGlowEffect.get() && glowSecondPass) {
                PostEffectRegistry.renderEffectForNextTick(ClientProxy.IRRADIATED_SHADER);
                endVertexConsumer = source.getBuffer(ACRenderTypes.getTremorzillaBeam(getEndBeamTexture(entity), true));
            } else {
                endVertexConsumer = source.getBuffer(ACRenderTypes.getTremorzillaBeam(getEndBeamTexture(entity), false));
            }
            poseStack.pushPose();
            poseStack.translate(0, 0, length - 1.5F);
            poseStack.mulPose(Axis.ZP.rotationDegrees(45));
            poseStack.mulPose(Axis.XP.rotationDegrees(90));
            poseStack.scale(width, width, width);
            BEAM_END_MODEL.resetToDefaultPose();
            BEAM_END_MODEL.renderToBuffer(poseStack, endVertexConsumer, 240, OverlayTexture.NO_OVERLAY, 1.0F, 1.0F, 1.0F, 1.0F);
            poseStack.popPose();
        }
        poseStack.popPose();
    }

public void render(WaterBoltEntity entityIn, float entityYaw, float partialTicks, PoseStack poseStack, MultiBufferSource bufferIn, int packedLightIn) {
        int waterColorAt = entityIn.level().getBiome(entityIn.blockPosition()).get().getWaterColor();
        float colorR = (waterColorAt >> 16 & 255) / 255F;
        float colorG = (waterColorAt >> 8 & 255) / 255F;
        float colorB = (waterColorAt & 255) / 255F;

        poseStack.pushPose();
        poseStack.translate(0.0D, (double) 0.25F, 0.0D);
        poseStack.mulPose(Axis.YP.rotationDegrees(Mth.lerp(partialTicks, entityIn.yRotO, entityIn.getYRot()) - 180.0F));
        poseStack.mulPose(Axis.XP.rotationDegrees(Mth.lerp(partialTicks, entityIn.xRotO, entityIn.getXRot())));
        MODEL.setupAnim(entityIn, 0.0F, 0.0F, entityIn.tickCount + partialTicks, 0.0F, 0.0F);
        VertexConsumer ivertexbuilder = bufferIn.getBuffer(ACRenderTypes.getBubbledNoCull(TEXTURE));
        MODEL.renderToBuffer(poseStack, ivertexbuilder, packedLightIn, OverlayTexture.NO_OVERLAY, colorR, colorG, colorB, 1.0F);
        VertexConsumer ivertexbuilder2 = bufferIn.getBuffer(ACRenderTypes.getBubbledNoCull(OVERLAY_TEXTURE));
        MODEL.renderToBuffer(poseStack, ivertexbuilder2, packedLightIn, OverlayTexture.NO_OVERLAY, 1.0F, 1.0F, 1.0F, 1.0F);
        poseStack.popPose();
        if (entityIn.hasTrail()) {
            double x = Mth.lerp(partialTicks, entityIn.xOld, entityIn.getX());
            double y = Mth.lerp(partialTicks, entityIn.yOld, entityIn.getY());
            double z = Mth.lerp(partialTicks, entityIn.zOld, entityIn.getZ());
            poseStack.pushPose();
            poseStack.translate(-x, -y, -z);
            renderTrail(entityIn, partialTicks, poseStack, bufferIn, colorR, colorG, colorB, 0.6F, packedLightIn);
            poseStack.popPose();
        }
        super.render(entityIn, entityYaw, partialTicks, poseStack, bufferIn, packedLightIn);
    }

public void render(WaveEntity entityIn, float entityYaw, float partialTicks, PoseStack matrixStackIn, MultiBufferSource bufferIn, int packedLightIn) {
        if(entityIn.isInvisible()){
            return;
        }
        matrixStackIn.pushPose();
        matrixStackIn.translate(0.0D, (double) 1.5F, 0.0D);
        matrixStackIn.mulPose(Axis.YN.rotationDegrees(Mth.lerp(partialTicks, entityIn.yRotO, entityIn.getYRot()) + 180.0F));
        float ageInTicks = entityIn.activeWaveTicks + partialTicks;
        float f = ageInTicks / 10F;
        matrixStackIn.translate(0.0D, -0.1F + (1 - f) * -1, -(double) 0.5);
        matrixStackIn.scale(1F, -(0.2F + f * 0.9F), 1F);
        MODEL.setupAnim(entityIn, 0.0F, 0.0F, ageInTicks, 0.0F, 0.0F);
        VertexConsumer ivertexbuilder = bufferIn.getBuffer(RenderType.entityTranslucent(getWaveTexture(entityIn.activeWaveTicks)));
        int waterColorAt = entityIn.level().getBiome(entityIn.blockPosition()).get().getWaterColor();
        float colorR = (waterColorAt >> 16 & 255) / 255F;
        float colorG = (waterColorAt >> 8 & 255) / 255F;
        float colorB = (waterColorAt & 255) / 255F;
        MODEL.renderToBuffer(matrixStackIn, ivertexbuilder, packedLightIn, OverlayTexture.NO_OVERLAY, colorR, colorG, colorB, 1.0F);
        VertexConsumer ivertexbuilder2 = bufferIn.getBuffer(RenderType.entityTranslucent(getOverlayTexture(entityIn.activeWaveTicks)));
        MODEL.renderToBuffer(matrixStackIn, ivertexbuilder2, packedLightIn, OverlayTexture.NO_OVERLAY, 1.0F, 1.0F, 1.0F, 1.0F);
        matrixStackIn.popPose();
        super.render(entityIn, entityYaw, partialTicks, matrixStackIn, bufferIn, packedLightIn);
    }

public void render(PoseStack poseStack, MultiBufferSource bufferIn, int packedLightIn, T entity, float limbSwing, float limbSwingAmount, float partialTicks, float ageInTicks, float netHeadYaw, float headPitch) {
        if (entity.getPossessedByLicowitchId() != -1) {
