@Override
	protected void createNextCurve() {
		AnimationPlayer animPlayer = this.owner.getAnimator().getPlayerFor(this.animation);
		boolean isTrailInvisible = animPlayer.getAnimation().get().isLinkAnimation() || animPlayer.getElapsedTime() <= this.trailInfo.startTime();
		boolean isFirstTrail = this.trailEdges.isEmpty();
		boolean needCorrection = (!isTrailInvisible && isFirstTrail);

		if (needCorrection) {
			float startCorrection = Math.max((this.trailInfo.startTime() - animPlayer.getPrevElapsedTime()) / (animPlayer.getElapsedTime() - animPlayer.getPrevElapsedTime()), 0.0F);
			this.startEdgeCorrection = this.trailInfo.interpolateCount() * 2 * startCorrection;
		}

		TrailInfo trailInfo = this.trailInfo;
		Pose prevPose = this.owner.getAnimator().getPose(0.0F);//this.lastPose;
		Pose currentPose = this.owner.getAnimator().getPose(1.0F);
		Pose middlePose = this.owner.getAnimator().getPose(0.5F);//Pose.interpolatePose(prevPose, currentPose, 0.5F);

		Vec3 posOld = this.owner.getOriginal().getPosition(0.0F);
		Vec3 posCur = this.owner.getOriginal().getPosition(1.0F);
		Vec3 posMid = MathUtils.lerpVector(posOld, posCur, 0.5F);

		OpenMatrix4f prevModelMatrix = this.owner.getModelMatrix(0.0F);
		OpenMatrix4f curModelMatrix = this.owner.getModelMatrix(1.0F);
		JointTransform lastTransform = JointTransform.fromMatrix(curModelMatrix);
		JointTransform currentTransform = JointTransform.fromMatrix(curModelMatrix);

		OpenMatrix4f prvmodelTf
			= OpenMatrix4f
				.createTranslation((float)posOld.x, (float)posOld.y, (float)posOld.z)
				.rotateDeg(180.0F, Vec3f.Y_AXIS)
				.mulBack(prevModelMatrix);
		OpenMatrix4f middleModelTf
			= OpenMatrix4f
				.createTranslation((float)posMid.x, (float)posMid.y, (float)posMid.z)
				.rotateDeg(180.0F, Vec3f.Y_AXIS)
				.mulBack(JointTransform.interpolate(lastTransform, currentTransform, 0.5F).toMatrix());
		OpenMatrix4f curModelTf
			= OpenMatrix4f
				.createTranslation((float)posCur.x, (float)posCur.y, (float)posCur.z)
				.rotateDeg(180.0F, Vec3f.Y_AXIS)
				.mulBack(curModelMatrix);

		OpenMatrix4f prevJointTf = this.owner.getArmature().getBoundTransformFor(prevPose, this.joint).mulFront(prvmodelTf);
		OpenMatrix4f middleJointTf = this.owner.getArmature().getBoundTransformFor(middlePose, this.joint).mulFront(middleModelTf);
		OpenMatrix4f currentJointTf = this.owner.getArmature().getBoundTransformFor(currentPose, this.joint).mulFront(curModelTf);
		Vec3 prevStartPos = OpenMatrix4f.transform(prevJointTf, trailInfo.start());
		Vec3 prevEndPos = OpenMatrix4f.transform(prevJointTf, trailInfo.end());
		Vec3 middleStartPos = OpenMatrix4f.transform(middleJointTf, trailInfo.start());
		Vec3 middleEndPos = OpenMatrix4f.transform(middleJointTf, trailInfo.end());
		Vec3 currentStartPos = OpenMatrix4f.transform(currentJointTf, trailInfo.start());
		Vec3 currentEndPos = OpenMatrix4f.transform(currentJointTf, trailInfo.end());

		List<Vec3> finalStartPositions;
		List<Vec3> finalEndPositions;
		boolean visibleTrail;

		if (isTrailInvisible) {
			finalStartPositions = Lists.newArrayList();
			finalEndPositions = Lists.newArrayList();
			finalStartPositions.add(prevStartPos);
			finalStartPositions.add(middleStartPos);
			finalEndPositions.add(prevEndPos);
			finalEndPositions.add(middleEndPos);

			this.invisibleTrailEdges.clear();
			visibleTrail = false;
		} else {
			List<Vec3> startPosList = Lists.newArrayList();
			List<Vec3> endPosList = Lists.newArrayList();
			TrailEdge edge1;
			TrailEdge edge2;

			if (isFirstTrail) {
				int lastIdx = this.invisibleTrailEdges.size() - 1;
				edge1 = this.invisibleTrailEdges.get(lastIdx);
				edge2 = new TrailEdge(prevStartPos, prevEndPos, -1);
			} else {
				edge1 = this.trailEdges.get(this.trailEdges.size() - (this.trailInfo.interpolateCount() / 2 + 1));
				edge2 = this.trailEdges.get(this.trailEdges.size() - 1);
				edge2.lifetime++;
			}

			startPosList.add(edge1.start);
			endPosList.add(edge1.end);
			startPosList.add(edge2.start);
			endPosList.add(edge2.end);
			startPosList.add(middleStartPos);
			endPosList.add(middleEndPos);
			startPosList.add(currentStartPos);
			endPosList.add(currentEndPos);

			finalStartPositions = CubicBezierCurve.getBezierInterpolatedPoints(startPosList, 1, 3, this.trailInfo.interpolateCount());
			finalEndPositions = CubicBezierCurve.getBezierInterpolatedPoints(endPosList, 1, 3, this.trailInfo.interpolateCount());

			if (!isFirstTrail) {
				finalStartPositions.remove(0);
				finalEndPositions.remove(0);
			}

			visibleTrail = true;
		}

		this.makeTrailEdges(finalStartPositions, finalEndPositions, visibleTrail ? this.trailEdges : this.invisibleTrailEdges);
	}

@Override
	public void render(VertexConsumer vertexConsumer, Camera camera, float partialTick) {
		if (this.trailEdges.isEmpty()) {
			return;
		}

		PoseStack poseStack = new PoseStack();
		int light = this.getLightColor(partialTick);
		this.setupPoseStack(poseStack, camera, partialTick);
		Matrix4f matrix4f = poseStack.last().pose();
		int edges = this.trailEdges.size() - 1;
		boolean startFade = this.trailEdges.get(0).lifetime == 1;
		boolean endFade = this.trailEdges.get(edges).lifetime == this.trailInfo.trailLifetime();
		float startEdge = (startFade ? this.trailInfo.interpolateCount() * 2 * partialTick : 0.0F) + this.startEdgeCorrection;
		float endEdge = endFade ? Math.min(edges - (this.trailInfo.interpolateCount() * 2) * (1.0F - partialTick), edges - 1) : edges - 1;
		float interval = 1.0F / (endEdge - startEdge);
		float fading = 1.0F;

		if (this.shouldRemove) {
			if (TrailInfo.isValidTime(this.trailInfo.fadeTime())) {
				fading = ((float)(this.lifetime - this.age) / (float)this.trailInfo.trailLifetime());
			} else {
				fading = Mth.clamp(((this.lifetime - this.age) + (1.0F - partialTick)) / this.trailInfo.trailLifetime(), 0.0F, 1.0F);
			}
		}

		float partialStartEdge = interval * (startEdge % 1.0F);
		float from = -partialStartEdge;
		float to = -partialStartEdge + interval;

		for (int i = (int)(startEdge); i < (int)endEdge + 1; i++) {
			TrailEdge e1 = this.trailEdges.get(i);
			TrailEdge e2 = this.trailEdges.get(i + 1);
			Vector4f pos1 = new Vector4f((float)e1.start.x, (float)e1.start.y, (float)e1.start.z, 1.0F);
			Vector4f pos2 = new Vector4f((float)e1.end.x, (float)e1.end.y, (float)e1.end.z, 1.0F);
			Vector4f pos3 = new Vector4f((float)e2.end.x, (float)e2.end.y, (float)e2.end.z, 1.0F);
			Vector4f pos4 = new Vector4f((float)e2.start.x, (float)e2.start.y, (float)e2.start.z, 1.0F);

			pos1.mul(matrix4f);
			pos2.mul(matrix4f);
			pos3.mul(matrix4f);
			pos4.mul(matrix4f);

			float alphaFrom = Mth.clamp(from, 0.0F, 1.0F);
			float alphaTo = Mth.clamp(to, 0.0F, 1.0F);

			vertexConsumer.addVertex(pos1.x(), pos1.y(), pos1.z()).setUv(from, 1.0F).setColor(this.rCol, this.gCol, this.bCol, this.alpha * alphaFrom * fading).setLight(light);
			vertexConsumer.addVertex(pos2.x(), pos2.y(), pos2.z()).setUv(from, 0.0F).setColor(this.rCol, this.gCol, this.bCol, this.alpha * alphaFrom * fading).setLight(light);
			vertexConsumer.addVertex(pos3.x(), pos3.y(), pos3.z()).setUv(to, 0.0F).setColor(this.rCol, this.gCol, this.bCol, this.alpha * alphaTo * fading).setLight(light);
			vertexConsumer.addVertex(pos4.x(), pos4.y(), pos4.z()).setUv(to, 1.0F).setColor(this.rCol, this.gCol, this.bCol, this.alpha * alphaTo * fading).setLight(light);

			from += interval;
			to += interval;
		}
	}

@Override
	public void render(VertexConsumer vertexConsumer, Camera camera, float partialTick) {
		float alpha = Mth.lerp(partialTick, this.alphaO, this.alpha);
		int lightColor = this.getLightColor(partialTick);
		PoseStack poseStack = new PoseStack();
		this.setupPoseStack(poseStack, camera, partialTick);
		MultiBufferSource.BufferSource buffers = Minecraft.getInstance().renderBuffers().bufferSource();
		this.entitySnapshot.renderTextured(poseStack, buffers, EpicFightRenderTypes::entityAfterimageStencil, Mesh.DrawingFunction.POSITION_TEX, 0, 0.0F, 0.0F, 0.0F, 1.0F);
		this.entitySnapshot.renderItems(poseStack, buffers, EpicFightRenderTypes.itemAfterimageStencil(), Mesh.DrawingFunction.POSITION_TEX, lightColor, 1.0F);
		buffers.endLastBatch();

		this.entitySnapshot.renderTextured(poseStack, buffers, EpicFightRenderTypes::entityAfterimageTranslucent, Mesh.DrawingFunction.NEW_ENTITY, lightColor, this.rCol, this.gCol, this.bCol, alpha);
		this.entitySnapshot.renderItems(poseStack, buffers, EpicFightRenderTypes.itemAfterimageTranslucent(), Mesh.DrawingFunction.NEW_ENTITY, lightColor, alpha);
		buffers.endLastBatch();

		this.revert(poseStack);
	}

@Override
    @Deprecated
    public void render(float pTicks, PoseStack poseStack, MultiBufferSource bufferSourceList) {
        var world = Minecraft.getInstance().level;
        if (world == null) return;

        var matrixTranslation = this.getRenderPosition(pTicks);
        var now = world.getGameTime() + pTicks;

        if (this.getTrailMaxLength() <= 0) return;

        var buffer = OctoRenderManager.getOrCreateBuffer(this);

        if (buffer == null)
            return;

        var aliveNow = this.isTrailAlive();
        var growingNow = aliveNow && this.isTrailGrowing();
        var minDistance = getTrailMinSampleDistance();
        var minDistanceSq = minDistance * minDistance;

        if (growingNow) {
            var head = buffer.peekFirst();
            if (head == null) {
                buffer.write(matrixTranslation, now);
            } else {
                var distSq = head.position().distanceToSqr(matrixTranslation);
                if (distSq >= minDistanceSq && now > head.time()) {
                    var samplesPerTick = Math.max(1, getTrailSamplesPerTick());
                    var sampleInterval = 1.0 / samplesPerTick;
                    var deltaTime = Math.max(1e-6, now - head.time());
                    var stepsByTime = (int) Math.floor(deltaTime / sampleInterval);

                    if (stepsByTime > 0) {
                        var stepsByDistance = (int) Math.ceil(Math.sqrt(distSq) / minDistance);
                        var steps = Math.min(stepsByTime, Math.max(1, stepsByDistance));

                        for (int i = 1; i <= steps; i++) {
                            var sampleTime = head.time() + sampleInterval * i;
                            if (sampleTime > now) break;
                            double t = (sampleTime - head.time()) / deltaTime;
                            var samplePos = head.position().lerp(matrixTranslation, t);
                            buffer.write(samplePos, sampleTime);
                        }
                    }
                }
            }
        }

        var maxAge = getTrailEffectiveMaxAgeTicks(growingNow);
        buffer.pruneOlderThan(now - maxAge);
        buffer.trimToSize(this.getTrailMaxSamples());

        var points = new ArrayList<Vec3>();
        var lifeFractions = new ArrayList<Float>();

        if (aliveNow) {
            var headLife = 0f;
            if (!growingNow && buffer.peekFirst() != null) {
                headLife = (float) Mth.clamp((now - buffer.peekFirst().time()) / maxAge, 0.0, 1.0);
            }
            points.add(Vec3.ZERO);
            lifeFractions.add(headLife);
        }

        for (var sample : buffer) {
            var relative = sample.position().subtract(matrixTranslation);
            var life = (float) Mth.clamp((now - sample.time()) / maxAge, 0.0, 1.0);
            points.add(relative);
            lifeFractions.add(life);
        }

        if (points.size() < 2) return;

        points = new ArrayList<>(this.getTrailRenderPositions(points, pTicks));
        if (points.size() != lifeFractions.size()) {
            var size = Math.min(points.size(), lifeFractions.size());
            points = new ArrayList<>(points.subList(0, size));
            lifeFractions = new ArrayList<>(lifeFractions.subList(0, size));
        }

        if (points.size() > 1) {
            var densePoints = new ArrayList<Vec3>(points.size());
            var denseLives = new ArrayList<Float>(lifeFractions.size());
            var maxSteps = Math.max(2, getTrailSamplesPerTick() * 4);

            densePoints.add(points.getFirst());
            denseLives.add(lifeFractions.getFirst());

            for (int i = 0; i < points.size() - 1; i++) {
                var p1 = points.get(i);
                var p2 = points.get(i + 1);
                var l1 = lifeFractions.get(i);
                var l2 = lifeFractions.get(i + 1);
                var dist = p1.distanceTo(p2);

                if (dist > minDistance) {
                    var steps = (int) Math.ceil(dist / minDistance);
                    steps = Math.min(steps, maxSteps);

                    for (int s = 1; s < steps; s++) {
                        float t = s / (float) steps;
                        densePoints.add(p1.lerp(p2, t));
                        denseLives.add(Mth.lerp(t, l1, l2));
                    }
                }

                densePoints.add(p2);
                denseLives.add(l2);
            }

            points = densePoints;
            lifeFractions = denseLives;
        }

        var partialPoses = new ArrayList<Vec3>();
        var partialLives = new ArrayList<Float>();

        if (points.size() > 2) {
            for (var i = 0; i < points.size() - 1; i++) {
                var p0 = i == 0 ? points.getFirst() : points.get(i - 1);
                var p1 = points.get(i);
                var p2 = points.get(i + 1);
                var p3 = i == points.size() - 2 ? points.getLast() : points.get(i + 2);

                var l1 = lifeFractions.get(i);
                var l2 = lifeFractions.get(i + 1);

                partialPoses.add(p1);
                partialLives.add(l1);

                var interpolationPoints = Math.max(1, this.getTrailInterpolationPoints() + 1);
                for (float f = 1f / interpolationPoints; f < 1; f += 1f / interpolationPoints) {
                    partialPoses.add(VectorUtils.catmullromVec(f, p0, p1, p2, p3));
                    partialLives.add(Mth.lerp(f, l1, l2));
                }
            }
            partialPoses.add(points.getLast());
            partialLives.add(lifeFractions.getLast());
        } else {
            partialPoses.addAll(points);
            partialLives.addAll(lifeFractions);
        }

        if (partialPoses.size() < 2) return;

        var cleanPoses = new ArrayList<Vec3>();
        var cleanLives = new ArrayList<Float>();
        for (var i = 0; i < partialPoses.size(); i++) {
            var v = partialPoses.get(i);
            if (v == null) continue;
            cleanPoses.add(v);
            cleanLives.add(partialLives.get(i));
        }

        partialPoses = cleanPoses;
        partialLives = cleanLives;

        if (partialPoses.size() < 2) return;

        var faces = Math.max(1, getTrailFaces());
        var ringSize = faces == 1 ? 2 : faces;
        var crossVecs = new Vec3[partialPoses.size()][ringSize];
        var lastIndex = partialPoses.size() - 1;
        var baseScale = this.getTrailScale();

        var widthPower = Math.max(0.05, getTrailWidthPower());
        var angleStep = faces == 1 ? 180.0 : 360.0 / faces;

        for (var i = 0; i < partialPoses.size(); i++) {
            var current = partialPoses.get(i);
            if (current == null) continue;

            var prev = i == 0 ? current : partialPoses.get(i - 1);
            var next = i == lastIndex ? current : partialPoses.get(i + 1);

            var tangent = next.subtract(prev);
            if (tangent.lengthSqr() < 1e-6) continue;

            var perpendicular = tangent.cross(Y_VEC);
            if (perpendicular.lengthSqr() < 1e-6) {
                perpendicular = tangent.cross(VectorUtils.X_VEC);
            }

            if (perpendicular.lengthSqr() < 1e-6) continue;

            var axis = tangent.normalize();
            var base = perpendicular.normalize();

            var ratio = 1.0 - Math.pow((double) i / Math.max(1, lastIndex), widthPower);
            var scale = baseScale * ratio;
            if (scale <= 1e-6) {
                continue;
            }

            var first = base.scale(scale);
            for (var j = 0; j < ringSize; j++) {
                crossVecs[i][j] = VectorUtils.rotate(first, axis, angleStep * j);
            }
        }

        var color1 = new Color(this.getTrailFadeInColor(), true);
        var color2 = new Color(this.getTrailFadeOutColor(), true);

        poseStack.pushPose();

        var matrix4f = poseStack.last().pose();
        var tes = bufferSourceList.getBuffer(TRAIL_RENDER_TYPE);

        for (var i = 0; i < partialPoses.size() - 1; i++) {
            var pos1 = partialPoses.get(i);
            var pos2 = partialPoses.get(i + 1);

            if (pos1 == null || pos2 == null) continue;
            if (pos2.subtract(pos1).lengthSqr() < 1e-6) continue;

            var t1 = i / (float) (partialPoses.size() - 1);
            var t2 = (i + 1) / (float) (partialPoses.size() - 1);
            var c1 = ColorUtils.blend(color1, color2, t1);
            var c2 = ColorUtils.blend(color1, color2, t2);

            for (var j = 0; j < ringSize; j++) {
                var jNext = (j + 1) % ringSize;
                var o1a = crossVecs[i][j];
                var o1b = crossVecs[i][jNext];
                var o2a = crossVecs[i + 1][j];
                var o2b = crossVecs[i + 1][jNext];
                if (o1a == null || o1b == null || o2a == null || o2b == null) continue;

                TesselatorUtils.drawQuadGradient(tes, matrix4f,
                        (float) (pos2.x + o2b.x), (float) (pos2.y + o2b.y), (float) (pos2.z + o2b.z),
                        (float) (pos1.x + o1b.x), (float) (pos1.y + o1b.y), (float) (pos1.z + o1b.z),
                        (float) (pos1.x + o1a.x), (float) (pos1.y + o1a.y), (float) (pos1.z + o1a.z),
                        (float) (pos2.x + o2a.x), (float) (pos2.y + o2a.y), (float) (pos2.z + o2a.z),
                        c2, c1);
            }
        }

        poseStack.popPose();
    }

@Override
    public void render(ScytheBoomerang entityIn, float entityYaw, float partialTicks, PoseStack poseStack, MultiBufferSource bufferIn, int packedLightIn) {
        poseStack.pushPose();
        var stack = entityIn.getItem();
        var model = this.itemRenderer.getModel(stack, entityIn.level(), null, 1);
        if (entityIn.isNarrow()) {
            Vec3 direction = entityIn.getDeltaMovement().normalize();
            float yRot = ((float) (Mth.atan2(direction.x, direction.z)));
            poseStack.mulPose(Axis.YP.rotation(yRot+1.57f));
        }
        else {
            poseStack.mulPose(Axis.XP.rotationDegrees(90f));
        }
        poseStack.mulPose(Axis.ZP.rotation((entityIn.age + partialTicks) * 0.9f));
        poseStack.scale(2f, 2, 1.5f);
        itemRenderer.render(stack, stack.getItem() instanceof MalumScytheItem ? ItemDisplayContext.NONE : ItemDisplayContext.FIXED, false, poseStack, bufferIn, packedLightIn, OverlayTexture.NO_OVERLAY, model);
        poseStack.popPose();

        var spirit = stack.getItem() instanceof ISpiritAffiliatedItem affiliatedItem ? affiliatedItem.getDefiningSpiritType(stack) : null;
        boolean isMagical = spirit != null;
        var renderType = isMagical ?
                LodestoneRenderTypes.ADDITIVE_TWO_SIDED_TEXTURE_TRIANGLE.apply(MalumRenderTypeTokens.CONCENTRATED_TRAIL) :
                LodestoneRenderTypes.TRANSPARENT_TWO_SIDED_TEXTURE_TRIANGLE.apply(MalumRenderTypeTokens.CONCENTRATED_TRAIL).addUniformData(UniformData.LUMITRANSPARENT);
        var primaryColor = isMagical ? spirit.getPrimaryColor() : new Color(0.9f, 0.9f, 0.9f);
        var secondaryColor = isMagical ? spirit.getSecondaryColor() : new Color(0.5f, 0.5f, 0.5f);
        var builder = VFXBuilders.createWorld().setRenderType(renderType);
        final float scalar = Math.min(entityIn.age / 20f, 1f);
        RenderUtils.renderEntityTrail(poseStack, builder, entityIn.theFormer, entityIn, primaryColor, secondaryColor, scalar, partialTicks);
        RenderUtils.renderEntityTrail(poseStack, builder, entityIn.theLatter, entityIn, primaryColor, secondaryColor, scalar, partialTicks);

        super.render(entityIn, entityYaw, partialTicks, poseStack, bufferIn, packedLightIn);
    }

@Override
    public void render(T entity, float entityYaw, float partialTicks, PoseStack poseStack, MultiBufferSource bufferIn, int packedLightIn) {
        if (entity.isAwaitingSpawn()) {
            return;
        }
        float delta = entity.getVisualEffectScalar();
        float scale = delta * getScaleMultiplier();
        float alpha = Mth.clamp(delta * getAlphaMultiplier(), 0, 1);
        WorldVFXBuilder builder = VFXBuilders.createWorld().setRenderType(getTrailRenderType(true));
        RenderUtils.renderEntityTrail(poseStack, builder, entity.trailPointBuilder, entity, getPrimaryColor(0), getSecondaryColor(0), scale * 2f, alpha, partialTicks);
        RenderUtils.renderEntityTrail(poseStack, builder, entity.spinningTrailPointBuilder, entity, getPrimaryColor(1), getSecondaryColor(1), scale * 2f, alpha, partialTicks);
        builder.setRenderType(getTrailRenderType(false));
        RenderUtils.renderEntityTrail(poseStack, builder, entity.trailPointBuilder, entity, getPrimaryColor(2), getSecondaryColor(2), scale, alpha, partialTicks);
        RenderUtils.renderEntityTrail(poseStack, builder, entity.spinningTrailPointBuilder, entity, getPrimaryColor(3), getSecondaryColor(3), scale, alpha, partialTicks);
        super.render(entity, entityYaw, partialTicks, poseStack, bufferIn, packedLightIn);
    }

@OnlyIn(Dist.CLIENT)
    @Override
    public void act(Level level, RandomSource random, NetworkedParticleEffectPositionData positionData, MalumNetworkedParticleEffectColorData colorData, WeaponParticleEffectData extraData) {
        float offsetBase = Easing.SINE_IN_OUT.asWeighedRandom(random, 0.4f, 0.8f) * (random.nextBoolean() ? 1 : -1) + (extraData.isMirrored() ? 3.14f : 0);
        for (int i = 0; i < 8; i++) {
            ParticleEffectSpawner slash;
            if (i >= 6) {
                slash = WeaponParticleEffects.spawnSlashParticle(level, positionData.getAsVector(), MalumParticles.SLASH, ColorParticleData.create(0.15f, 0.05f, 0.1f).build());
                slash.getBuilder().setRenderType(LodestoneWorldParticleRenderType.TRANSPARENT);
            } else {
                slash = WeaponParticleEffects.spawnSlashParticle(level, positionData.getAsVector(), MalumParticles.SLASH, colorData);
            }
            var direction = extraData.getDirection();
            float spinOffset = extraData.getSlashRotation() + (i % 2 == 0 ? 1 : -1) * offsetBase;
            int lifeDelay = (i % 2 == 0 ? 3 : 0);
            slash.getBuilder()
                    .setSpinData(SpinParticleData.create(0).setSpinOffset(spinOffset).build())
                    .setScaleData(GenericParticleData.create(Easing.SINE_IN_OUT.asWeighedRandom(random, 1f, 2f)).build())
                    .setMotion(direction.scale(Easing.SINE_IN_OUT.asWeighedRandom(random, 0.5f, 0.7f)))
                    .setLifeDelay(lifeDelay)
                    .setBehavior(PointyDirectionalParticleBehavior.pointyDirectional(direction));
            slash.spawnParticles();
        }
    }

@OnlyIn(Dist.CLIENT)
    @Override
    public void act(Level level, RandomSource random, NetworkedParticleEffectPositionData positionData, MalumNetworkedParticleEffectColorData colorData, WeaponParticleEffectData extraData) {
        var direction = extraData.getDirection();
        float yRot = ((float) (Mth.atan2(direction.x, direction.z) * (double) (180F / (float) Math.PI)));
        float yaw = (float) Math.toRadians(yRot);
        Vec3 left = new Vec3(-Math.cos(yaw), 0, Math.sin(yaw));
        for(int i = 0; i < 3; i++) {
            final Vec3 pos = positionData.getAsVector();
            for (int j = 0; j < 16; j++) {
                float spinOffset = extraData.getSlashRotation() + Easing.SINE_IN_OUT.asWeighedRandom(random, -0.5f, 0.5f) + (extraData.isMirrored() ? 3.14f : 0);
                float slashAngle = (i*0.33f+j) / 16f * (float) Math.PI * 2f;
                var slashDirection = left.scale(Math.sin(slashAngle))
                        .add(direction.scale(Math.cos(slashAngle)))
                        .normalize();
                var slashPosition = pos.add(slashDirection.scale(0.14f));

                var slash = WeaponParticleEffects.spawnSlashParticle(level, slashPosition, MalumParticles.ROUNDABOUT_SLASH, colorData);
                slash.getBuilder()
                        .setSpinData(SpinParticleData.create(0).setSpinOffset(spinOffset).build())
                        .setScaleData(GenericParticleData.create(Easing.SINE_IN_OUT.asWeighedRandom(random, 2.5f, 5f)).build())
                        .setMotion(slashDirection.scale(Easing.SINE_IN_OUT.asWeighedRandom(random, 0.05f, 0.2f)).add(0, 0.2f, 0))
                        .setLifetime(12+i)
                        .setLifeDelay(i+j/4)
                        .setBehavior(PointyDirectionalParticleBehavior.pointyDirectional(slashDirection));
                slash.spawnParticles();
            }
            var slash = WeaponParticleEffects.spawnSlashParticle(level, pos, MalumParticles.ROUNDABOUT_SLASH, colorData);
            slash.getBuilder()
                    .setSpinData(SpinParticleData.create(0).setSpinOffset(i * 1.57f).build())
                    .setScaleData(GenericParticleData.create(Easing.SINE_IN_OUT.asWeighedRandom(random, 4.5f, 5f)).build())
                    .setLifetime(12)
                    .setLifeDelay(i*2)
                    .setBehavior(DirectionalParticleBehavior.directional(new Vec3(0, 1, 0)));
            slash.spawnParticles();
        }
    }

