@OnlyIn(Dist.CLIENT)
    @Override
    public void act(Level level, RandomSource random, NetworkedParticleEffectPositionData positionData, MalumNetworkedParticleEffectColorData colorData, Vec3 projectileDirection, Vec3 left, Vec3 up) {
        Vec3 pos = positionData.getAsVector();

        for (int i = 0; i < 16; i++) {
            var color = colorData.getColor();
            float spread = Easing.SINE_IN_OUT.asWeighedRandom(random, 0.1f, 0.5f);
            float speed = Easing.SINE_IN_OUT.asWeighedRandom(random, 0.3f, 0.4f);
            float distance = Easing.SINE_IN_OUT.asWeighedRandom(random, 3f, 6f);
            float angle = i / 16f * (float) Math.PI * 2f;

            Vec3 direction = projectileDirection
                    .add(left.scale(Math.sin(angle) * spread))
                    .add(up.scale(Math.cos(angle) * spread))
                    .normalize().scale(speed);
            Vec3 spawnPosition = pos.add(direction.scale(distance));
            direction = direction.reverse();
            float lifetimeMultiplier = 0.7f;
            if (random.nextFloat() < 0.8f) {
                var lightSpecs = spiritLightSpecs(level, spawnPosition, color);
                lightSpecs.getBuilder()
                        .disableNoClip()
                        .multiplyLifetime(lifetimeMultiplier)
                        .setRenderType(LodestoneWorldParticleRenderType.LUMITRANSPARENT)
                        .enableForcedSpawn()
                        .modifyScaleData(d -> d.multiplyValue(1.75f))
                        .setMotion(direction);
                lightSpecs.getBloomBuilder()
                        .disableNoClip()
                        .multiplyLifetime(lifetimeMultiplier)
                        .setRenderType(LodestoneWorldParticleRenderType.LUMITRANSPARENT)
                        .modifyScaleData(d -> d.multiplyValue(1.75f))
                        .setMotion(direction);
                lightSpecs.spawnParticles();
            }
            if (random.nextFloat() < 0.8f) {
                var sparks = SparkParticleEffects.spiritMotionSparks(level, spawnPosition, color);
                sparks.getBuilder()
                        .disableNoClip()
                        .multiplyLifetime(lifetimeMultiplier)
                        .setRenderType(LodestoneWorldParticleRenderType.LUMITRANSPARENT)
                        .enableForcedSpawn()
                        .modifyScaleData(d -> d.multiplyValue(1.75f))
                        .modifyLengthData(d -> d.multiplyValue(3f))
                        .setMotion(direction.scale(1.5f));
                sparks.getBloomBuilder()
                        .disableNoClip()
                        .multiplyLifetime(lifetimeMultiplier)
                        .setRenderType(LodestoneWorldParticleRenderType.LUMITRANSPARENT)
                        .modifyScaleData(d -> d.multiplyValue(1.75f))
                        .setMotion(direction.scale(1.5f));
                sparks.spawnParticles();
            }
        }
    }

@OnlyIn(Dist.CLIENT)
    @Override
    public void act(Level level, RandomSource random, NetworkedParticleEffectPositionData positionData, MalumNetworkedParticleEffectColorData colorData, UnwindingChaosChargeEffectData extraData) {
        final Entity entity = level.getEntity(extraData.entityId);
        if (entity != null) {
            var smokeColor = new Color(45, 15, 15);
            long gameTime = level.getGameTime();
            var pos = positionData.getAsVector();
            var direction = pos.subtract(entity.position()).normalize();
            float yRot = ((float) (Mth.atan2(direction.x, direction.z) * (double) (180F / (float) Math.PI)));
            float yaw = (float) Math.toRadians(yRot);
            Vec3 left = new Vec3(-Math.cos(yaw), 0, Math.sin(yaw));
            Vec3 up = left.cross(direction);

            Consumer<LodestoneWorldParticle> behavior = p -> {
                Vec3 distance = entity.position().add(0, entity.getBbHeight() / 2f, 0).subtract(p.getParticlePosition());
                if (distance.length() == 0) {
                    distance = new Vec3(0, 0.02f, 0);
                }
                float delta = Math.max(p.getAge() / (float) p.getLifetime(), 0);
                float lerp = Easing.QUINTIC_IN_OUT.lerp(delta, 0.05f, 0.5f);
                float velocity = (float) Easing.CIRC_IN.lerp(delta, 0.05f, 0.2f + distance.length() * 1.2f);
                final Vec3 speed = p.getParticleSpeed().lerp(distance.normalize().scale(velocity), lerp);
                p.setParticleSpeed(speed);
            };

            for (int i = 0; i < 16; i++) {
                SpiritArcanaType cyclingSpiritType = colorData.getSpirit();
                float spread = Easing.SINE_IN_OUT.asWeighedRandom(random, 0.5f, 0.6f);
                float speed = Easing.SINE_IN_OUT.asWeighedRandom(random, 0.6f, 0.8f);
                float angle = i / 16f * (float) Math.PI * 2f;
                Vec3 particleDirection = direction
                        .add(left.scale(Math.sin(angle) * spread))
                        .add(up.scale(Math.cos(angle) * spread))
                        .normalize().scale(speed);
                Vec3 particlePosition = pos.add(particleDirection.scale(2f));
                var lightSpecs = spiritLightSpecs(level, particlePosition, cyclingSpiritType, new WorldParticleOptions(MalumParticles.SPARK.get()));
                var transparencyData = GenericParticleData.create(0.4f, 0.8f, 0f).setEasing(Easing.SINE_IN_OUT, Easing.EXPO_IN_OUT).build();
                int lifeDelay = i * 2;
                int lifetime = 20;
                lightSpecs.getBuilder()
                        .setBehavior(SparkParticleBehavior.sparkBehavior())
                        .setLengthData(GenericParticleData.create(0.2f, 2f, 0f).setEasing(Easing.SINE_IN, Easing.SINE_IN_OUT).build())
                        .modifyScaleData(d -> d.multiplyValue(Easing.SINE_IN_OUT.asWeighedRandom(random, 2, 2.5f)))
                        .modifyColorData(c -> c.multiplyCoefficient(0.5f))
                        .setTransparencyData(transparencyData)
                        .setLifeDelay(lifeDelay)
                        .setLifetime(lifetime)
                        .addTickActor(behavior);
                lightSpecs.getBloomBuilder()
                        .setTransparencyData(transparencyData)
                        .setLifeDelay(lifeDelay)
                        .setLifetime(lifetime)
                        .addTickActor(behavior)
                        .modifyColorData(c -> c.multiplyCoefficient(0.5f))
                        .modifyScaleData(d -> d.multiplyValue(Easing.SINE_IN_OUT.asWeighedRandom(random, 0.7f, 1.1f)))
                        .modifyTransparencyData(d -> d.multiplyCoefficient(1.4f));
                lightSpecs.spawnParticles();

                lightSpecs = spiritLightSpecs(level, particlePosition, cyclingSpiritType, new WorldParticleOptions(LodestoneParticleTypes.WISP_PARTICLE.get()));
                transparencyData = GenericParticleData.create(1f, 0f).setCoefficient(1.5f).build();
                lightSpecs.getBuilder()
                        .setRenderType(LodestoneWorldParticleRenderType.LUMITRANSPARENT)
                        .setColorData(ColorParticleData.create(smokeColor).build())
                        .setTransparencyData(transparencyData)
                        .setLifeDelay(lifeDelay)
                        .addTickActor(behavior)
                        .setLifetime(lifetime);
                lightSpecs.spawnParticlesRaw();
            }
        }
    }

public static void lifeWeaverHealingBeam(Level level, RandomSource random, NetworkedParticleEffectPositionData positionData, MalumNetworkedParticleEffectColorData colorData, LifeweaverHealingBeamParticleEffect.LifeweaverHealingBeamEffectData extraData) {
        var target = level.getEntity(extraData.targetId());
        var source = level.getEntity(extraData.sourceId());
        if (target != null && source != null) {
            var pos = positionData.getAsVector();
            final Vec3 targetPos = target.position().add(0, target.getBbHeight() / 2f, 0);
            var direction = targetPos.subtract(pos).normalize();
            float yRot = ((float) (Mth.atan2(direction.x, direction.z) * (double) (180F / (float) Math.PI)));
            float yaw = (float) Math.toRadians(yRot);
            Vec3 left = new Vec3(-Math.cos(yaw), 0, Math.sin(yaw));
            Vec3 up = left.cross(direction);

            final Consumer<LodestoneWorldParticle> behavior = p -> {
                float partialTick = Minecraft.getInstance().getTimer().getGameTimeDeltaPartialTick(true);
                var spark = (SparkParticleBehavior) p.behavior;
                final Vec3 distance = target.getPosition(partialTick).add(0, target.getBbHeight()/2f, 0).subtract(p.getParticlePosition());
                spark.setForcedDirection(distance.normalize());
                final float length = (float) Math.clamp(distance.length(), 2, 4);
                p.lengthData.overrideValueMultiplier(length / 6f);
                p.scaleData.overrideValueMultiplier(length / 4f);
            };
            for (int i = 0; i < 4; i++) {
                SpiritArcanaType cyclingSpiritType = colorData.getSpirit();
                float spread = Easing.SINE_IN_OUT.asWeighedRandom(random, 0.6f, 0.8f);
                float speed = Easing.SINE_IN_OUT.asWeighedRandom(random, 0.6f, 0.8f);
                float angle = i / 4f * (float) Math.PI * 2f;
                Vec3 particleDirection = direction
                        .add(left.scale(Math.sin(angle) * spread))
                        .add(up.scale(Math.cos(angle) * spread))
                        .normalize().scale(speed);
                Vec3 particlePosition = pos.add(particleDirection.scale(0.4f));
                final int lifeDelay = i * 2;
                SpiritBasedParticleBuilder.createSpirit(LodestoneParticleTypes.EXTRUDING_SPARK_PARTICLE)
                        .setSpirit(cyclingSpiritType)
                        .setTransparencyData(GenericParticleData.create(0f, 0.7f, 0).setEasing(Easing.SINE_IN_OUT, Easing.SINE_IN_OUT).build())
                        .setLengthData(GenericParticleData.create(0.8f, 2.6f, 0.4f).setEasing(Easing.SINE_IN_OUT, Easing.SINE_IN_OUT).build())
                        .setScaleData(GenericParticleData.create(0.2f, 0.4f, 0.2f).setEasing(Easing.SINE_IN_OUT, Easing.SINE_IN_OUT).build())
                        .setBehavior(SparkParticleBehavior.sparkBehavior().setForcedDirection(direction).setLengthCenter(1f))
                        .setRandomOffset(0.1f)
                        .setLifetime(15)
                        .setLifeDelay(lifeDelay)
                        .enableNoClip()
                        .addRenderActor(behavior)
                        .spawn(level, particlePosition.x, particlePosition.y, particlePosition.z);


                SpiritBasedParticleBuilder.createSpirit(MalumParticles.GIANT_GLOWING_STAR)
                        .setSpirit(cyclingSpiritType)
                        .setTransparencyData(GenericParticleData.create(0.2f, 0.3f, 0).setEasing(Easing.SINE_IN_OUT, Easing.SINE_IN_OUT).build())
                        .setScaleData(GenericParticleData.create(0.3f, 0.6f, 0.2f).setEasing(Easing.SINE_IN_OUT, Easing.SINE_IN_OUT).build())
                        .setLifetime(15)
                        .setLifeDelay(lifeDelay)
                        .enableNoClip()
                        .spawn(level, particlePosition.x, particlePosition.y, particlePosition.z);
                SpiritBasedParticleBuilder.createSpirit(MalumParticles.STAR)
                        .setSpirit(cyclingSpiritType)
                        .setTransparencyData(GenericParticleData.create(0.15f, 0.5f, 0).setEasing(Easing.SINE_IN_OUT, Easing.SINE_IN_OUT).build())
                        .setScaleData(GenericParticleData.create(0.05f, 0.2f, 0.1f).setEasing(Easing.SINE_IN_OUT, Easing.SINE_IN_OUT).build())
                        .setLifetime(15)
                        .setLifeDelay(lifeDelay)
                        .enableNoClip()
                        .spawn(level, particlePosition.x, particlePosition.y, particlePosition.z);
            }

            long gameTime = level.getGameTime();
            float time = 16;
            for (int i = 0; i < 6; i++) {
                var offsetTargetPosition = VecHelper.rotatingRadialOffset(targetPos, 1.1f, i, 6, gameTime, time);
                double timeOffset = (Math.cos(((gameTime + i * 480) % time) / time) * 0.25f) - 0.25f;
                offsetTargetPosition = offsetTargetPosition.add(0, timeOffset, 0);
                 for (int j = 0; j < 2; j++) {
                    var lightSpecs = spiritLightSpecs(level, offsetTargetPosition, colorData.getColor());
                    float velocity = -Easing.SINE_IN_OUT.asWeighedRandom(random, 0.05f, 0.1f);
                    var motion = offsetTargetPosition.subtract(targetPos).normalize().scale(velocity);
                    lightSpecs.getBuilder()
                            .multiplyLifetime(0.8f)
                            .setMotion(motion)
                            .setTransparencyData(GenericParticleData.create(0.2f, 0.8f, 0f).build())
                            .modifyScaleData(d -> d.multiplyValue(Easing.SINE_IN_OUT.asWeighedRandom(random, 1f, 2f)));
                    lightSpecs.getBloomBuilder()
                            .multiplyLifetime(0.6f)
                            .setMotion(motion)
                            .setTransparencyData(GenericParticleData.create(0.05f, 0.35f, 0f).build())
                            .modifyScaleData(d -> d.multiplyValue(Easing.SINE_IN_OUT.asWeighedRandom(random, 0.5f, 1f)));
                    lightSpecs.spawnParticles();
                }
            }
        }
    }

@Override
	public void tick() {
		super.tick();

		this.yaw += 36.0F;
		this.scale += (float)(Math.max(30 - this.age, 0)) / 140.0F;

		if (this.caster != null && this.caster.getStunShield() <= 0.0F) {
			this.remove();
		}

		for (int x = -1; x <= 1; x+=2) {
			for (int z = -1; z <= 1; z += 2) {
				Vec3 rand = new Vec3(Math.random() * x, Math.random(), Math.random() * z).normalize().scale(10.0D);
				this.level.addParticle(EpicFightParticles.DUST_CONTRACTIVE.get(), this.x + rand.x, this.y + rand.y - 1.0D, this.z + rand.z, -rand.x, -rand.y, -rand.z);
			}
		}
	}

public LaserParticle(ClientLevel level, double x, double y, double z, double toX, double toY, double toZ) {
		super(level, x, y, z, 0, 0, 0, Meshes.LASER);
		this.lifetime = 5;

		Vec3 direction = new Vec3(toX - x, toY - y, toZ - z);
		Vec3 start = new Vec3(x, y, z);
		Vec3 destination = start.add(direction.normalize().scale(200.0D));
		BlockHitResult hitResult = level.clip(new ClipContext(start, destination, ClipContext.Block.COLLIDER, ClipContext.Fluid.NONE, CollisionContext.empty()));
		double xLength = hitResult.getLocation().x - x;
		double yLength = hitResult.getLocation().y - y;
		double zLength = hitResult.getLocation().z - z;
		double horizontalDistance = (float)Math.sqrt(xLength * xLength + zLength * zLength);
		this.length = (float)Math.sqrt(xLength * xLength + yLength * yLength + zLength * zLength);
		this.yRot = (float)(Math.atan2(zLength, xLength) * (180D / Math.PI)) + 90.0F + 180.0F;
		this.xRot = (float)(Math.atan2(yLength, horizontalDistance) * (180D / Math.PI));
		int smokeCount = (int)this.length * 4;

		for (int i = 0; i < smokeCount; i++) {
			level.addParticle(ParticleTypes.SMOKE, x + xLength / smokeCount * i, y + yLength / smokeCount * i, z + zLength / smokeCount * i, 0, 0, 0);
		}

		this.setBoundingBox(new AABB(x, y, z, toX, toY, toZ));
	}

public static void altarBlessTarget(Level level, NetworkedParticleEffectPositionData positionData, MalumNetworkedParticleEffectColorData colorData, LivingEntity target) {
        var random = level.random;
        var position = positionData.getAsVector();

        Function<Vec3, Consumer<LodestoneWorldParticle>> behavior = initialOffset -> p -> {
            var targetPosition = target.getPosition(p.partialTicksCache);
            p.setParticlePosition(targetPosition.add(initialOffset).add(p.getInterpolatedTravelledDistance()));
        };
        var offset = behavior.apply(position.subtract(target.position()));
        for (int i = 0; i < 5; i++) {
            int lifeDelay = i * 2;
            float upwardsMotion = 0.01f * i;
            float scale = 2f + i * 0.25f;
            cultistSigil(level, colorData)
                    .setSpinData(SpinParticleData.createRandomDirection(random, 0.3f, 0).setEasing(Easing.EXPO_OUT).build())
                    .modifyScaleData(d -> d.multiplyValue(scale))
                    .setBehavior(DirectionalParticleBehavior.directional(new Vec3(0, 1, 0)))
                    .setFriction(0.9f)
                    .addRenderActor(offset)
                    .addMotion(0, upwardsMotion, 0f)
                    .setLifetime(15)
                    .setLifeDelay(lifeDelay)
                    .spawn(level, position);
        }
        long gameTime = level.getGameTime();
        float time = 16;
        for (int i = 0; i < 8; i++) {
            var offsetPosition = VecHelper.rotatingRadialOffset(position, 0.9f, i, 8, gameTime, time);
            offsetPosition = offsetPosition.add(0, (Math.cos(((gameTime + i * 480) % time) / time) * 0.25f) + 0.5f, 0);
            offset = behavior.apply(offsetPosition.subtract(position));
            float upwardsVelocity = 0.2f;
            for (int j = 0; j < 3; j++) {
                var lightSpecs = SparkParticleEffects.spiritMotionSparks(level, offsetPosition, colorData.getColor(), new WorldParticleOptions(MalumParticles.MOTION_LINES));
                float velocity = Easing.SINE_IN_OUT.asWeighedRandom(random, 0.05f, 0.1f);
                var motion = offsetPosition.subtract(position).normalize().scale(velocity);
                int lifeDelay = j * 3;
                lightSpecs.getBuilder()
                        .setRenderType(LodestoneWorldParticleRenderType.LUMITRANSPARENT)
                        .addRenderActor(offset)
                        .multiplyLifetime(1.25f)
                        .setMotion(motion)
                        .addMotion(0, upwardsVelocity, 0)
                        .setLifeDelay(lifeDelay)
                        .setLengthData(GenericParticleData.create(2f, 0.5f).setEasing(Easing.EXPO_OUT).build())
                        .setTransparencyData(GenericParticleData.create(0.6f, 0.8f, 0f).build())
                        .modifyScaleData(d -> d.multiplyValue(Easing.SINE_IN_OUT.asWeighedRandom(random, 3f, 4f)));
                lightSpecs.getBloomBuilder()
                        .setRenderType(LodestoneWorldParticleRenderType.LUMITRANSPARENT)
                        .addRenderActor(offset)
                        .multiplyLifetime(0.75f)
                        .setMotion(motion)
                        .addMotion(0, upwardsVelocity, 0)
                        .setLifeDelay(lifeDelay)
                        .setScaleData(GenericParticleData.create(1f, 0.25f).setEasing(Easing.EXPO_OUT).build())
                        .setTransparencyData(GenericParticleData.create(0.05f, 0.35f, 0f).build());
                lightSpecs.spawnParticles();
            }
        }
    }

