@Override
	public void renderParticle(BufferBuilder buffer, Entity entityIn, float partialTicks, float rotationX,
			float rotationZ, float rotationYZ, float rotationXY, float rotationXZ) {
		float rx = (float)(this.prevPosX + (this.posX - this.prevPosX) * (double)partialTicks - interpPosX);
		float ry = (float)(this.prevPosY + (this.posY - this.prevPosY) * (double)partialTicks - interpPosY);
		float rz = (float)(this.prevPosZ + (this.posZ - this.prevPosZ) * (double)partialTicks - interpPosZ);

		float renderScale = 0.1F * this.particleScale;

		int i = this.getBrightnessForRender(partialTicks);
		int j = i >> 16 & 65535;
		int k = i & 65535;

		float texUOffset = this.prevTexUOffset + (this.texUOffset - this.prevTexUOffset) * partialTicks;

		buildBeam(rx, ry, rz, this.end, renderScale, texUOffset, this.texUScale, rotationX, rotationZ, rotationYZ, rotationXY, rotationXZ,
				(vx, vy, vz, u, v) -> {
					buffer.pos(vx, vy, vz).tex(u, v).color(this.particleRed, this.particleGreen, this.particleBlue, this.particleAlpha).lightmap(j, k).endVertex();
				});
	}

public static void buildBeam(double rx, double ry, double rz, Vec3d end, float scale, float texUOffset, float texUScale,
			float rotationX, float rotationZ, float rotationYZ, float rotationXY, float rotationXZ, BeamVertexConsumer consumer) {
		double len = end.length();

		Vec3d v1 = new Vec3d((double)(-rotationX - rotationXY), (double)(-rotationZ), (double)(-rotationYZ - rotationXZ));
		Vec3d v2 = new Vec3d((double)(-rotationX + rotationXY), (double)(rotationZ), (double)(-rotationYZ + rotationXZ));

		Vec3d facing = v1.crossProduct(v2);

		Vec3d perpendicularDir = end.crossProduct(facing).normalize();

		if(perpendicularDir.length() < 1.0E-4D) {
			//Special case where facing and particle direction perfectly match.
			//Instead of using the crossproduct we can just directly use the v1 and v2 vectors
			//to get the correct result
			facing = v2.subtract(v1).normalize();
			perpendicularDir = end.crossProduct(facing).normalize();
		}

		Vec3d perpendicularDir2 = perpendicularDir.crossProduct(end).normalize();

		Vec3d[] offsets = new Vec3d[] { perpendicularDir.scale(scale), perpendicularDir.scale(-scale) };
		Vec3d[] offsets2 = new Vec3d[] { perpendicularDir2.scale(scale), perpendicularDir2.scale(-scale) };

		double x1 = rx;
		double y1 = ry;
		double z1 = rz;

		double x2 = rx + end.x;
		double y2 = ry + end.y;
		double z2 = rz + end.z;

		//br
		consumer.emit((double)x2 + offsets[0].x, (double)y2 + offsets[0].y, (double)z2 + offsets[0].z, texUOffset + len / (0.2 * texUScale), 0);
		//tr                                                                                    
		consumer.emit((double)x2 + offsets[1].x, (double)y2 + offsets[1].y, (double)z2 + offsets[1].z, texUOffset + len / (0.2 * texUScale), 1);
		//tl                                                                                    
		consumer.emit((double)x1 + offsets[1].x, (double)y1 + offsets[1].y, (double)z1 + offsets[1].z, texUOffset, 1);
		//bl                                                                                    
		consumer.emit((double)x1 + offsets[0].x, (double)y1 + offsets[0].y, (double)z1 + offsets[0].z, texUOffset, 0);

		//br
		consumer.emit((double)x2 + offsets2[0].x, (double)y2 + offsets2[0].y, (double)z2 + offsets2[0].z, texUOffset + len / (0.2 * texUScale), 0);
		//tr                                                                                    
		consumer.emit((double)x2 + offsets2[1].x, (double)y2 + offsets2[1].y, (double)z2 + offsets2[1].z, texUOffset + len / (0.2 * texUScale), 1);
		//tl                                                                                    
		consumer.emit((double)x1 + offsets2[1].x, (double)y1 + offsets2[1].y, (double)z1 + offsets2[1].z, texUOffset, 1);
		//bl                                                                                    
		consumer.emit((double)x1 + offsets2[0].x, (double)y1 + offsets2[0].y, (double)z1 + offsets2[0].z, texUOffset, 0);
	}

@Override
	public void renderParticle(BufferBuilder buffer, Entity entityIn, float partialTicks, float rotationX, float rotationZ, float rotationYZ, float rotationXY, float rotationXZ) {
		float rx = (float)(this.prevPosX + (this.posX - this.prevPosX) * (double)partialTicks - interpPosX);
		float ry = (float)(this.prevPosY + (this.posY - this.prevPosY) * (double)partialTicks - interpPosY);
		float rz = (float)(this.prevPosZ + (this.posZ - this.prevPosZ) * (double)partialTicks - interpPosZ);

		int light = this.getBrightnessForRender(partialTicks);
		int lightmapX = light >> 16 & 65535;
		int lightmapY = light & 65535;

		float scale = ((MathHelper.sin((this.particleAge + partialTicks) * 0.8f) + 1) * 0.5f * 0.5f + 0.5f) * this.baseSize * (1 - (this.particleAge - 1 + partialTicks) / this.particleMaxAge);

		for(Arc arc : this.arcs) {

			ParticleBeam.buildBeam(rx + arc.from.x, ry + arc.from.y, rz + arc.from.z, arc.dir, scale * arc.size, 0, 0, rotationX, rotationZ, rotationYZ, rotationXY, rotationXZ, (x, y, z, u, v) -> {
				buffer.pos(x, y, z).tex(u, v).color(this.particleRed, this.particleGreen, this.particleBlue, this.particleAlpha).lightmap(lightmapX, lightmapY).endVertex();
			});

		}

		if(this.lighting && ShaderHelper.INSTANCE.isWorldShaderActive()) {
			double distFromCam = entityIn.getDistance(this.target.x, this.target.y, this.target.z);
			if(distFromCam < 40) {
	        	ShaderHelper.INSTANCE.require();

	        	float strength = (1 - this.particleAge / (float)this.particleMaxAge) * this.particleAlpha * 50.0f;

	            ShaderHelper.INSTANCE.getWorldShader().addLight(new LightSource(this.target.x, this.target.y, this.target.z,
	                    1.0f + 5.0f * this.baseSize, this.particleRed * strength, this.particleGreen * strength, this.particleBlue * strength));
			}
        }
	}

@Override
	public void renderParticle(BufferBuilder buffer, Entity entityIn, float partialTicks, float rotationX,
			float rotationZ, float rotationYZ, float rotationXY, float rotationXZ) {
		if(this.particleRed > 1) {
			this.particleRed /= 255.0f;
		}

		if(this.particleGreen > 1) {
			this.particleGreen /= 255.0f;
		}

		if(this.particleBlue > 1) {
			this.particleBlue /= 255.0f;
		}

		if(this.particleAge > this.particleMaxAge - 10) {
			this.particleAlpha = (this.particleMaxAge - this.particleAge) / 10.0F * this.initAlpha;
		} else if(this.particleAge < 10) {
			this.particleAlpha = this.particleAge / 10.0F * this.initAlpha;
		} else {
			this.particleAlpha = this.initAlpha;
		}

		if(ShaderHelper.INSTANCE.isWorldShaderActive()) {
			double distFromCam = entityIn.getDistance(this.posX, this.posY, this.posZ);
			if(distFromCam < 8) {
	        	ShaderHelper.INSTANCE.require();

	        	float strength = 1.0f * Math.min(1, (2.0f - (float)(distFromCam - 6.0f)) / 2.0f) * this.particleAlpha * 3.5f;

	        	double rx = this.prevPosX + (this.posX - this.prevPosX) * partialTicks;
				double ry = this.prevPosY + (this.posY - this.prevPosY) * partialTicks;
				double rz = this.prevPosZ + (this.posZ - this.prevPosZ) * partialTicks;
	            ShaderHelper.INSTANCE.getWorldShader().addLight(new LightSource(rx, ry, rz,
	                    2.6f, this.particleRed * strength, this.particleGreen * strength, this.particleBlue * strength));
			}
        }

		super.renderParticle(buffer, entityIn, partialTicks, rotationX, rotationZ, rotationYZ, rotationXY, rotationXZ);
	}

@Override
    public void render(EntitySolarBeam solarBeam, float entityYaw, float delta, PoseStack matrixStackIn, MultiBufferSource bufferIn, int packedLightIn) {
        clearerView = solarBeam.caster instanceof Player && Minecraft.getInstance().player == solarBeam.caster && Minecraft.getInstance().options.getCameraType() == CameraType.FIRST_PERSON;

        double collidePosX = solarBeam.prevCollidePosX + (solarBeam.collidePosX - solarBeam.prevCollidePosX) * delta;
        double collidePosY = solarBeam.prevCollidePosY + (solarBeam.collidePosY - solarBeam.prevCollidePosY) * delta;
        double collidePosZ = solarBeam.prevCollidePosZ + (solarBeam.collidePosZ - solarBeam.prevCollidePosZ) * delta;
        double posX = solarBeam.xo + (solarBeam.getX() - solarBeam.xo) * delta;
        double posY = solarBeam.yo + (solarBeam.getY() - solarBeam.yo) * delta;
        double posZ = solarBeam.zo + (solarBeam.getZ() - solarBeam.zo) * delta;
        float yaw = solarBeam.prevYaw + (solarBeam.renderYaw - solarBeam.prevYaw) * delta;
        float pitch = solarBeam.prevPitch + (solarBeam.renderPitch - solarBeam.prevPitch) * delta;

        float length = (float) Math.sqrt(Math.pow(collidePosX - posX, 2) + Math.pow(collidePosY - posY, 2) + Math.pow(collidePosZ - posZ, 2));
        int frame = Mth.floor((solarBeam.appear.getTimer() - 1 + delta) * 2);
        if (frame < 0) {
            frame = 6;
        }
        VertexConsumer ivertexbuilder = bufferIn.getBuffer(MMRenderType.getGlowingEffect(getTextureLocation(solarBeam)));

        renderStart(frame, matrixStackIn, ivertexbuilder, packedLightIn);
        renderBeam(length, 180f / (float) Math.PI * yaw, 180f / (float) Math.PI * pitch, frame, matrixStackIn, ivertexbuilder, packedLightIn);

        matrixStackIn.pushPose();
        matrixStackIn.translate(collidePosX - posX, collidePosY - posY, collidePosZ - posZ);
        renderEnd(frame, solarBeam.blockSide, matrixStackIn, ivertexbuilder, packedLightIn);
        matrixStackIn.popPose();
    }

private void renderEnd(int frame, Direction side, PoseStack matrixStackIn, VertexConsumer builder, int packedLightIn) {
        matrixStackIn.pushPose();
        Quaternionf quat = this.entityRenderDispatcher.cameraOrientation();
        matrixStackIn.mulPose(quat);
        renderFlatQuad(frame, matrixStackIn, builder, packedLightIn);
        matrixStackIn.popPose();
        if (side == null) {
            return;
        }
        matrixStackIn.pushPose();
        Quaternionf sideQuat = side.getRotation();
        sideQuat.mul(MathUtils.quatFromRotationXYZ(90, 0, 0, true));
        matrixStackIn.mulPose(sideQuat);
        matrixStackIn.translate(0, 0, -0.01f);
        renderFlatQuad(frame, matrixStackIn, builder, packedLightIn);
        matrixStackIn.popPose();
    }

private void renderBeam(float length, float yaw, float pitch, int frame,  PoseStack matrixStackIn, VertexConsumer builder, int packedLightIn) {
        matrixStackIn.pushPose();
        matrixStackIn.mulPose(MathUtils.quatFromRotationXYZ(90, 0, 0, true));
        matrixStackIn.mulPose(MathUtils.quatFromRotationXYZ(0, 0, yaw - 90f, true));
        matrixStackIn.mulPose(MathUtils.quatFromRotationXYZ(-pitch, 0, 0, true));
        matrixStackIn.pushPose();
        if (!clearerView) {
            matrixStackIn.mulPose(MathUtils.quatFromRotationXYZ(0, Minecraft.getInstance().gameRenderer.getMainCamera().getXRot() + 90, 0, true));
        }
        drawBeam(length, frame, matrixStackIn, builder, packedLightIn);
        matrixStackIn.popPose();

        if (!clearerView) {
            matrixStackIn.pushPose();
            matrixStackIn.mulPose(MathUtils.quatFromRotationXYZ(0, -Minecraft.getInstance().gameRenderer.getMainCamera().getXRot() - 90, 0, true));
            drawBeam(length, frame, matrixStackIn, builder, packedLightIn);
            matrixStackIn.popPose();
        }
        matrixStackIn.popPose();
    }

