private static void renderShieldingLine(Purpoid purpoid, float partialTicks, PoseStack stack, MultiBufferSource bufferSource, Vec3 mommyPos, int stunTimer) {
		stack.pushPose();
		double interpolatedPurpoidX = Mth.lerp(partialTicks, purpoid.xo, purpoid.getX());
		double interpolatedPurpoidY = Mth.lerp(partialTicks, purpoid.yo, purpoid.getY()) + 0.25F;
		double interpolatedPurpoidZ = Mth.lerp(partialTicks, purpoid.zo, purpoid.getZ());
		stack.translate(0.0F, 0.25F, 0.0F);
		float xDifference = (float) (mommyPos.x - interpolatedPurpoidX);
		float yDifference = (float) (mommyPos.y + 1.0F - interpolatedPurpoidY);
		float zDifference = (float) (mommyPos.z - interpolatedPurpoidZ);
		VertexConsumer vertexconsumer = bufferSource.getBuffer(EERenderTypes.PURPAZOID_SHIELDING_LINE);
		Matrix4f matrix4f = stack.last().pose();
		float width = 0.1F;
		float widthProportionalToDistance = (float) Mth.fastInvSqrt(xDifference * xDifference + zDifference * zDifference) * width / 2.0F;
		float zGap = zDifference * widthProportionalToDistance;
		float xGap = xDifference * widthProportionalToDistance;

		float stunTimerHalfCycles = Math.max(stunTimer - partialTicks, 0.0F) / 20.0F;
		float alpha = 0.1F + 0.4F * (1.0F - 2.0F * Mth.abs(stunTimerHalfCycles - Mth.floor(stunTimerHalfCycles + 0.5F)));

		float baseR = 0.643F;
		float baseG = 0.482F;
		float baseB = 0.918F;
		if (purpoid.hurtTime > 0 || purpoid.deathTime > 0) {
			baseR = baseR * 0.5F + 0.5F;
			baseG *= 0.5F;
			baseB *= 0.5F;
		}

		float waveOffset = Mth.PI * (purpoid.tickCount + partialTicks) / 20.0F;
		for (int i = 0; i <= 48; ++i) {
			addShieldingLineVertexPair(vertexconsumer, matrix4f, alpha, waveOffset, baseR, baseG, baseB, xDifference, yDifference, zDifference, width, width, zGap, xGap, i, false);
		}

		for (int i = 48; i >= 0; --i) {
			addShieldingLineVertexPair(vertexconsumer, matrix4f, alpha, waveOffset, baseR, baseG, baseB, xDifference, yDifference, zDifference, width, 0.0F, zGap, xGap, i, true);
		}

		stack.popPose();
	}

@Override
	public void render(PoseStack stack, MultiBufferSource bufferIn, int packedLightIn, Purpoid purpoid, float limbSwing, float limbSwingAmount, float partialTicks, float ageInTicks, float netHeadYaw, float headPitch) {
		if (!purpoid.isBaby() || purpoid.getIDOfShieldedMommy() < 0) return;
		PurpoidModel model = this.purpazoidModel;
		model.setupAnim(purpoid, limbSwing, limbSwingAmount, ageInTicks, netHeadYaw, headPitch);
		PurpoidGelModel gelModel = this.gelModel;
		gelModel.parentToHead(model.head);
		gelModel.setupAnim(purpoid, limbSwing, limbSwingAmount, ageInTicks, netHeadYaw, headPitch);
		stack.pushPose();
		stack.translate(0.0F, 0.8125F, 0.0F);
		float inAndOut = 0.05F * Mth.abs(Mth.sin(0.15707963267F * ageInTicks));
		float scale = 0.5F + inAndOut;
		stack.scale(scale, scale, scale);
		float alpha = 0.15F + inAndOut;
		VertexConsumer nonEmissiveBuffer = bufferIn.getBuffer(RenderType.entityTranslucent(PurpoidRenderer.getTexture(2)));
		model.renderToBuffer(stack, nonEmissiveBuffer, 240, OverlayTexture.pack(0, 10), 1.0F, 1.0F, 1.0F, alpha);
		gelModel.renderToBuffer(stack, nonEmissiveBuffer, 240, OverlayTexture.pack(0, 10), 1.0F, 1.0F, 1.0F, alpha);
		gelModel.renderToBuffer(stack, bufferIn.getBuffer(RenderType.entityTranslucent(PurpoidEmissiveLayer.TEXTURES[2])), 240, OverlayTexture.pack(0, 10), 1.0F, 1.0F, 1.0F, alpha);
		stack.popPose();
	}

public static void renderBeaconBeam(
        PoseStack poseStack, SubmitNodeCollector collector, Identifier beamLocation, Identifier glowLocation, float partialTick, float textureScale,
        long gameTime, float yOffset, float height, int colorBot, int colorTop, float beamRadius, float glowRadius) {

        if (height < 0) {
            return;
        }

        final float maxY = yOffset + height;
        poseStack.pushPose();
        poseStack.translate(0.5, 0.0, 0.5);
        float f = Math.floorMod(gameTime, 40) + partialTick;
        float f1 = height < 0 ? f : -f;
        float f2 = Mth.frac(f1 * 0.2F - Mth.floor(f1 * 0.1F));
        poseStack.pushPose();
        poseStack.mulPose(Axis.YP.rotationDegrees(f * 2.25F - 45.0F));
        final float f6 = -beamRadius;
        final float f9 = -beamRadius;
        final float f12 = -1.0F + f2;
        final float f13 = height * textureScale * (0.5F / beamRadius) + f12;
        collector.submitCustomGeometry(poseStack, ApothRenderTypes.affixBeam(beamLocation, true), (pose, buffer) -> renderPart(
            pose, buffer, colorBot, colorTop, yOffset, maxY,
            0.0F, beamRadius, beamRadius, 0.0F, f6, 0.0F, 0.0F, f9,
            0.0F, 1.0F, f13, f12));
        poseStack.popPose();
        final float g3 = -glowRadius;
        final float g4 = -glowRadius;
        final float g5 = -glowRadius;
        final float g6 = -glowRadius;
        final float g12 = -1.0F + f2;
        final float g13 = height * textureScale + g12;
        final int glowBot = ARGB.alpha(colorBot) / 2 << 24 | colorBot & 0x00FFFFFF;
        final int glowTop = ARGB.alpha(colorTop) / 2 << 24 | colorTop & 0x00FFFFFF;
        collector.submitCustomGeometry(poseStack, ApothRenderTypes.affixBeam(glowLocation, true), (pose, buffer) -> renderPart(
            pose, buffer, glowBot, glowTop, yOffset, maxY,
            g3, g4, glowRadius, g5, g6, glowRadius, glowRadius, glowRadius,
            0.0F, 1.0F, g13, g12));
        poseStack.popPose();
    }

@Override
    public void renderByItem(ItemStack itemStack, ItemDisplayContext transformType, PoseStack stack, MultiBufferSource bufferIn, int combinedLightIn, int p_239207_6_) {
        if (transformType == ItemDisplayContext.FIRST_PERSON_RIGHT_HAND) {
            Player player = Minecraft.getInstance().player;
            Vec3 playerPos = player.position().add(0, player.getEyeHeight(), 0);
            Vec3 look = player.getLookAngle(); // or getLook(partialTicks)
            //The next 3 variables are directions on the screen relative to the players look direction. So right = to the right of the player, regardless of facing direction.
            Vec3 right = new Vec3(-look.z, 0, look.x).normalize();
            Vec3 forward = look;
            Vec3 down = right.cross(forward);

            //These are used to calculate where the particles are going. We want them going into the laser, so we move the destination right, down, and forward a bit.
            right = right.scale(0.2 - player.attackAnim);
            forward = forward.scale(0.45f);
            down = down.scale(-0.1 - player.attackAnim);
            Vec3 laserPos = playerPos.add(right);
            laserPos = laserPos.add(forward);
            laserPos = laserPos.add(down);
            int timeHeld = 72000 - Minecraft.getInstance().player.getUseItemRemainingTicks();
            DyeColor color1 = itemStack.getOrDefault(DataComponents.BASE_COLOR, DyeColor.PURPLE);
            if (timeHeld > 0 && timeHeld != 72000) {
                float scaleAge = (float) ParticleUtil.inRange(0.05, 0.1);
                if (player.level.random.nextInt(20) == 0) {
                    for (int i = 0; i < 1; i++) {
                        Vec3 particlePos = new Vec3(laserPos.x, laserPos.y, laserPos.z);
                        particlePos = particlePos.add(ParticleUtil.pointInSphere().scale(0.3f));
                        player.level.addParticle(ParticleLineData.createData(ParticleColor.fromInt(color1.getTextColor()), scaleAge, 5 + player.level.random.nextInt(20)),
                                particlePos.x(), particlePos.y(), particlePos.z(),
                                laserPos.x(), laserPos.y(), laserPos.z());
                    }
                }
            }
        }
        super.renderByItem(itemStack, transformType, stack, bufferIn, combinedLightIn, p_239207_6_);
    }

