public void renderSwordEnergy(EntitySwordEnergy energyBall, double x, double y, double z, float rotationYaw, float partialTickTime) {
		if(ShaderHelper.INSTANCE.isWorldShaderActive()) {
			ShaderHelper.INSTANCE.require();
			ShaderHelper.INSTANCE.getWorldShader().addLight(new LightSource(energyBall.posX, energyBall.posY + 0.5D, energyBall.posZ, 
					2f,
					5.0f / 255.0f * 13.0F, 
					40.0f / 255.0f * 13.0F, 
					60.0f / 255.0f * 13.0F));
		}

		float ticks = energyBall.ticksExisted + partialTickTime;
		GlStateManager.pushMatrix();
		GlStateManager.translate(x, y - 0.0625D - energyBall.pulseFloat, z);
		float f1 = ticks;
		bindTexture(FORCE_TEXTURE);
		GlStateManager.matrixMode(GL11.GL_TEXTURE);
		GlStateManager.loadIdentity();
		float f2 = f1 * 0.01F;
		float f3 = f1 * 0.01F;
		GlStateManager.translate(f2, f3, 0.0F);
		GlStateManager.matrixMode(GL11.GL_MODELVIEW);
		GlStateManager.enableBlend();
		float f4 = 0.5F;
		GlStateManager.color(f4, f4, f4, 1.0F);
		GlStateManager.disableLighting();
		GlStateManager.blendFunc(SourceFactor.ONE, DestFactor.ONE);
		GlStateManager.scale(1F + energyBall.pulseFloat, 1F + energyBall.pulseFloat, 1F + energyBall.pulseFloat);
		model.render(0.0625F);
		GlStateManager.matrixMode(GL11.GL_TEXTURE);
		GlStateManager.loadIdentity();
		GlStateManager.matrixMode(GL11.GL_MODELVIEW);
		GlStateManager.enableLighting();
		GlStateManager.popMatrix();

		double interpPos1 = energyBall.lastPos1 + (energyBall.pos1 - energyBall.lastPos1) * partialTickTime;
		renderItemInBlock(x - interpPos1, y + 0.725F, z - interpPos1, this.swordPiece1, ticks);
		double interpPos2 = energyBall.lastPos2 + (energyBall.pos2 - energyBall.lastPos2) * partialTickTime;
		renderItemInBlock(x + interpPos2, y + 0.725F, z - interpPos2, this.swordPiece2, ticks);
		double interpPos3 = energyBall.lastPos3 + (energyBall.pos3 - energyBall.lastPos3) * partialTickTime;
		renderItemInBlock(x + interpPos3, y + 0.725F, z + interpPos3, this.swordPiece3, ticks);
		double interpPos4 = energyBall.lastPos4 + (energyBall.pos4 - energyBall.lastPos4) * partialTickTime;
		renderItemInBlock(x - interpPos4, y + 0.725F, z + interpPos4, this.swordPiece4, ticks);


		bindTexture(FORCE_TEXTURE);
		GlStateManager.matrixMode(GL11.GL_TEXTURE);
		GlStateManager.loadIdentity();
		GlStateManager.translate(f2, 0, 0.0F);
		GlStateManager.matrixMode(GL11.GL_MODELVIEW);
		GlStateManager.enableBlend();
		GlStateManager.color(f4, f4, f4, 1.0F);
		GlStateManager.disableLighting();
		GlStateManager.blendFunc(SourceFactor.ONE, DestFactor.ONE);
		GlStateManager.enableTexture2D();
		GlStateManager.disableCull();
		renderBeam(new Vec3d(x, y + 0.85F, z), new Vec3d(x - interpPos1 - 0.1F, y + 0.9F, z - interpPos1 - 0.1F), 0.05F, 0.25F, true, true);
		GlStateManager.pushMatrix();
		GlStateManager.translate(x - interpPos1, y - 0.14F, z - interpPos1);
		if(energyBall.pos1 < 3.5F)
			model.render(0.0625F);
		GlStateManager.popMatrix();
		renderBeam(new Vec3d(x, y + 0.85F, z), new Vec3d(x + interpPos2 + 0.1F, y + 0.9F, z - interpPos2 - 0.1F), 0.05F, 0.25F, true, true);
		GlStateManager.pushMatrix();
		GlStateManager.translate(x + interpPos2, y - 0.14F, z - interpPos2);
		if(energyBall.pos2 < 3.5F)
			model.render(0.0625F);
		GlStateManager.popMatrix();
		renderBeam(new Vec3d(x, y + 0.85F, z), new Vec3d(x + interpPos3 + 0.1F, y + 0.9F, z + interpPos3 + 0.1F), 0.05F, 0.25F, true, true);
		GlStateManager.pushMatrix();
		GlStateManager.translate(x + interpPos3, y - 0.14F, z + interpPos3);
		if(energyBall.pos3 < 3.5F)
			model.render(0.0625F);
		GlStateManager.popMatrix();
		renderBeam(new Vec3d(x, y + 0.85F, z), new Vec3d(x - interpPos4 - 0.1F, y + 0.9F, z + interpPos4 + 0.1F), 0.05F, 0.25F, true, true);
		GlStateManager.pushMatrix();
		GlStateManager.translate(x - interpPos4, y - 0.14F, z + interpPos4);
		if(energyBall.pos4 < 3.5F)
			model.render(0.0625F);
		GlStateManager.popMatrix();
		GlStateManager.enableCull();
		GlStateManager.enableTexture2D();
		GlStateManager.matrixMode(GL11.GL_TEXTURE);
		GlStateManager.loadIdentity();
		GlStateManager.matrixMode(GL11.GL_MODELVIEW);
		GlStateManager.enableLighting();
		GlStateManager.blendFunc(SourceFactor.SRC_ALPHA, DestFactor.ONE_MINUS_SRC_ALPHA);
		GlStateManager.disableBlend();
	}

public static void renderBeam(Vec3d start, Vec3d end, float startWidth, float endWidth, boolean renderStartCap, boolean renderEndCap) {
		Vec3d diff = start.subtract(end);
		Vec3d dir = diff.normalize();
		Vec3d upVec = new Vec3d(0, 1, 0);
		Vec3d localSide = dir.crossProduct(upVec).normalize();
		Vec3d localUp = localSide.crossProduct(dir).normalize();

		Tessellator tessellator = Tessellator.getInstance();
		BufferBuilder vertexbuffer = tessellator.getBuffer();

		double maxVStart = diff.length() / 8.0D;
		double maxVEnd = diff.length() / 8.0D;
		double minVStart = 0.0D;
		double minVEnd = 0.0D;
		double maxU = diff.length() / 2.0D;

		vertexbuffer.begin(7, DefaultVertexFormats.POSITION_TEX);
		vertexbuffer.pos(start.x + (localSide.x + localUp.x) * startWidth, start.y + (localSide.y + localUp.y) * startWidth, start.z + (localSide.z + localUp.z) * startWidth).tex(0, minVStart).endVertex();
		vertexbuffer.pos(start.x + (localSide.x - localUp.x) * startWidth, start.y + (localSide.y - localUp.y) * startWidth, start.z + (localSide.z - localUp.z) * startWidth).tex(0, maxVStart).endVertex();
		vertexbuffer.pos(end.x + (localSide.x - localUp.x) * endWidth, end.y + (localSide.y - localUp.y) * endWidth, end.z + (localSide.z - localUp.z) * endWidth).tex(maxU, maxVEnd).endVertex();
		vertexbuffer.pos(end.x + (localSide.x + localUp.x) * endWidth, end.y + (localSide.y + localUp.y) * endWidth, end.z + (localSide.z + localUp.z) * endWidth).tex(maxU, minVEnd).endVertex();

		vertexbuffer.pos(end.x + (-localSide.x + localUp.x) * endWidth, end.y + (-localSide.y + localUp.y) * endWidth, end.z + (-localSide.z + localUp.z) * endWidth).tex(maxU, minVEnd).endVertex();
		vertexbuffer.pos(end.x + (-localSide.x - localUp.x) * endWidth, end.y + (-localSide.y - localUp.y) * endWidth, end.z + (-localSide.z - localUp.z) * endWidth).tex(maxU, maxVEnd).endVertex();
		vertexbuffer.pos(start.x + (-localSide.x - localUp.x) * startWidth, start.y + (-localSide.y - localUp.y) * startWidth, start.z + (-localSide.z - localUp.z) * startWidth).tex(0, maxVStart).endVertex();
		vertexbuffer.pos(start.x + (-localSide.x + localUp.x) * startWidth, start.y + (-localSide.y + localUp.y) * startWidth, start.z + (-localSide.z + localUp.z) * startWidth).tex(0, minVStart).endVertex();

		vertexbuffer.pos(end.x + (localUp.x + localSide.x) * endWidth, end.y + (localUp.y + localSide.y) * endWidth, end.z + (localUp.z + localSide.z) * endWidth).tex(maxU, minVEnd).endVertex();
		vertexbuffer.pos(end.x + (localUp.x - localSide.x) * endWidth, end.y + (localUp.y - localSide.y) * endWidth, end.z + (localUp.z - localSide.z) * endWidth).tex(maxU, maxVEnd).endVertex();
		vertexbuffer.pos(start.x + (localUp.x - localSide.x) * startWidth, start.y + (localUp.y - localSide.y) * startWidth, start.z + (localUp.z - localSide.z) * startWidth).tex(0, maxVStart).endVertex();
		vertexbuffer.pos(start.x + (localUp.x + localSide.x) * startWidth, start.y + (localUp.y + localSide.y) * startWidth, start.z + (localUp.z + localSide.z) * startWidth).tex(0, minVStart).endVertex();

		vertexbuffer.pos(start.x + (-localUp.x + localSide.x) * startWidth, start.y + (-localUp.y + localSide.y) * startWidth, start.z + (-localUp.z + localSide.z) * startWidth).tex(0, minVStart).endVertex();
		vertexbuffer.pos(start.x + (-localUp.x - localSide.x) * startWidth, start.y + (-localUp.y - localSide.y) * startWidth, start.z + (-localUp.z - localSide.z) * startWidth).tex(0, maxVStart).endVertex();
		vertexbuffer.pos(end.x + (-localUp.x - localSide.x) * endWidth, end.y + (-localUp.y - localSide.y) * endWidth, end.z + (-localUp.z - localSide.z) * endWidth).tex(maxU, maxVEnd).endVertex();
		vertexbuffer.pos(end.x + (-localUp.x + localSide.x) * endWidth, end.y + (-localUp.y + localSide.y) * endWidth, end.z + (-localUp.z + localSide.z) * endWidth).tex(maxU, minVEnd).endVertex();

		if(renderStartCap) {
			vertexbuffer.pos(start.x + (localUp.x - localSide.x) * startWidth, start.y + (localUp.y - localSide.y) * startWidth, start.z + (localUp.z - localSide.z) * startWidth).tex(0, 1).endVertex();
			vertexbuffer.pos(start.x + (-localUp.x - localSide.x) * startWidth, start.y + (-localUp.y - localSide.y) * startWidth, start.z + (-localUp.z - localSide.z) * startWidth).tex(1, 1).endVertex();
			vertexbuffer.pos(start.x + (-localUp.x + localSide.x) * startWidth, start.y + (-localUp.y + localSide.y) * startWidth, start.z + (-localUp.z + localSide.z) * startWidth).tex(1, 0).endVertex();
			vertexbuffer.pos(start.x + (localUp.x + localSide.x) * startWidth, start.y + (localUp.y + localSide.y) * startWidth, start.z + (localUp.z + localSide.z) * startWidth).tex(0, 0).endVertex();
		}

		if(renderEndCap) {
			vertexbuffer.pos(end.x + (localUp.x + localSide.x) * endWidth, end.y + (localUp.y + localSide.y) * endWidth, end.z + (localUp.z + localSide.z) * endWidth).tex(0, 0).endVertex();
			vertexbuffer.pos(end.x + (-localUp.x + localSide.x) * endWidth, end.y + (-localUp.y + localSide.y) * endWidth, end.z + (-localUp.z + localSide.z) * endWidth).tex(1, 0).endVertex();
			vertexbuffer.pos(end.x + (-localUp.x - localSide.x) * endWidth, end.y + (-localUp.y - localSide.y) * endWidth, end.z + (-localUp.z - localSide.z) * endWidth).tex(1, 1).endVertex();
			vertexbuffer.pos(end.x + (localUp.x - localSide.x) * endWidth, end.y + (localUp.y - localSide.y) * endWidth, end.z + (localUp.z - localSide.z) * endWidth).tex(0, 1).endVertex();
		}
		tessellator.draw();
	}

public static void render(Player player, float partialTick, PoseStack poseStack, MultiBufferSource.BufferSource buffer) {
        Entity entity = MiscCapHelper.getClientTarget(player);
        if (entity instanceof LivingEntity livingentity) {
            int count = player.getUseItemRemainingTicks();
            int castTime = player.getUseItem().getUseDuration() - count;
            float f = getAttackAnimationScale(castTime, partialTick);
            float f1 = castTime + partialTick;
            float f2 = f1 * 0.5F % 1.0F;
            poseStack.pushPose();
            Vec3 targetPos = getPosition(livingentity, livingentity.getBbHeight() * 0.5, partialTick);
            Vec3 playerPos = player.getEyePosition(partialTick);
            if (Minecraft.getInstance().level != null) {
                boolean mainHand = WandUtil.getSpellOnHand(player, InteractionHand.MAIN_HAND) instanceof PrismaBeamSpell;
                ItemStack wand = mainHand ? player.getMainHandItem() : player.getOffhandItem();
                float staffHeight = wand.getItem() instanceof IWand w ? w.getWandVisualHeight(Minecraft.getInstance().level, player, wand) : 0.8F;
                if (player == Minecraft.getInstance().player && Minecraft.getInstance().options.getCameraType() == CameraType.FIRST_PERSON) {
                    // first-person staff end position
                    int arm = (player.getMainArm() == HumanoidArm.RIGHT ? 1 : -1) * (mainHand ? 1 : -1);
                    double fovFactor = 960.0 / (double) Minecraft.getInstance().options.fov().get();
                    float horizontalFactor = 0.125F * staffHeight + 0.35F, verticalFactor = 1.5F * staffHeight - 0.45F;
                    Vec3 vec3 = Minecraft.getInstance().gameRenderer.getMainCamera().getNearPlane().getPointOnPlane(horizontalFactor * arm, verticalFactor).scale(fovFactor);
                    playerPos = player.getEyePosition(partialTick).add(vec3);
                } else {
                    // third person staff end position
                    Optional<Vec3> staffEndPos = ModelUtil.getThirdPersonPlayerHandPosition(
                            player,
                            Minecraft.getInstance().getEntityRenderDispatcher(),
                            Mth.lerp(partialTick, player.yBodyRotO, player.yBodyRot),
                            partialTick,
                            mainHand ? player.getMainArm() : player.getMainArm().getOpposite(),
                            new Vec3(0, 0.55, -staffHeight)
                    );
                    if (staffEndPos.isPresent()) {
                        playerPos = staffEndPos.get();
                    }
                }
            }
            Vec3 view = Minecraft.getInstance().gameRenderer.getMainCamera().getPosition();
            poseStack.translate(playerPos.x() - view.x(), playerPos.y() - view.y(), playerPos.z() - view.z());
            Vec3 diff = targetPos.subtract(playerPos);
            float f4 = (float) (diff.length() + 1.0D);
            diff = diff.normalize();
            float f5 = (float) Math.acos(diff.y);
            float f6 = (float) Math.atan2(diff.z, diff.x);
            poseStack.mulPose(Axis.YP.rotationDegrees((((float)Math.PI / 2F) - f6) * (180F / (float)Math.PI)));
            poseStack.mulPose(Axis.XP.rotationDegrees(f5 * (180F / (float)Math.PI)));
            float f7 = f1 * 0.05F * -1.5F;
            float f8 = f * f;
            int j = 64 + (int)(f8 * 191.0F);
            int k = 32 + (int)(f8 * 191.0F);
            int l = 128 - (int)(f8 * 64.0F);
            float f11 = Mth.cos(f7 + 2.3561945F) * 0.282F;
            float f12 = Mth.sin(f7 + 2.3561945F) * 0.282F;
            float f13 = Mth.cos(f7 + ((float)Math.PI / 4F)) * 0.282F;
            float f14 = Mth.sin(f7 + ((float)Math.PI / 4F)) * 0.282F;
            float f15 = Mth.cos(f7 + 3.926991F) * 0.282F;
            float f16 = Mth.sin(f7 + 3.926991F) * 0.282F;
            float f17 = Mth.cos(f7 + 5.4977875F) * 0.282F;
            float f18 = Mth.sin(f7 + 5.4977875F) * 0.282F;
            float f19 = Mth.cos(f7 + (float)Math.PI) * 0.2F;
            float f20 = Mth.sin(f7 + (float)Math.PI) * 0.2F;
            float f21 = Mth.cos(f7 + 0.0F) * 0.2F;
            float f22 = Mth.sin(f7 + 0.0F) * 0.2F;
            float f23 = Mth.cos(f7 + ((float)Math.PI / 2F)) * 0.2F;
            float f24 = Mth.sin(f7 + ((float)Math.PI / 2F)) * 0.2F;
            float f25 = Mth.cos(f7 + ((float)Math.PI * 1.5F)) * 0.2F;
            float f26 = Mth.sin(f7 + ((float)Math.PI * 1.5F)) * 0.2F;
            float f29 = -1.0F + f2;
            float f30 = f4 * 2.5F + f29;
            VertexConsumer vertexconsumer = buffer.getBuffer(BEAM_RENDER_TYPE);
            PoseStack.Pose posestack$pose = poseStack.last();
            Matrix4f matrix4f = posestack$pose.pose();
            Matrix3f matrix3f = posestack$pose.normal();
            vertex(vertexconsumer, matrix4f, matrix3f, f19, f4, f20, j, k, l, 0.4999F, f30);
            vertex(vertexconsumer, matrix4f, matrix3f, f19, 0.0F, f20, j, k, l, 0.4999F, f29);
            vertex(vertexconsumer, matrix4f, matrix3f, f21, 0.0F, f22, j, k, l, 0.0F, f29);
            vertex(vertexconsumer, matrix4f, matrix3f, f21, f4, f22, j, k, l, 0.0F, f30);
            vertex(vertexconsumer, matrix4f, matrix3f, f23, f4, f24, j, k, l, 0.4999F, f30);
            vertex(vertexconsumer, matrix4f, matrix3f, f23, 0.0F, f24, j, k, l, 0.4999F, f29);
            vertex(vertexconsumer, matrix4f, matrix3f, f25, 0.0F, f26, j, k, l, 0.0F, f29);
            vertex(vertexconsumer, matrix4f, matrix3f, f25, f4, f26, j, k, l, 0.0F, f30);
            float f31 = 0.0F;
            if (player.tickCount % 2 == 0) {
                f31 = 0.5F;
            }

            vertex(vertexconsumer, matrix4f, matrix3f, f11, f4, f12, j, k, l, 0.5F, f31 + 0.5F);
            vertex(vertexconsumer, matrix4f, matrix3f, f13, f4, f14, j, k, l, 1.0F, f31 + 0.5F);
            vertex(vertexconsumer, matrix4f, matrix3f, f17, f4, f18, j, k, l, 1.0F, f31);
            vertex(vertexconsumer, matrix4f, matrix3f, f15, f4, f16, j, k, l, 0.5F, f31);
            poseStack.popPose();
            buffer.endBatch();
        }
    }

private Pair<BoltQuads, QuadCache> createQuads(QuadCache cache, Vec3 startPos, Vec3 end, float size) {
        Vec3 diff = end.subtract(startPos);
        Vec3 rightAdd = diff.cross(new Vec3(0.5, 0.5, 0.5)).normalize().scale(size);
        Vec3 backAdd = diff.cross(rightAdd).normalize().scale(size), rightAddSplit = rightAdd.scale(0.5F);

        Vec3 start = cache != null ? cache.prevEnd : startPos;
        Vec3 startRight = cache != null ? cache.prevEndRight : start.add(rightAdd);
        Vec3 startBack = cache != null ? cache.prevEndBack : start.add(rightAddSplit).add(backAdd);
        Vec3 endRight = end.add(rightAdd), endBack = end.add(rightAddSplit).add(backAdd);

        BoltQuads quads = new BoltQuads();
        quads.addQuad(start, end, endRight, startRight);
        quads.addQuad(startRight, endRight, end, start);

        quads.addQuad(startRight, endRight, endBack, startBack);
        quads.addQuad(startBack, endBack, endRight, startRight);

        return Pair.of(quads, new QuadCache(end, endRight, endBack));
    }

@Override
	public void handlePerspective(Key key, LivingEntity holder, ItemDisplayContext cameraItemDisplayContext, PoseStack mat)
	{
		if(holder==null||!holder.isUsingItem())
			return;
		boolean leftHand = cameraItemDisplayContext==FIRST_PERSON_LEFT_HAND||cameraItemDisplayContext==THIRD_PERSON_LEFT_HAND;
		boolean rightHand = cameraItemDisplayContext==FIRST_PERSON_RIGHT_HAND||cameraItemDisplayContext==THIRD_PERSON_RIGHT_HAND;
		if(!leftHand&&!rightHand)
			return;
		boolean leftIsMain = holder.getMainArm()==HumanoidArm.LEFT;
		InteractionHand inHand = (leftIsMain==leftHand)?InteractionHand.MAIN_HAND: InteractionHand.OFF_HAND;
		if(holder.getUsedItemHand()!=inHand)
			return;

		if(cameraItemDisplayContext==FIRST_PERSON_RIGHT_HAND)
		{
			mat.mulPose(new Quaternionf().rotateXYZ(-.15F, 0, 0));
			mat.translate(-.25, .5, -.4375);
		}
		else if(cameraItemDisplayContext==THIRD_PERSON_RIGHT_HAND)
		{
			mat.mulPose(new Quaternionf().rotateXYZ(0.52359F, 0, 0));
			mat.mulPose(new Quaternionf().rotateXYZ(0, 0.78539F, 0));
			mat.translate(.40625, -.125, -.125);
		}
		if(cameraItemDisplayContext==FIRST_PERSON_LEFT_HAND)
		{
			mat.mulPose(new Quaternionf().rotateXYZ(.15F, 0, 0));
			mat.translate(-.25, .375, .4375);
		}
		else if(cameraItemDisplayContext==THIRD_PERSON_LEFT_HAND)
		{
			mat.mulPose(new Quaternionf().rotateX(-0.52359F).rotateY(-0.78539F));
			mat.translate(-.1875, .3125, .4375);
		}
	}

@Override
	public void render(Beam entity, float yaw, float tickDelta, PoseStack poseStack, MultiBufferSource vertices, int light) {
		LivingEntity caster = entity.getCaster();
		Vec3 cam = Minecraft.getInstance().gameRenderer.getMainCamera().getPosition();

		if(caster != null) {
			Vec3 startPos = caster.getPosition(tickDelta).add(0, caster.getEyeHeight(caster.getPose()) * 0.9f, 0);
			Vec3 endPos = entity.getBeamPos(tickDelta);
			Vector3d axis = new Vector3d(endPos.x() - startPos.x(), endPos.y() - startPos.y(), endPos.z() - startPos.z()).normalize();
			VertexConsumer vertex = vertices.getBuffer(LAYER);
			Color color = ArcanusHelper.getMagicColor(entity);
			float distance = entity.distanceTo(caster) / 2f;

			poseStack.pushPose();
			poseStack.translate(-entity.getX(), -entity.getY(), -entity.getZ());

			for(int i = 0; i < 2; i++) {
				Vector3d vec = new Vector3d(cam.x(), cam.y(), cam.z()).sub(startPos.x(), startPos.y(), startPos.z()).cross(axis).normalize().mul(0.2);
				vec.rotateAxis(Math.toRadians(i == 0 ? 45 : -45), axis.x, axis.y, axis.z);
				Vec3 vert1 = startPos.add(vec.x, vec.y, vec.z);
				Vec3 vert2 = startPos.subtract(vec.x, vec.y, vec.z);
				Vec3 vert3 = endPos.add(vec.x, vec.y, vec.z);
				Vec3 vert4 = endPos.subtract(vec.x, vec.y, vec.z);
				float beamProgress = entity.getBeamProgress(tickDelta) * 2f;

				if(i > 0)
					beamProgress *= -1f;

				float minU = 0;
				float minV = -beamProgress;
				float maxU = 1;
				float maxV = distance - beamProgress;

				if(i > 0) {
					minV = 1 - minV;
					maxV = 1 - maxV;
				}

				vertex(vertex, poseStack, vert4, color, maxU, minV);
				vertex(vertex, poseStack, vert3, color, minU, minV);
				vertex(vertex, poseStack, vert1, color, minU, maxV);
				vertex(vertex, poseStack, vert2, color, maxU, maxV);
			}

			poseStack.popPose();
		}
	}

@Override
	public void render(MagicRune entity, float yaw, float tickDelta, PoseStack poseStack, MultiBufferSource vertices, int light) {
		super.render(entity, yaw, tickDelta, poseStack, vertices, light);
		Color color = ArcanusHelper.getMagicColor(entity);
		float alpha = keyFrames[entity.tickCount % keyFrames.length] / 16f;
		float r = color.redF() * alpha;
		float g = color.greenF() * alpha;
		float b = color.blueF() * alpha;
		color = Color.fromFloatsRGB(r, g, b);

		poseStack.pushPose();
		poseStack.translate(0, Math.sin((entity.tickCount + tickDelta) * 0.125) * 0.05, 0);
		poseStack.mulPose(Axis.YP.rotationDegrees(entity.tickCount + tickDelta));
		model.renderToBuffer(poseStack, vertices.getBuffer(ArcanusClient.getMagicCircles(TEXTURE)), LightTexture.FULL_BRIGHT, OverlayTexture.NO_OVERLAY, color.asIntARGB());
		poseStack.popPose();
	}

@Override
	protected void draw(Tessellator tessellator, double length, float partialTicks){

		float scale = this.particleScale;

		BufferBuilder buffer = tessellator.getBuffer();

		GlStateManager.disableLighting();
		OpenGlHelper.setLightmapTextureCoords(OpenGlHelper.lightmapTexUnit, 240f, 240f);

		GlStateManager.pushMatrix();
		// Enables texture tiling (Also used for guardian beam, beacon beam and ender crystal beam, amongst others)
		GlStateManager.glTexParameteri(GL11.GL_TEXTURE_2D, GL11.GL_TEXTURE_WRAP_S, GL11.GL_REPEAT);
		GlStateManager.glTexParameteri(GL11.GL_TEXTURE_2D, GL11.GL_TEXTURE_WRAP_T, GL11.GL_REPEAT);

		GlStateManager.rotate(Minecraft.getMinecraft().player.ticksExisted + partialTicks, 0, 0, 1);

		Minecraft.getMinecraft().renderEngine.bindTexture(TEXTURE);

		buffer.begin(GL11.GL_QUADS, DefaultVertexFormats.POSITION_TEX_COLOR);

		float t = THICKNESS * scale;
		float v1 = 2 * (particleAge + partialTicks) / particleMaxAge;
		float v2 = v1 + (float)length * 2; // Multiply by 2 to make it squished like it is in vanilla

		buffer.pos(-t, 0, 0)   .tex(0,   v1)  .color(particleRed, particleGreen, particleBlue, 1).endVertex();
		buffer.pos( t, 0, 0)   .tex(0.5, v1)  .color(particleRed, particleGreen, particleBlue, 1).endVertex();
		buffer.pos( t, 0, length).tex(0.5, v2).color(particleRed, particleGreen, particleBlue, 1).endVertex();
		buffer.pos(-t, 0, length).tex(0,   v2).color(particleRed, particleGreen, particleBlue, 1).endVertex();

		buffer.pos(0, -t, 0)   .tex(0,   v1)  .color(particleRed, particleGreen, particleBlue, 1).endVertex();
		buffer.pos(0,  t, 0)   .tex(0.5, v1)  .color(particleRed, particleGreen, particleBlue, 1).endVertex();
		buffer.pos(0,  t, length).tex(0.5, v2).color(particleRed, particleGreen, particleBlue, 1).endVertex();
		buffer.pos(0, -t, length).tex(0,   v2).color(particleRed, particleGreen, particleBlue, 1).endVertex();

		tessellator.draw();

//		GlStateManager.glTexParameteri(GL11.GL_TEXTURE_2D, GL11.GL_TEXTURE_WRAP_S, GL11.GL_REPEAT);
//		GlStateManager.glTexParameteri(GL11.GL_TEXTURE_2D, GL11.GL_TEXTURE_WRAP_T, GL11.GL_REPEAT);

		GlStateManager.popMatrix();

		// Makes the rain go weird
		//GlStateManager.enableLighting();
	}

@SubscribeEvent
	public static void onRenderWorldLastEvent(RenderWorldLastEvent event){
		// Only render in first person
		if(Minecraft.getMinecraft().gameSettings.thirdPersonView == 0){

			EntityPlayer player = Minecraft.getMinecraft().player;

			if(WizardData.get(player).getVariable(Shield.SHIELD_KEY) != null && EntityUtils.isCasting(player, Spells.shield)){

				GlStateManager.pushMatrix();

				GlStateManager.disableCull();
				GlStateManager.enableBlend();
				GlStateManager.blendFunc(GL11.GL_ONE, GL11.GL_SRC_ALPHA);
				GlStateManager.shadeModel(GL11.GL_SMOOTH);
				GlStateManager.disableLighting();
				OpenGlHelper.setLightmapTextureCoords(OpenGlHelper.lightmapTexUnit, 240f, 240f);

				GlStateManager.translate(0, 1.4, 0);

				GlStateManager.rotate(-player.rotationYaw, 0, 1, 0);
				GlStateManager.rotate(player.rotationPitch, 1, 0, 0);

				GlStateManager.translate(0, 0, 1);

				GlStateManager.pushMatrix();

				// Changes the scale at which the texture is applied to the model. See LayerCreeper for a similar example,
				// but with translation instead of scaling.
				// You can do all sorts of fun stuff with this, just by applying transformations in the 2D texture space.
				GlStateManager.matrixMode(GL11.GL_TEXTURE); // Switch to the 2D texture space
				GlStateManager.loadIdentity();

				GlStateManager.translate(0.5, 0.5, 0);

				float s = 1 - ((player.ticksExisted + event.getPartialTicks()) % 5) / 5 * 0.52f;
				s = s*s;
				GlStateManager.scale(s, s, 1);

				GlStateManager.translate(-0.5, -0.5, 0);

				GlStateManager.matrixMode(GL11.GL_MODELVIEW); // Switch back to the 3D model space

				Tessellator tessellator = Tessellator.getInstance();

				Minecraft.getMinecraft().renderEngine.bindTexture(TEXTURE);

				render(tessellator);

				// Undo the texture scaling
				GlStateManager.matrixMode(GL11.GL_TEXTURE);
				GlStateManager.loadIdentity();
				GlStateManager.matrixMode(GL11.GL_MODELVIEW);

				GlStateManager.popMatrix();

				GlStateManager.enableLighting();

				GlStateManager.shadeModel(GL11.GL_FLAT);
				GlStateManager.enableCull();
				GlStateManager.disableBlend();
				// RenderHelper.enableStandardItemLighting();

				GlStateManager.popMatrix();
			}
		}
	}

private static void render(Tessellator tessellator){

		BufferBuilder buffer = tessellator.getBuffer();

		double widthOuter = 0.6d;
		double heightOuter = 0.7d;
		double widthInner = 0.3d;
		double heightInner = 0.4d;
		double depth = 0.2d;

		buffer.begin(GL11.GL_TRIANGLE_STRIP, DefaultVertexFormats.POSITION_TEX_COLOR);

		buffer.pos(-widthOuter, heightInner, -depth).tex(0, 0.2).color(0, 0, 0, 255).endVertex();
		buffer.pos(-widthInner, heightInner, 0).tex(0.2, 0.2).color(200, 200, 255, 255).endVertex();
		buffer.pos(-widthInner, heightOuter, -depth).tex(0.2, 0).color(0, 0, 0, 255).endVertex();
		buffer.pos(-widthInner, heightInner, 0).tex(0.2, 0.2).color(200, 200, 255, 255).endVertex();

		buffer.pos(widthInner, heightOuter, -depth).tex(0.8, 0).color(0, 0, 0, 255).endVertex();
		buffer.pos(widthInner, heightInner, 0).tex(0.8, 0.2).color(200, 200, 255, 255).endVertex();
		buffer.pos(widthOuter, heightInner, -depth).tex(1, 0.2).color(0, 0, 0, 255).endVertex();
		buffer.pos(widthInner, heightInner, 0).tex(0.8, 0.2).color(200, 200, 255, 255).endVertex();

		buffer.pos(widthOuter, -heightInner, -depth).tex(1, 0.8).color(0, 0, 0, 255).endVertex();
		buffer.pos(widthInner, -heightInner, 0).tex(0.8, 0.8).color(200, 200, 255, 255).endVertex();
		buffer.pos(widthInner, -heightOuter, -depth).tex(0.8, 1).color(0, 0, 0, 255).endVertex();
		buffer.pos(widthInner, -heightInner, 0).tex(0.8, 0.8).color(200, 200, 255, 255).endVertex();

		buffer.pos(-widthInner, -heightOuter, -depth).tex(0.2, 1).color(0, 0, 0, 255).endVertex();
		buffer.pos(-widthInner, -heightInner, 0).tex(0.2, 0.8).color(200, 200, 255, 255).endVertex();
		buffer.pos(-widthOuter, -heightInner, -depth).tex(0, 0.8).color(0, 0, 0, 255).endVertex();
		buffer.pos(-widthInner, -heightInner, 0).tex(0.2, 0.8).color(200, 200, 255, 255).endVertex();

		buffer.pos(-widthOuter, heightInner, -depth).tex(0, 0.2).color(0, 0, 0, 255).endVertex();
		buffer.pos(-widthInner, heightInner, 0).tex(0.2, 0.2).color(200, 200, 255, 255).endVertex();

		tessellator.draw();

		buffer.begin(GL11.GL_TRIANGLE_STRIP, DefaultVertexFormats.POSITION_TEX_COLOR);

		buffer.pos(-widthInner, heightInner, 0).tex(0.2, 0.2).color(200, 200, 255, 255).endVertex();
		buffer.pos(widthInner, heightInner, 0).tex(0.8, 0.2).color(200, 200, 255, 255).endVertex();
		buffer.pos(-widthInner, -heightInner, 0).tex(0.2, 0.8).color(200, 200, 255, 255).endVertex();
		buffer.pos(widthInner, -heightInner, 0).tex(0.8, 0.8).color(200, 200, 255, 255).endVertex();

		tessellator.draw();
	}

@Override
	public void doRender(EntityMagicConstruct entity, double x, double y, double z, float entityYaw, float partialTicks){

		// Makes the sigil invisible to enemies of the player that created it
		if(this.invisibleToEnemies){
			// Unfortunately we can't access the caster's allies if they're not online, it only works the other way round
			if(entity.getCaster() != Minecraft.getMinecraft().player && entity.getCaster() instanceof EntityPlayer
					&& !AllyDesignationSystem.isPlayerAlly((EntityPlayer)entity.getCaster(), Minecraft.getMinecraft().player)){
				return;
			}
		}

		GlStateManager.pushMatrix();
		GlStateManager.enableBlend();
		GlStateManager.disableLighting();
		OpenGlHelper.setLightmapTextureCoords(OpenGlHelper.lightmapTexUnit, 240, 240);
		GlStateManager.blendFunc(GL11.GL_SRC_ALPHA, GL11.GL_ONE_MINUS_SRC_ALPHA);

		float yOffset = 0;

		GlStateManager.translate((float)x, (float)y + yOffset, (float)z);

		this.bindTexture(texture);
		float f6 = 1.0F;
		float f7 = 0.5F;
		float f8 = 0.5F;

		GlStateManager.rotate(-90, 1, 0, 0);

		// Healing aura rotates slowly
		if(rotationSpeed != 0) GlStateManager.rotate(entity.ticksExisted * rotationSpeed, 0, 0, 1);

		float s = entity.width * DrawingUtils.smoothScaleFactor(entity.lifetime, entity.ticksExisted, partialTicks, 10, 10);
		GlStateManager.scale(s, s, s);

		Tessellator tessellator = Tessellator.getInstance();
		BufferBuilder buffer = tessellator.getBuffer();
		buffer.begin(GL11.GL_QUADS, DefaultVertexFormats.POSITION_TEX);

		buffer.pos(0.0F - f7, 0.0F - f8, 0.01).tex(0, 1).endVertex();
		buffer.pos(f6   - f7, 0.0F - f8, 0.01).tex(1, 1).endVertex();
		buffer.pos(f6   - f7, 1.0F - f8, 0.01).tex(1, 0).endVertex();
		buffer.pos(0.0F - f7, 1.0F - f8, 0.01).tex(0, 0).endVertex();

		tessellator.draw();

		GlStateManager.disableBlend();
		GlStateManager.enableLighting();
		GlStateManager.disableRescaleNormal();
		GlStateManager.popMatrix();
	}

@SubscribeEvent
    public static void renderBeams(RenderLevelStageEvent event) {
        if (event.getStage() == RenderLevelStageEvent.Stage.AFTER_TRANSLUCENT_BLOCKS) {
            Minecraft minecraft = Minecraft.getInstance();
            ClientLevel level = minecraft.level;
            if (level != null) {
                float partialTick = event.getPartialTick();
                Vec3 origin = event.getCamera().getPosition();
                Frustum frustum = event.getFrustum();
                MultiBufferSource.BufferSource bufferSource = minecraft.renderBuffers().bufferSource();
                CorruptedBeamRenderer.renderQueued(bufferSource);
                boolean drewAny = false;

                for (Entity entity : level.entitiesForRendering()) {
                    if (!(entity instanceof LivingEntity enchanted) || enchanted.isRemoved()) {
                        continue;
                    }
                    Entity enchanter = MiscCapHelper.getEnchanter(enchanted);
                    if (enchanter == null || enchanter.isRemoved()) {
                        continue;
                    }
                    Vec3 target = getTargetPos(enchanted, partialTick);
                    Vec3 source = getSourcePos(enchanter, partialTick);
                    if (!frustum.isVisible(beamBounds(source, target))) {
                        continue;
                    }
                    renderBeam(enchanted, source, target, origin, partialTick, event.getPoseStack(), bufferSource);
                    drewAny = true;
                }

                if (drewAny) {
                    bufferSource.endBatch(ModRenderType.enchantedBeam(BEAM_TEXTURE));
                }
            }
        }
    }

private static void renderRibbon(Vec3 origin, Vec3 from, Vec3 to, float arcPhase, float width, int argb, PoseStack poseStack, VertexConsumer consumer) {
        double distance = to.distanceTo(from);
        if (distance < 1.0E-4D) {
            return;
        }

        Vec3 camera = Minecraft.getInstance().gameRenderer.getMainCamera().getPosition();
        double arc = Mth.sin(arcPhase * Mth.PI) * ARC_AMOUNT * distance;
        Vec3 tangent0 = new Vec3(0.0D, arc, 0.0D);
        Vec3 tangent1 = new Vec3(0.0D, -0.125D * distance, 0.0D);

        Matrix4f pose = poseStack.last().pose();
        float half = width * 0.5F;
        Vec3 previous = from;

        for (int i = 0; i < SEGMENTS; ++i) {
            float t0 = (float) i / SEGMENTS;
            float t1 = (float) (i + 1) / SEGMENTS;
            Vec3 current = hermite(from, to, tangent0, tangent1, t1);

            Vec3 segment = current.subtract(previous);
            Vec3 toCamera = previous.subtract(camera);
            if (segment.lengthSqr() < 1.0E-8D || toCamera.lengthSqr() < 1.0E-8D) {
                previous = current;
                continue;
            }

            Vec3 side = segment.normalize().cross(toCamera.normalize());
            if (side.lengthSqr() < 1.0E-8D) {
                previous = current;
                continue;
            }
            side = side.normalize().scale(half);

            float v0 = t0 * (float) distance * UV_TILING;
            float v1 = t1 * (float) distance * UV_TILING;

            vertexAt(consumer, pose, previous.add(side).subtract(origin), 0.0F, v0, argb);
            vertexAt(consumer, pose, previous.subtract(side).subtract(origin), 1.0F, v0, argb);
            vertexAt(consumer, pose, current.subtract(side).subtract(origin), 1.0F, v1, argb);
            vertexAt(consumer, pose, current.add(side).subtract(origin), 0.0F, v1, argb);

            previous = current;
        }
    }

@Override
    public void render(VertexConsumer consumer, Camera camera, float partialTick) {
        Vec3 camPos = camera.getPosition();
        PoseStack stack = new PoseStack();
        stack.pushPose();
        stack.translate(-camPos.x, -camPos.y, -camPos.z);
        double currentX = Mth.lerp(partialTick, this.xo, this.x);
        double currentY = Mth.lerp(partialTick, this.yo, this.y);
        double currentZ = Mth.lerp(partialTick, this.zo, this.z);
        Vec3 sight = camPos.subtract(currentX, currentY, currentZ).scale(-1);
        Vec3 direction = toPos.subtract(fromPos);
        Vec3 start = new Vec3(currentX, currentY, currentZ).add(direction.scale(Easing.IN_OUT_QUAD.interpolate(Math.min(age + partialTick, lifetime) / lifetime, 0, 1)));
        Vec3 end = start.add(direction.scale(Easing.IN_OUT_QUAD.interpolate(Mth.abs(Math.min(age + partialTick, lifetime) / lifetime - 0.5f) * 2, 0.5F, 0)));
        if (end.distanceTo(fromPos) > direction.length()) {
            end = toPos;
        }
        Vec3 offset = end.subtract(start);
        Vec3 sideOffset = offset.cross(sight).normalize().scale(0.03);
        PoseStack.Pose pose = stack.last();
        float u0 = this.getU0();
        float u1 = Easing.IN_OUT_QUAD.interpolate(Mth.abs(Math.min(age + partialTick, lifetime) / lifetime - 0.5f) * 2, this.getU1(), this.getU0());
        float v0 = this.getV0();
        float v1 = this.getV1();
        vertex(consumer, pose, start.add(sideOffset), u0, v0, LightTexture.FULL_BRIGHT);
        vertex(consumer, pose, start.add(sideOffset.scale(-1)), u0, v1, LightTexture.FULL_BRIGHT);
        vertex(consumer, pose, end.add(sideOffset.scale(-1)), u1, v1, LightTexture.FULL_BRIGHT);
        vertex(consumer, pose, end.add(sideOffset), u1, v0, LightTexture.FULL_BRIGHT);
        stack.popPose();
    }

public void render(VertexConsumer consumer, Camera camera, float partialTick) {
        if (this.trailPointer > -1) {
            MultiBufferSource.BufferSource bufferSource = Minecraft.getInstance().renderBuffers().bufferSource();
            VertexConsumer vertexConsumer = bufferSource.getBuffer(RenderType.entityTranslucent(this.getTexture()));
            Vec3 cameraPos = camera.getPosition();
            double x = Mth.lerp(partialTick, this.xo, this.x);
            double y = Mth.lerp(partialTick, this.yo, this.y);
            double z = Mth.lerp(partialTick, this.zo, this.z);
            PoseStack poseStack = new PoseStack();
            poseStack.pushPose();
            poseStack.translate(-cameraPos.x, -cameraPos.y, -cameraPos.z);
            int samples = 0;
            Vec3 drawFrom = new Vec3(x, y, z);
            float zRot = this.getCameraRot(camera);
            Vec3 topAngleVec = (new Vec3(0.0, this.getTrailHeight() / 2.0D, 0.0)).zRot(zRot);
            Vec3 bottomAngleVec = (new Vec3(0.0, this.getTrailHeight() / -2.0D, 0.0)).zRot(zRot);

            while (samples < this.sampleSize()){
                Vec3 sample = this.getTrailPosition(samples * this.sampleStep(), partialTick);
                Vec3 draw1 = drawFrom;
                float u1 = (float)samples / (float)this.sampleSize();
                float u2 = u1 + 1.0F / (float)this.sampleSize();
                PoseStack.Pose last = poseStack.last();
                Matrix4f matrix4f = last.pose();
                Matrix3f matrix3f = last.normal();
                vertexConsumer.vertex(matrix4f, (float)draw1.x + (float)bottomAngleVec.x, (float)draw1.y + (float)bottomAngleVec.y, (float)draw1.z + (float)bottomAngleVec.z).color(this.rCol, this.gCol, this.bCol, this.trailA).uv(u1, 1.0F).overlayCoords(OverlayTexture.NO_OVERLAY).uv2(this.getLightColor(partialTick)).normal(matrix3f, 0.0F, 1.0F, 0.0F).endVertex();
                vertexConsumer.vertex(matrix4f, (float)sample.x + (float)bottomAngleVec.x, (float)sample.y + (float)bottomAngleVec.y, (float)sample.z + (float)bottomAngleVec.z).color(this.rCol, this.gCol, this.bCol, this.trailA).uv(u2, 1.0F).overlayCoords(OverlayTexture.NO_OVERLAY).uv2(this.getLightColor(partialTick)).normal(matrix3f, 0.0F, 1.0F, 0.0F).endVertex();
                vertexConsumer.vertex(matrix4f, (float)sample.x + (float)topAngleVec.x, (float)sample.y + (float)topAngleVec.y, (float)sample.z + (float)topAngleVec.z).color(this.rCol, this.gCol, this.bCol, this.trailA).uv(u2, 0.0F).overlayCoords(OverlayTexture.NO_OVERLAY).uv2(this.getLightColor(partialTick)).normal(matrix3f, 0.0F, 1.0F, 0.0F).endVertex();
                vertexConsumer.vertex(matrix4f, (float)draw1.x + (float)topAngleVec.x, (float)draw1.y + (float)topAngleVec.y, (float)draw1.z + (float)topAngleVec.z).color(this.rCol, this.gCol, this.bCol, this.trailA).uv(u1, 0.0F).overlayCoords(OverlayTexture.NO_OVERLAY).uv2(this.getLightColor(partialTick)).normal(matrix3f, 0.0F, 1.0F, 0.0F).endVertex();
                ++samples;
                drawFrom = sample;
            }

            bufferSource.endBatch();
            poseStack.popPose();
        }

    }

@SideOnly(Side.CLIENT)
	@SubscribeEvent
	public static void tick(TickEvent.ClientTickEvent event) {
		if (event.phase != TickEvent.Phase.END) return;
		World world = Minecraft.getMinecraft().world;
		if (world == null) return;

		List<EntityUnicorn> unicorns = world.getEntities(EntityUnicorn.class, input -> true);

		for (EntityUnicorn unicorn : unicorns) {
			if (unicorn == null) continue;
			if (unicorn.isDead) {
				positions.remove(unicorn);
				break;
			}

			positions.putIfAbsent(unicorn, new ArrayList<>());

			List<Point> poses = positions.get(unicorn);

			if ((poses.size() >= 1000 || world.getTotalWorldTime() % 20 == 0) && !poses.isEmpty()) {
				poses.remove(0);
			}

			double mot = 0.05;
			if (poses.size() < 1000) {
				if (unicorn.motionX >= mot || unicorn.motionX <= -mot
						|| unicorn.motionY >= mot || unicorn.motionY <= -mot
						|| unicorn.motionZ >= mot || unicorn.motionZ <= -mot) {

					Vec3d backCenter = unicorn.getPositionVector();
					Vec3d look = new Vec3d(unicorn.motionX, unicorn.motionY, unicorn.motionZ).normalize();
					backCenter = backCenter.add(look.scale(-1));

					Vec3d cross = look.crossProduct(new Vec3d(0, 1, 0)).normalize().scale(0.35f);
					poses.add(new Point(backCenter, cross, world.getTotalWorldTime()));
				} else if (!poses.isEmpty()) {
					poses.remove(0);
				}
			}
		}
	}

@SubscribeEvent
	@SideOnly(Side.CLIENT)
	public static void render(RenderWorldLastEvent event) {
		World world = Minecraft.getMinecraft().world;
		EntityPlayer player = Minecraft.getMinecraft().player;
		if (player == null || world == null) return;

		GlStateManager.pushMatrix();

		double interpPosX = player.lastTickPosX + (player.posX - player.lastTickPosX) * event.getPartialTicks();
		double interpPosY = player.lastTickPosY + (player.posY - player.lastTickPosY) * event.getPartialTicks();
		double interpPosZ = player.lastTickPosZ + (player.posZ - player.lastTickPosZ) * event.getPartialTicks();

		GlStateManager.translate(-interpPosX, -interpPosY + 0.1, -interpPosZ);

		GlStateManager.disableCull();
		GlStateManager.depthMask(false);
		GlStateManager.enableBlend();
		GlStateManager.disableTexture2D();
		GlStateManager.shadeModel(GL11.GL_SMOOTH);
		GlStateManager.blendFunc(GL_SRC_ALPHA, GL_ONE);
		GlStateManager.enableColorMaterial();
		GlStateManager.disableLighting();

		Tessellator tessellator = Tessellator.getInstance();
		BufferBuilder vb = tessellator.getBuffer();

		Set<EntityUnicorn> corns = new HashSet<>(positions.keySet());
		for (EntityUnicorn corn : corns) {
			if (corn.world.provider.getDimension() != world.provider.getDimension()) continue;

			List<Point> points = new ArrayList<>(positions.getOrDefault(corn, new ArrayList<>()));
			boolean q = false;

			vb.begin(GL11.GL_TRIANGLE_STRIP, DefaultVertexFormats.POSITION_COLOR);
			for (Point pos : points) {
				if (pos == null) continue;

				float sub = (world.getTotalWorldTime() - pos.time);
				Color color = Color.getHSBColor(sub % 360.0f / 360.0f, 1f, 1f);

				int alpha;
				if (sub < 500) {
					alpha = (int) (MathHelper.clamp(Math.log(sub + 1) / 2.0, 0, 1) * 80.0);
				} else {
					alpha = (int) (MathHelper.clamp(1 - (Math.log(sub) / 2.0), 0, 1) * 80.0);
				}

				pos(vb, pos.origin.subtract(pos.normal.scale(1.5))).color(color.getRed(), color.getGreen(), color.getBlue(), alpha).endVertex();
				pos(vb, pos.origin.add(pos.normal.scale(1.5))).color(color.getRed(), color.getGreen(), color.getBlue(), alpha).endVertex();
				q = !q;
			}

			tessellator.draw();
		}

		GlStateManager.enableCull();
		GlStateManager.depthMask(true);
		GlStateManager.disableBlend();
		GlStateManager.enableTexture2D();
		GlStateManager.shadeModel(GL11.GL_FLAT);
		GlStateManager.tryBlendFuncSeparate(GlStateManager.SourceFactor.SRC_ALPHA, GlStateManager.DestFactor.ONE_MINUS_SRC_ALPHA, GlStateManager.SourceFactor.ONE, GlStateManager.DestFactor.ZERO);

		GlStateManager.popMatrix();
	}

public static void renderAllInWorld(MatrixStack matrices, VertexConsumerProvider.Immediate vertexConsumers, Camera camera, int light, float delta) {
        var focusedEntity = camera.getFocusedEntity();
        if (focusedEntity == null) {
            return;
        }

        var world = MinecraftClient.getInstance().world;
        if (world == null) {
            return;
        }
        var renderDistance = MinecraftClient.getInstance().options.getViewDistance().getValue() * 24; // 24 = 16 * 1.5F
        var squaredRenderDistance = renderDistance * renderDistance;
        // Any entity exposing a cast process can beam (players and summons alike)
        var casters = new ArrayList<LivingEntity>();
        for (var entity : world.getEntities()) {
            if (entity instanceof LivingEntity livingEntity
                    && entity instanceof SpellCaster.Entity holder
                    && holder.getBeam() != null
                    && entity.squaredDistanceTo(focusedEntity) < squaredRenderDistance) {
                casters.add(livingEntity);
            }
        }
        if (casters.isEmpty()) {
            return;
        }

        matrices.push();
        Vec3d camPos = camera.getPos();
        matrices.translate(-camPos.x, -camPos.y, -camPos.z);
        for (var livingEntity : casters) {
            var launchHeight = LaunchGeometry.launchHeight(livingEntity);
            var offset = new Vec3d(0.0, launchHeight, LaunchGeometry.launchPointOffsetDefault);
            SpellCaster.Entity caster = (SpellCaster.Entity) livingEntity;
            matrices.push();
            var pos = new Vec3d(livingEntity.prevX, livingEntity.prevY, livingEntity.prevZ)
                    .lerp(livingEntity.getPos(), delta);
            matrices.translate(pos.x, pos.y, pos.z);

            Vec3d from = livingEntity.getPos().add(0, launchHeight, 0);
            var lookVector = Vec3d.ZERO;
            if (livingEntity == MinecraftClient.getInstance().player) {
                // No lerp for local player
                lookVector = Vec3d.fromPolar(livingEntity.getPitch(), livingEntity.getYaw());
            } else {
                lookVector = Vec3d.fromPolar(livingEntity.prevPitch, livingEntity.prevYaw);
                lookVector = lookVector.lerp(Vec3d.fromPolar(livingEntity.getPitch(), livingEntity.getYaw()), delta);
            }
            lookVector = lookVector.normalize();
            var beamPosition = TargetHelper.castBeam(livingEntity, lookVector, 32);
            lookVector = lookVector.multiply(beamPosition.length());
            Vec3d to = from.add(lookVector);

            var beamAppearance = caster.getBeam();
            renderBeamFromPlayer(matrices, vertexConsumers, beamAppearance,
                    from, to, offset, livingEntity.getWorld().getTime(), delta);
            ((BeamEmitterEntity)livingEntity).setLastRenderedBeam(new Beam.Rendered(beamPosition, beamAppearance));
            matrices.pop();
        }
        vertexConsumers.draw();
        matrices.pop();
    }

private static void renderBeamFromPlayer(MatrixStack matrixStack, VertexConsumerProvider vertexConsumerProvider,
                                             Spell.Target.Beam beam,
                                             Vec3d from, Vec3d to, Vec3d offset, long time, float tickDelta) {
        var absoluteTime = (float)Math.floorMod(time, 40) + tickDelta;

        matrixStack.push();
        matrixStack.translate(0, offset.y, 0);

        Vec3d beamVector = to.subtract(from);
        float length = (float)beamVector.length();

        // Perform some rotation
        beamVector = beamVector.normalize();
        float n = (float)Math.acos(beamVector.y);
        float o = (float)Math.atan2(beamVector.z, beamVector.x);
        matrixStack.multiply(RotationAxis.POSITIVE_Y.rotationDegrees((1.5707964F - o) * 57.295776F));
        matrixStack.multiply(RotationAxis.POSITIVE_X.rotationDegrees(n * 57.295776F));
        matrixStack.translate(0, offset.z, 0); // At this point everything is so rotated, we need to translate along y to move along z

        matrixStack.multiply(RotationAxis.POSITIVE_Y.rotationDegrees(absoluteTime * 2.25F - 45.0F));

        var texture = Identifier.of(beam.texture_id);
        var outerColor = Color.IntFormat.fromLongRGBA(beam.color_rgba);
        var innerColor = Color.IntFormat.fromLongRGBA(beam.inner_color_rgba);

        LayerSet renderLayers;
        if (ShaderCompatibility.isVanillaRenderSystem()) {
            renderLayers = vanilla(texture);
        } else {
            var luminance = ShaderCompatibility.isShaderPackInUse()
                    ? (SpellEngineClient.config.renderBeamsHighLuminance ? beam.luminance : Spell.Target.Beam.Luminance.MEDIUM)
                    : Spell.Target.Beam.Luminance.LOW;
            renderLayers = layerSetFor(texture, luminance);
        }
        BeamRenderer.renderBeam(matrixStack, vertexConsumerProvider,
                time, tickDelta, beam.flow, true,
                innerColor, outerColor, renderLayers,
                0, length, beam.width);

        matrixStack.pop();
    }

@Override
    public void render(@NotNull VertexConsumer vertex, Camera camera, float tick) {
        MultiBufferSource.BufferSource multibuffersource$buffersource = Minecraft.getInstance().renderBuffers().bufferSource();
        Vec3 vec3 = camera.getPosition();
        EntityRenderDispatcher entityRenderDispatcher = Minecraft.getInstance().getEntityRenderDispatcher();

        double lerpX = Mth.lerp(tick, this.xo, this.x);
        double lerpY = Mth.lerp(tick, this.yo, this.y);
        double lerpZ = Mth.lerp(tick, this.zo, this.z);
        float colorR = this.rCol / 255.0F;
        float colorG = this.gCol / 255.0F;
        float colorB = this.bCol / 255.0F;
        float colorA = 0.5F / Math.abs((float) age + 1);

        PoseStack stack = new PoseStack();
        Entity entity = this.getFromEntity();

        if (entity instanceof LivingEntity living) {
            EntityRenderer<? super LivingEntity> rendererRaw = entityRenderDispatcher.getRenderer(living);

            if (rendererRaw instanceof LivingEntityRenderer) {
                LivingEntityRenderer<LivingEntity, EntityModel<LivingEntity>> renderer = (LivingEntityRenderer<LivingEntity, EntityModel<LivingEntity>>) rendererRaw;
                java.util.function.Function<VertexConsumer, VertexConsumer> createTintedBuffer = (originalBuffer) -> new VertexConsumer() {
                    @Override
                    public VertexConsumer vertex(double x, double y, double z) {
                        originalBuffer.vertex(x, y, z);
                        return this;
                    }

                    @Override
                    public VertexConsumer color(int r, int g, int b, int a) {
                        originalBuffer.color(
                                (int) (r * colorR),
                                (int) (g * colorG),
                                (int) (b * colorB),
                                (int) (a * colorA)
                        );
                        return this;
                    }

                    @Override
                    public VertexConsumer uv(float u, float v) {
                        originalBuffer.uv(u, v);
                        return this;
                    }

                    @Override
                    public VertexConsumer overlayCoords(int u, int v) {
                        originalBuffer.overlayCoords(u, v); // 1.21.1의 setUv1 역할
                        return this;
                    }

                    @Override
                    public VertexConsumer uv2(int u, int v) {
                        originalBuffer.uv2(u, v); // 1.21.1의 setUv2 역할
                        return this;
                    }

                    @Override
                    public VertexConsumer normal(float x, float y, float z) {
                        originalBuffer.normal(x, y, z);
                        return this;
                    }

                    @Override
                    public void endVertex() {
                        originalBuffer.endVertex();
                    }

                    @Override
                    public void defaultColor(int r, int g, int b, int a) {
                        originalBuffer.defaultColor(
                                (int) (r * colorR),
                                (int) (g * colorG),
                                (int) (b * colorB),
                                (int) (a * colorA)
                        );
                    }

                    @Override
                    public void unsetDefaultColor() {
                        originalBuffer.unsetDefaultColor();
                    }
                };

                Minecraft minecraft = Minecraft.getInstance();
                boolean flag = !living.isInvisible();
                boolean flag1 = !flag && !living.isInvisibleTo(minecraft.player);
                boolean flag2 = minecraft.shouldEntityAppearGlowing(living);

                MultiBufferSource tintedSource = (requestedType) -> {
                    boolean hasTexture = requestedType.format().getElements().contains(DefaultVertexFormat.ELEMENT_UV0);
                    boolean hasNormal = requestedType.format().getElements().contains(DefaultVertexFormat.ELEMENT_NORMAL);

                    if (hasTexture && hasNormal) {
                        RenderType ghostType = this.getRenderType(living, renderer, flag, flag1, flag2);
                        VertexConsumer originalBuffer = multibuffersource$buffersource.getBuffer(ghostType);
                        return createTintedBuffer.apply(originalBuffer);
                    } else {
                        VertexConsumer originalBuffer = multibuffersource$buffersource.getBuffer(requestedType);
                        return createTintedBuffer.apply(originalBuffer);
                    }
                };

                entityRenderDispatcher.render(living,
                        lerpX - vec3.x(), lerpY - vec3.y(), lerpZ - vec3.z(),
                        living.getYRot(), tick, stack, tintedSource, entityRenderDispatcher.getPackedLightCoords(living, tick));
            }
        }
    }

public void render(VertexConsumer vertexConsumer, Camera camera, float partialTick) {
        Vec3 vec3 = camera.getPosition();
        PoseStack posestack = new PoseStack();
        MultiBufferSource.BufferSource multibuffersource$buffersource = Minecraft.getInstance().renderBuffers().bufferSource();
        float f = (float)(Mth.lerp((double)partialTick, this.xo, this.x) - vec3.x());
        float f1 = (float)(Mth.lerp((double)partialTick, this.yo, this.y) - vec3.y());
        float f2 = (float)(Mth.lerp((double)partialTick, this.zo, this.z) - vec3.z());
        float lerpAge = this.age + partialTick;
        float ageProgress = lerpAge / (float) this.lifetime;
        float scale = 1.85F;
        posestack.pushPose();
        posestack.translate(f, f1, f2);
        posestack.scale(scale, scale, scale);
        LightningBoltData.BoltRenderInfo lightningBoltData = new LightningBoltData.BoltRenderInfo(0.5F, 0.1F, 0.5F, 0.85F, new Vector4f(rCol /255, gCol /255, bCol /255, (1.0F - ageProgress) * 0.8F), 0.1F);
        LightningBoltData bolt = new LightningBoltData(lightningBoltData, Vec3.ZERO, new Vec3(toX, toY, toZ), 4)
                .size(0.05F)
                .lifespan(this.lifetime)
                .spawn(LightningBoltData.SpawnFunction.CONSECUTIVE);
        lightningRender.update(this, bolt, partialTick);
        lightningRender.render(partialTick, posestack, multibuffersource$buffersource);

        multibuffersource$buffersource.endBatch();
        posestack.popPose();
    }

@Override
    public void render(VertexConsumer buffer, Camera camera, float partialTicks) {
        Vec3 vec3 = camera.getPosition();
        float f = (float)(Mth.lerp((double)partialTicks, this.xo, this.x) - vec3.x());
        float f1 = (float)(Mth.lerp((double)partialTicks, this.yo, this.y) - vec3.y());
        float f2 = (float)(Mth.lerp((double)partialTicks, this.zo, this.z) - vec3.z());
        Quaternionf quaternionf = new Quaternionf();
        quaternionf.rotateY((float) Math.toRadians(-camera.getYRot()));

        Vector3f[] avector3f = new Vector3f[]{new Vector3f(-1.0F, -1.0F, 0.0F), new Vector3f(-1.0F, 1.0F, 0.0F), new Vector3f(1.0F, 1.0F, 0.0F), new Vector3f(1.0F, -1.0F, 0.0F)};
        float f3 = this.getQuadSize(partialTicks);

        for(int i = 0; i < 4; ++i) {
            Vector3f vector3f = avector3f[i];
            vector3f.rotate(quaternionf);
            vector3f.mul(f3);
            vector3f.add(f, f1, f2);
        }

        float f6 = this.getU0();
        float f7 = this.getU1();
        float f4 = this.getV0();
        float f5 = this.getV1();
        int j = this.getLightColor(partialTicks);
        buffer.vertex(avector3f[0].x(), avector3f[0].y(), avector3f[0].z()).uv(f7, f5).color(this.rCol, this.gCol, this.bCol, this.alpha).uv2(j).endVertex();
        buffer.vertex(avector3f[1].x(), avector3f[1].y(), avector3f[1].z()).uv(f7, f4).color(this.rCol, this.gCol, this.bCol, this.alpha).uv2(j).endVertex();
        buffer.vertex(avector3f[2].x(), avector3f[2].y(), avector3f[2].z()).uv(f6, f4).color(this.rCol, this.gCol, this.bCol, this.alpha).uv2(j).endVertex();
        buffer.vertex(avector3f[3].x(), avector3f[3].y(), avector3f[3].z()).uv(f6, f5).color(this.rCol, this.gCol, this.bCol, this.alpha).uv2(j).endVertex();


    }

public void render(Bolt_strike_Entity entity, float p_115267_, float partialTicks, PoseStack poseStack, MultiBufferSource p_115270_, int p_115271_) {
        double x = Mth.lerp(partialTicks, entity.xOld, entity.getX());
        double y = Mth.lerp(partialTicks, entity.yOld, entity.getY());
        double z = Mth.lerp(partialTicks, entity.zOld, entity.getZ());

        int r = entity.getR();
        int g = entity.getG();
        int b = entity.getB();

        float f = entity.getAnimationProgress(partialTicks);
        float f1 = 0.0F;
        if (f != 0.0F) {
            f1 = f;

            poseStack.pushPose();

            poseStack.translate(-x, -y, -z);
            LightningBoltData.BoltRenderInfo boltData = new LightningBoltData.BoltRenderInfo(0.2f, 0.7f, 0.25F, 0.15F, new Vector4f((float) r / 255, (float) g / 255, (float) b / 255, 0.7F), 0.92F);
            LightningBoltData bolt1 = new LightningBoltData(boltData, entity.getAnglePosition(partialTicks,MAX_HEIGHT,START_MAX_RADIUS,START_MIN_RADIUS), entity.getAnglePosition(partialTicks,0,END_MAX_RADIUS,END_MIN_RADIUS), 4)
                    .size(f1)
                    .lifespan(1)
                    .spawn(LightningBoltData.SpawnFunction.NO_DELAY)
                    .fade(LightningBoltData.FadeFunction.NONE);
            LightningRender lightningRender = getLightingRender(entity.getUUID());
            if (!Minecraft.getInstance().isPaused()) {
                lightningRender.update(entity, bolt1, partialTicks);
            }
            lightningRender.render(partialTicks, poseStack, p_115270_);

            poseStack.popPose();
        }
        if (entity.isRemoved() && lightningRenderMap.containsKey(entity.getUUID())) {
            lightningRenderMap.remove(entity.getUUID());
        }
    }

