public List<Pair<RenderType, Consumer<VertexConsumer>>> render(float partialTicks, PoseStack matrixStack)
	{
		float mod = (age+partialTicks)/(float)lifetime;
		int iStartMut = 0;
		int iEndMut = pointsList.length;
		if(mod >= .76)
		{
			float rem = (((mod-.7599f)%.25f)*48)/2f;
			iStartMut += Math.ceil(rem);
			iEndMut -= Math.floor(rem);
		}
		final int iStart = iStartMut;
		final int iEnd = iEndMut;
		mod = .3f+mod*mod;
		matrixStack.pushPose();
		matrixStack.translate(x, y, z);
		matrixStack.scale(mod, mod, mod);
		matrixStack.mulPose(new Quaternionf().rotateXYZ(0, Mth.PI*mod, 0));
		Matrix4f transform = matrixStack.last().pose();
		Matrix3f transformN = matrixStack.last().normal();
		matrixStack.popPose();

		LinePointProcessor putLinePoint = (buffer, i, color) -> {
			int correctIndex = getCyclicIndexInRange(iStart, iEnd, i);
			Vector3f vecRender = pointsList[correctIndex];
			if(i!=iStart)
			{
				Vector3f last = pointsList[getCyclicIndexInRange(iStart, iEnd, i-1)];
				renderLinePoint(transformN, transform, vecRender, last, color, buffer, false);
			}
			if(i!=iEnd)
			{
				Vector3f next = pointsList[getCyclicIndexInRange(iStart, iEnd, i+1)];
				renderLinePoint(transformN, transform, next, vecRender, color, buffer, true);
			}
		};

		List<Pair<RenderType, Consumer<VertexConsumer>>> ret = new ArrayList<>();
		ret.add(Pair.of(IERenderTypes.getParticleLines(4f), buffer -> {
			for(int i = iStart; i <= iEnd; i++)
				putLinePoint.draw(buffer, i, colourOut);
		}));

		ret.add(Pair.of(IERenderTypes.getParticleLines(1f), buffer -> {
			for(int i = iStart; i <= iEnd; i++)
				putLinePoint.draw(buffer, i, colourIn);
		}));

		ret.add(Pair.of(IERenderTypes.POINTS, buffer -> {
			for(int i = iStart; i < iEnd; i++)
				drawPoint(buffer, transform, pointsList[i], 8, colourOut);
		}));

		ret.add(Pair.of(IERenderTypes.POINTS, buffer -> {
			for(int i = iEnd-1; i >= iStart; i--)
				drawPoint(buffer, transform, pointsList[i], 2, colourIn);
		}));
		return ret;
	}

@Override
	public void render(AreaOfEffect entity, float yaw, float tickDelta, PoseStack poseStack, MultiBufferSource vertices, int light) {
		super.render(entity, yaw, tickDelta, poseStack, vertices, light);
		Color color = ArcanusHelper.getMagicColor(entity);
		float alpha = 1 - (Mth.clamp(entity.getTrueAge() - (70 * 0.9f), 0f, 10f) / 10f);
		float r = color.redF() * alpha;
		float g = color.greenF() * alpha;
		float b = color.blueF() * alpha;
		color = Color.fromFloatsRGB(r, g, b);

		poseStack.pushPose();
		poseStack.mulPose(Axis.XP.rotationDegrees(180));
		poseStack.translate(0, -1.51, 0);
		model.base.yRot = (entity.tickCount + tickDelta) * 0.015f;
		model.pillar.yRot = -model.base.yRot;
		model.walls.yRot = -(entity.tickCount + tickDelta) * 0.035f;
		model.renderToBuffer(poseStack, vertices.getBuffer(ArcanusClient.getMagicCircles(TEXTURE)), light, OverlayTexture.NO_OVERLAY, color.asIntARGB());
		poseStack.popPose();
	}

@Override
	public void render(TemporalDilationField entity, float entityYaw, float partialTick, PoseStack poseStack, MultiBufferSource buffer, int packedLight) {
		super.render(entity, entityYaw, partialTick, poseStack, buffer, packedLight);
		Minecraft client = Minecraft.getInstance();
		Color color = ArcanusHelper.getMagicColor(entity);
		Vec3 cameraPos = client.getCameraEntity() != null ? new Vec3(client.getCameraEntity().getX(), 0, client.getCameraEntity().getZ()) : Vec3.ZERO;
		Vec3 fieldPos = new Vec3(entity.getX(), 0, entity.getZ());
		Vec3 directionToCamera = cameraPos.subtract(fieldPos);
		float handProgress = (float) Math.toRadians((360f / entity.getMaxAge()) * entity.getAge() + partialTick);

		poseStack.pushPose();
		poseStack.mulPose(Axis.XP.rotationDegrees(180));
		poseStack.scale(3, 3, 3);
		poseStack.translate(0, -3.01, 0);

		model.xPlaneRing.yRot = (float) Mth.atan2(directionToCamera.z(), directionToCamera.x());
		model.xClockHand.xRot = -handProgress;
		model.yClockHand.yRot = handProgress;

		model.renderToBuffer(poseStack, buffer.getBuffer(ArcanusClient.getMagicCircles(TEXTURE)), packedLight, OverlayTexture.NO_OVERLAY, color.asIntARGB());
		poseStack.popPose();
	}

public void renderAt(TileAlchemyArray tileArray, double x, double y, double z, float craftTime, PoseStack matrixStack, MultiBufferSource renderer, int combinedLightIn, int combinedOverlayIn)
	{
		matrixStack.pushPose();

		matrixStack.translate(0.5, 0.5, 0.5);

		float rot = getRotation(-1, craftTime);
		float secondaryRot = getSecondaryRotation(craftTime);

		float size = 3;
		Direction dirRotation = tileArray.getRotation();

		matrixStack.pushPose();
		matrixStack.translate(0, getVerticalOffset(craftTime), 0);
		matrixStack.mulPose(Axis.YP.rotationDegrees( -dirRotation.toYRot()));

		matrixStack.pushPose();

		matrixStack.mulPose(Axis.YP.rotationDegrees( rot));
//		matrixStack.rotate(new Quaternion(Direction.NORTH.toVector3f(), secondaryRot, true));
//		matrixStack.rotate(new Quaternion(Direction.EAST.toVector3f(), secondaryRot * 0.45812f, true));

		VertexConsumer twoDBuffer = renderer.getBuffer(RenderType.entityTranslucent(arrayResource));
		Model2D arrayModel = new BloodMagicRenderer.Model2D();
		arrayModel.minX = -0.5;
		arrayModel.maxX = +0.5;
		arrayModel.minY = -0.5;
		arrayModel.maxY = +0.5;
		arrayModel.resource = arrayResource;

		matrixStack.scale(size, size, size);

		RenderResizableQuadrilateral.INSTANCE.renderSquare(arrayModel, matrixStack, twoDBuffer, 0xFFFFFFFF, combinedLightIn, combinedOverlayIn);

		matrixStack.popPose();

		for (int i = 0; i < 5; i++)
		{
			matrixStack.pushPose();

			float newSize = 1;
			float distance = BindingAlchemyCircleRenderer.getDistanceOfCircle(i, craftTime);
			float angle = BindingAlchemyCircleRenderer.getAngleOfCircle(i, craftTime);
			float rotation = this.getRotation(i, craftTime);

			matrixStack.translate(distance * Math.sin(angle), this.getVerticalOffset(i, craftTime), -distance * Math.cos(angle));
			matrixStack.mulPose(Axis.YP.rotationDegrees( i * 360 / 5 ));
			matrixStack.mulPose(Axis.ZN.rotationDegrees( getInwardRotation(i, craftTime)));
			matrixStack.mulPose(Axis.YP.rotationDegrees( rotation ));
			twoDBuffer = renderer.getBuffer(RenderType.entityTranslucent(arraysResources[i]));
			arrayModel.resource = arraysResources[i];

			matrixStack.scale(newSize, newSize, newSize);

			RenderResizableQuadrilateral.INSTANCE.renderSquare(arrayModel, matrixStack, twoDBuffer, 0xFFFFFFFF, combinedLightIn, combinedOverlayIn);

			matrixStack.popPose();
		}

		matrixStack.popPose();
		matrixStack.popPose();
	}
